local _, ns = ...
local E = ns.DB.entries
E["npc:brainwashed-noble"] = {t="npc",n="Brainwashed Noble",z="westfall",s="The Brainwashed Noble is an elusive, captive aristocrat found deep within the subterranean caverns outside the Deadmines in Westfall. Stripped of his autonomy through magical manipulation, he serves the Defias Brotherhood alongside undead minions rather than walking the grand halls of Stormwind.",h="The Brainwashed Noble is an elusive, captive aristocrat found deep within the subterranean caverns outside...",sec={{t="A Pawn of the Brotherhood",b="Wandering the murky, bone-littered passages leading into the Deadmines, the Brainwashed Noble presents a jarring contrast to the desperate bandits and rotting corpses that surround him. Clad in remnants of highborn finery, he was almost certainly a sitting member or scion of Stormwind's House of Nobles before falling into Edwin VanCleef's hands. Rather than ransom him for gold, the Defias have bent his mind with enchantments, turning a member of the ruling class into a spellcasting guard for their secret sanctuary. His tragic presence speaks volumes about the lengths the Brotherhood will go to inflict revenge upon the peers who refused to pay them.",sp=0}},faq={{q="Who is the Brainwashed Noble?",a="He is an aristocratic human, presumed to be from Stormwind's House of Nobles, who has been captured and magically subjugated by the Defias Brotherhood deep within the Deadmines caverns.",al={"who is brainwashed noble","what is brainwashed noble","noble in deadmines"}},{q="Why is a Stormwind noble inside the Deadmines caves?",a="The Defias Brotherhood harbors a bitter vendetta against the Stormwind aristocracy over unpaid debts after rebuilding the city. Capturing, enslaving, and twisting the mind of a noble serves both as useful magical labor and as personal vengeance.",al={"why is he in deadmines","why is noble in caves"}},{q="Where can the Brainwashed Noble be found?",a="He is an uncommon sight in the sprawling cavern tunnels of Moonbrook that lead down toward the Deadmines entrance, specifically haunting the passages inhabited by skeletal undead.",al={"brainwashed noble location","where does he spawn"}},{q="How was he brainwashed?",a="While the exact caster remains unstated, the Defias employ several renegade spellcasters and enchanters throughout Westfall who are fully capable of bending a captive's mind through coercive sorcery.",al={"who brainwashed him","how is he controlled"}}},ang={["race:Human"]="Seeing a peer of the realm reduced to a mindless sentry deep beneath Westfall is a chilling reminder of the visceral grudge the Defias Brotherhood holds against Stormwind's ruling elite.",["class:Mage"]="The noble relies on magical staves and arcane tricks like Polymorph, suggesting he possessed formal magical education in the capital before his mind was shattered."},kw={"brainwashed noble","deadmines","defias brotherhood","house of nobles","moonbrook","stormwind","westfall"},rel={"subzone:deadmines","topic:house-of-nobles","topic:defias-brotherhood","zone:westfall","zone:deadmines","topic:stormwind-kingdom","quest:65","topic:human"},src={"Brainwashed Noble"}}
E["npc:captain-danuvin"] = {t="npc",n="Captain Danuvin",z="westfall",s="Captain Danuvin is an officer stationed at Sentinel Hill in Westfall, serving as one of the leaders tasked with holding the frontier together. Working alongside the People's Militia, he directs volunteers and recruits to patrol the roads and push back against encroaching Gnolls and outlaws. His commands are vital to keeping the supply lines and farmlands from falling completely into hostile hands.",h="Captain Danuvin is an officer stationed at Sentinel Hill in Westfall, serving as one of the leaders tasked...",sec={{t="Holding the Hill",b="Perched at the fortified tower of Sentinel Hill, Captain Danuvin coordinates ground patrols across Westfall. The region has spiraled into chaos with the withdrawal of regular Stormwind garrison troops, leaving local defenses severely depleted. Danuvin relies heavily on wandering adventurers, local farmhands, and volunteer fighters to maintain even a semblance of order across the grassy plains.",sp=0},{t="Patrolling the Frontier",b="Danuvin's immediate strategic concern is the security of the roadways and open lands around Sentinel Hill. With the Riverpaw Gnolls growing bolder and raiding close to central outposts, he organizes active patrols to cull their packs and secure the perimeter. His orders help prevent the encampment from being entirely surrounded by Westfall's opportunists and marauders.",sp=0}},faq={{q="Where can I find Captain Danuvin?",a="Captain Danuvin is stationed at Sentinel Hill, the primary Alliance outpost located in central Westfall. He is usually found standing near the hill's fortified tower overlooking the road.",al={"danuvin location","where is captain danuvin","danuvin westfall"}},{q="What faction does Captain Danuvin represent?",a="Danuvin serves the Alliance and works directly in support of the local defense forces in Westfall, collaborating closely with Gryan Stoutmantle and the People's Militia.",al={"danuvin faction","who does danuvin serve"}},{q="What duties does he assign to adventurers?",a="Danuvin tasks recruits with securing the countryside, primarily through orders like patrolling the plains and driving back the aggressive Riverpaw Gnoll packs encroaching on Sentinel Hill.",al={"danuvin quests","what does captain danuvin want","patrolling westfall quest"}},{q="Why is Danuvin relying on volunteers instead of the Stormwind Army?",a="Stormwind's royal court has refused to commit official garrison troops to defend Westfall, citing budget shortfalls and political discord. Danuvin and the rest of the leadership at Sentinel Hill have no choice but to rely on mercenaries and militia recruits.",al={"why no stormwind army","why militia","stormwind garrison westfall"}},{q="Does Danuvin have connections outside of Westfall?",a="As an officer tracking the regional defense of southern human lands, Danuvin monitors threats across nearby borders, including the plight of Redridge Mountains and Darkshire, often pointing seasoned fighters toward neighboring zones in need of aid.",al={"danuvin redridge","danuvin connections"}},{q="What is his role compared to Gryan Stoutmantle?",a="While Gryan Stoutmantle oversees the broad defense strategy and leadership of the People's Militia, Captain Danuvin acts as a field officer managing tactical concerns, road patrols, and the immediate gnoll threat around the base.",al={"stoutmantle vs danuvin","is danuvin in charge"}}},ang={["faction:Alliance"]="Captain Danuvin represents one of the few standing military figures striving to uphold order in Westfall despite the crown's neglect, offering Alliance recruits steady work defending the realm.",["class:Warrior"]="Danuvin respects martial discipline and direct frontline action, valuing warriors who are willing to charge into gnoll packs and clear the highway through brute strength.",["race:Human"]="For humans of the kingdom, assisting Danuvin is a matter of homeland survival, ensuring the breadbasket of Stormwind is not permanently lost to raiders and beasts."},kw={"captain danuvin","danuvin","gryan stoutmantle","patrolling westfall","peoples militia","riverpaw","sentinel hill","westfall"},rel={"subzone:sentinel-hill","zone:westfall","quest:102","quest:12","zone:redridge"},src={"Captain Danuvin"}}
E["npc:captain-grayson"] = {t="npc",n="Captain Grayson",z="westfall",s="Captain Grayson is the restless spirit of a pirate captain stationed at the Westfall Lighthouse. Having lost his own life when his ship smashed against the dark coastline, he now watches over the beacon to prevent other sailors from suffering his fate.",h="Captain Grayson is the restless spirit of a pirate captain stationed at the Westfall Lighthouse.",sec={{t="A Life Cut Short by the Rocks",b="In life, Grayson captained a vessel along the perilous southern seas of the Eastern Kingdoms. His voyage came to a violent end off the jagged shoals of Westfall on a night when the lighthouse fire had gone dark. Cast upon the rocks, Grayson perished alongside his ship, only to awaken as an earthbound phantom trapped upon the coast.",sp=0},{t="Tragedy at the Beacon",b="Drawn to the Westfall Lighthouse in death, Grayson hoped to find answers about the afterlife. Instead, he witnessed sheer tragedy. A notorious murloc known as Old Murk-Eye drove the lighthouse keeper and his family away. Though the keepers bravely returned to rekindle the flame, Old Murk-Eye rallied the surrounding murlocs for a second, brutal slaughter. Grayson could only watch helplessly as the family was butchered.",sp=0},{t="A Ghostly Vigil",b="With the keepers dead and Westfall crumbling under neglect, Captain Grayson took the solemn burden of the beacon upon his spectral shoulders. He seeks aid from passing adventurers to gather fuel for the great flame and avenge the slaughtered family by hunting down Old Murk-Eye and driving back the coastal murloc tide.",sp=0}},faq={{q="Who is Captain Grayson?",a="Captain Grayson is a human ghost pirate residing at the Westfall Lighthouse. After wrecking on the coast because the beacon went out, his spirit took it upon himself to maintain the light and protect passing mariners.",al={"grayson identity","who is the ghost pirate","lighthouse ghost"}},{q="How did Captain Grayson die?",a="He died when his pirate vessel was driven onto the treacherous rocks along Westfall's shore. The lighthouse was dark that night, giving him and his crew no warning before their ship was torn apart.",al={"grayson death","how did grayson become a ghost","what killed captain grayson"}},{q="What happened to the real lighthouse keeper?",a="The keeper and his family were attacked by coastal murlocs. Though they escaped the initial assault and returned to relight the beacon, Old Murk-Eye rallied a second raid and slaughtered them all before Grayson's eyes.",al={"where is the lighthouse keeper","what happened to the keepers","lighthouse family"}},{q="Who is Old Murk-Eye?",a="Old Murk-Eye is a cunning and vicious murloc chieftain stalking the Westfall shoreline. He led the assault that killed the lighthouse keeper's family and poses a constant threat to anyone attempting to keep the beacon lit.",al={"murk eye lore","old murk eye","murloc leader westfall"}},{q="Why does Grayson want the lighthouse kept lit?",a="Having drowned because the coastline was pitch black, Grayson considers it his solemn duty in the afterlife to ensure no other sailors meet that same fate upon the shoals.",al={"grayson motivation","why light the beacon"}},{q="Is Captain Grayson hostile to adventurers?",a="No. Despite his pirate background in life, Grayson harbors no ill will toward the living. He has witnessed too much slaughter and seeks only peace and assistance in tending the flame.",al={"is grayson friendly","grayson hostile"}}},ang={["faction:Alliance"]="With the Defias Brotherhood choking Westfall and Stormwind neglecting its borders, it falls to visiting Alliance travelers to answer Grayson's plea and secure the lighthouse flame.",["class:Paladin"]="Though Grayson is an undead spirit, his purpose is selfless and protective. Assisting him honors the sacred duty of defending the helpless and purging the murderous tides of murlocs.",["class:Priest"]="Grayson's spirit is anchored by guilt and grief over watching an innocent family die. Offering aid brings a measure of solace to his restless soul."},kw={"captain grayson","ghost pirate","grayson","lighthouse","old murk-eye","westfall","westfall lighthouse"},rel={"subzone:westfall-lighthouse","quest:103","quest:104","quest:152","zone:westfall","topic:murloc","topic:pirate","topic:alliance"},src={"Captain Grayson"}}
E["npc:farmer-furlbrow"] = {t="npc",n="Farmer Furlbrow",z="westfall",s="Farmer Theodore Furlbrow is an evicted Westfall pumpkin farmer stranded alongside his wife Verna on the road near the Jansen Stead. Driven from their home by the Defias Brotherhood, the couple is trying to repair their broken wagon and flee into Elwynn Forest.",h="Farmer Theodore Furlbrow is an evicted Westfall pumpkin farmer stranded alongside his wife Verna on the road...",sec={{t="A Life Packed on a Wagon",b="Theodore Furlbrow once cultivated a pumpkin patch in northern Westfall, but the rising criminal tide forced him and his wife, Verna, to abandon everything they owned. Gathering whatever they could salvage, they set out toward the safety of Elwynn Forest, urging neighbors like Farmer Saldean to follow suit. Disaster struck along the road near the Jansen Stead when their wagon broke down, leaving them stranded in plain sight of bandits and wild beasts. While Verna tends to their beloved horse Old Blanchy, Theodore watches the road with growing despair, desperate to recover cherished possessions—such as the pocket watch given to him by Verna's father on their wedding day—and hoping to warn Sentinel Hill about the bandits closing in.",sp=0},{t="Evidence of Land Seizure",b="When Furlbrow fled his farm, he left behind critical legal paperwork, including the deed to his property. Adventurers who explore the overrun farmsteads often discover these abandoned documents, providing tangible proof of how the Defias Brotherhood drove honest working folk off their land. Gryan Stoutmantle and the People's Militia rely on such evidence to catalog the scope of the thieves' rebellion across the province.",sp=1}},faq={{q="Who is Farmer Furlbrow?",a="Theodore Furlbrow is a displaced pumpkin farmer from northern Westfall. He and his wife Verna were forced off their homestead by the Defias Brotherhood and are currently stranded beside their broken wagon near the Jansen Stead.",al={"farmer furlbrow","theodore furlbrow","who is furlbrow"}},{q="Why is Farmer Furlbrow stranded on the road?",a="While fleeing Westfall for the safety of Elwynn Forest, his wagon suffered a breakdown. Until he can fix the wagon or find help, he and his wife are stuck squatting along the roadside with their old horse, Blanchy.",al={"why is his wagon broken","why is furlbrow on the road","broken cart westfall"}},{q="What heirloom did Farmer Furlbrow lose?",a="During their rushed flight from the farm, Theodore left behind a cherished pocket watch given to him by Verna's father on their wedding day. He asks travelers brave enough to navigate the bandit-infested farmsteads to bring it back to him.",al={"forgotten heirloom watch","furlbrow watch","pocket watch"}},{q="Does Farmer Furlbrow have any family outside Westfall?",a="Theodore has a brother who works as a horsehand far to the north in Tarren Mill, in the Hillsbrad Foothills.",al={"furlbrow family","furlbrow brother"}}},ang={["faction:Alliance"]="Theodore Furlbrow's plight represents the complete breakdown of civil authority in Westfall, where loyal citizens of the realm must abandon their homes with no royal soldiers to defend them."},kw={"blanchy","defias","furlbrow","heirloom","jansen","pumpkin","theodore","verna","wagon","watch"},rel={"npc:verna-furlbrow","quest:64","quest:184","quest:109","subzone:jansen-stead","npc:gryan-stoutmantle","topic:defias-brotherhood","zone:westfall"},src={"Farmer Furlbrow"}}
E["npc:farmer-saldean"] = {t="npc",n="Farmer Saldean",z="westfall",s="Farmer Saldean is a resilient human homesteader residing at Saldean's Farm in central Westfall alongside his wife, Salma. Unlike many neighboring farmers who fled or gave up, Saldean stubbornly tends his troubled fields in the face of rogue harvest golems and mounting banditry.",h="Farmer Saldean is a resilient human homesteader residing at Saldean's Farm in central Westfall alongside his...",sec={{t="Holding the Plow",b="Farmer Saldean remembers when Westfall was considered the lushest breadbasket this side of Stranglethorn Vale. Those prosperous years have crumbled into dust. Surrounded by overgrown fields, rampaging mechanical harvest watchers, and predatory bandits, Saldean refuses to yield his land. While other homesteaders abandoned their acres or turned to thievery, he and his wife Salma remain determined to harvest what little grain they can. Driven to practical desperation, he recruits wandering adventurers to dismantle the rogue harvest golems scouring his fields so he can salvage their parts and clear his soil for planting.",sp=0},{t="The Scythe of Westfall",b="Saldean's stubborn defense of his homestead makes him one of the few surviving anchors of civilian life between Sentinel Hill and the northern bridge. Despite his harsh circumstances, he maintains ties with the People's Militia, sending able-bodied travelers along to Gryan Stoutmantle once his own immediate troubles are settled. Saldean knows all too well that clearing out wild harvest reapers will only buy his farm temporary reprieve unless the broader lawlessness strangling the countryside is dealt with.",sp=0}},faq={{q="Who is Farmer Saldean?",a="Saldean is a veteran human farmer residing at Saldean's Farm in Westfall with his wife, Salma. He is one of the few local homesteaders stubbornly refusing to abandon his soil despite famine, rogue harvest golems, and the region's spiraling banditry.",al={"saldean","who is saldean","saldean npc"}},{q="Why is Farmer Saldean's farm in trouble?",a="Westfall's automated harvest golems have malfunctioned and gone wild, prowling the cropland and attacking anyone in sight. Saldean needs adventurers to hunt down the mechanical watchers and reap their parts so he can reclaim his wheat fields.",al={"why are harvest golems attacking","saldean farm problem"}},{q="Where can Farmer Saldean be found?",a="He is located outside his farmhouse at Saldean's Farm, situated right off the main road in central Westfall, just north of Sentinel Hill.",al={"saldean location","where is saldean","saldean farm location"}},{q="Does Saldean support the People's Militia?",a="Yes. While Saldean focuses entirely on defending his crops and home, he directs capable adventurers down the road to Gryan Stoutmantle at Sentinel Hill to assist the People's Militia in defending the region.",al={"saldean gryan stoutmantle","saldean militia"}},{q="What unique items does Saldean sell?",a="Saldean sells staple bread and is the primary purveyor of Special Chicken Feed, a curious grain sought after by travelers hoping to befriend the local fowl wandering Westfall.",al={"saldean vendor","special chicken feed vendor"}}},ang={["faction:Alliance"]="Saldean exemplifies the stubborn resolve of Westfall's remaining loyalists, clinging to Kingdom soil even when the crown's soldiers are nowhere to be seen.",["profession:Cooking"]="Farmers like Saldean are the crumbling backbone of Stormwind's food supply; securing his crop keeps basic bread on tables across the kingdom."},kw={"chicken feed","farmer saldean","harvest watcher","saldean","saldean's farm","salma","the killing fields","westfall"},rel={"subzone:saldean-s-farm","quest:9","quest:109","npc:gryan-stoutmantle","zone:westfall","topic:stormwind-kingdom","topic:defias-brotherhood","zone:stranglethorn"},src={"Farmer Saldean"}}
E["npc:foreman-thistlenettle"] = {t="npc",n="Foreman Thistlenettle",z="westfall",s="Foreman Thistlenettle was once a dwarven overseer representing both the Miners' League and the Explorers' League within the depths of Westfall. After a catastrophic cave-in trapped his crew in the subterranean tunnels of the Deadmines, he perished alongside his workers and rose again as an undead ghoul. He now wanders the dark, collapsed corridors, unrecognizable to all except by the guild badge he still carries.",h="Foreman Thistlenettle was once a dwarven overseer representing both the Miners' League and the Explorers'...",sec={{t="Tragedy in the Deadmines",b="Before the Defias Brotherhood took total control of the Deadmines, legitimate mining expeditions delved deep into its rich veins. Foreman Thistlenettle oversaw one such venture on behalf of the Miners' League and Explorers' League. Deep in the tunnels beneath Moonbrook, disaster struck when a violent cave-in sealed his party off from the surface. The trapped miners died in the darkness, but their rest did not last; a sinister, necrotic taint raised Thistlenettle and his crew as ravenous ghouls to stalk the shadowed passages.",sp=0},{t="A Brother's Grief",b="Back in Stormwind, his brother Wilder Thistlenettle spent restless months wondering about the fate of the missing mining crew. With no word escaping the occupied tunnels, rumors eventually surfaced that the fallen overseer still walked among the dead. Adventurers braving the outskirts of the Deadmines are asked to locate the undead foreman, end his torment, and recover his badge to bring closure to his grieving kin.",sp=1}},faq={{q="Who was Foreman Thistlenettle before he died?",a="He was a dwarven foreman associated with both the Miners' League and the Explorers' League. He led a crew of miners into the Deadmines prior to its complete fortification by outlaws, looking to excavate and survey the subterranean veins.",al={"thistlenettle lore","who is foreman thistlenettle","thistlenettle background"}},{q="Why is Foreman Thistlenettle an undead ghoul?",a="A catastrophic cave-in collapsed the tunnels around Thistlenettle and his mining party, killing them. Dark subterranean energies or lingering necromancy within the labyrinthine mines subsequently animated their remains, turning the dwarves into restless ghouls.",al={"why is he a ghoul","how did thistlenettle die","thistlenettle undead"}},{q="Where is Foreman Thistlenettle located?",a="He haunts a dead-end, collapsed tunnel within the exterior maze of the Deadmines, located before the portal to the inner instance itself, surrounded by his reanimated former miners.",al={"where to find thistlenettle","thistlenettle location","deadmines foreman spot"}},{q="Who is looking for Foreman Thistlenettle?",a="His brother, Wilder Thistlenettle, who resides in the Dwarven District of Stormwind City. Wilder seeks proof of his brother's fate and asks travelers to bring back Thistlenettle's Badge.",al={"who wants thistlenettle dead","wilder brother","thistlenettle quest giver"}}},ang={["race:Dwarf"]="The tragic loss of an Explorers' League foreman and an entire dwarven crew highlights the lingering dangers lurking beneath the human kingdoms.",["profession:Mining"]="Thistlenettle's fate is a somber reminder to all miners of the ever-present peril of tunnel collapses and hostile subterranean depths."},kw={"badge","cave-in","deadmines","foreman","ghoul","miners' league","thistlenettle","wilder"},rel={"npc:wilder-thistlenettle","quest:167","zone:deadmines","subzone:deadmines","topic:explorers-league","zone:westfall"},src={"Foreman Thistlenettle"}}
E["npc:grimbooze-thunderbrew"] = {t="npc",n="Grimbooze Thunderbrew",z="westfall",s="Grimbooze Thunderbrew is an eccentric dwarven brewmaster camped out in the Dagger Hills of Westfall. Renowned across Dun Morogh as one of the founders of the great dwarven brewing traditions, he currently spends his days concocting potent spirits and speaking almost entirely in verse.",h="Grimbooze Thunderbrew is an eccentric dwarven brewmaster camped out in the Dagger Hills of Westfall.",sec={{t="A Brewer in Exile",b="Hailing from the renowned Thunderbrew brewing dynasty of Kharanos, Grimbooze once oversaw the Thunderbrew Distillery in Dun Morogh. Known for his jovial disposition and an unyielding passion for potent spirits, Grimbooze left the snowy mountain peaks for the windswept hills of Westfall. His relatives quietly attribute his wanderlust—and his bizarre habit of speaking strictly in rhymes—to consuming far too much legendary drink over the years. Travelers passing through the dangerous Dagger Hills can find him tending to his private casks, always eager to test a thirsty traveler's palate.",sp=0},{t="The Contest of Brews",b="Before settling in Westfall, Grimbooze played a pivotal role in brewing history. Years ago, the distillery welcomed an enigmatic wandering pandaren brewmaster named Chen Stormstout. The two engaged in an epic drinking bout, matching Grimbooze's finest recipes against Chen's enchanted Jug of a Thousand Cups. Unable to agree on whose craft reigned supreme, they arranged a massive public tasting contest in Dun Morogh—an event that laid the groundwork for modern dwarven drinking festivals. While his kin manage the distillery back in Kharanos, Grimbooze remains out in the field, refining his family's signature ale.",sp=0}},faq={{q="Where can I find Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew is stationed in the Dagger Hills, situated in southern Westfall, keeping camp amidst the hills with his brewing equipment.",al={"grimbooze location","where is grimbooze","where to find grimbooze thunderbrew"}},{q="Why is Grimbooze speaking in rhymes?",a="His eccentric rhyming speech is an idiosyncrasy developed after decades of sampling incredibly potent spirits, notably Chen Stormstout's enchanted brew, which his family claims slightly pickled his mind.",al={"why does grimbooze rhyme","grimbooze rhyming","why is he talking in verse"}},{q="What is his connection to the Thunderbrew Distillery?",a="Grimbooze is a patriarch of the famous Thunderbrew clan of Kharanos in Dun Morogh. He once ran the Thunderbrew Distillery before heading out into the wider world, leaving family members like Ragnar Thunderbrew to manage operations at home.",al={"grimbooze distillery","is grimbooze related to ragnar","thunderbrew family"}},{q="Did Grimbooze really drink with a pandaren?",a="Yes. Grimbooze hosted the wandering brewmaster Chen Stormstout in Kharanos. Their spirited contest to see who brewed the finest ale led directly to a legendary tasting competition in the snow of Dun Morogh.",al={"grimbooze and chen","chen stormstout grimbooze","who did grimbooze drink with"}}},ang={["race:Dwarf"]="Every dwarf knows the Thunderbrew name, and finding one of their foremost elders brewing wild recipes in the Westfall hills is a welcome taste of Dun Morogh.",["profession:Cooking"]="Culinary adventurers and spirit crafters revere the Thunderbrew legacy, making an encounter with Grimbooze a lesson in artisanal brewing."},kw={"ale","brewer","chen stormstout","dagger hills","distillery","grimbooze","kharanos","thunderbrew","westfall"},rel={"subzone:dagger-hills","zone:westfall","subzone:thunderbrew-distillery","subzone:kharanos","npc:ragnar-thunderbrew","topic:dwarf","quest:117","zone:dunmorogh"},src={"Grimbooze Thunderbrew"}}
E["npc:gryan-stoutmantle"] = {t="npc",n="Gryan Stoutmantle",z="westfall",s="Gryan Stoutmantle is a paladin of the Silver Hand and the commander of the People's Militia, operating out of Sentinel Hill in Westfall. Born in Westfall, he returned from the devastated northern kingdom of Lordaeron to protect his homeland after Stormwind's crown abandoned the region to banditry.",h="Gryan Stoutmantle is a paladin of the Silver Hand and the commander of the People's Militia, operating out of...",sec={{t="A Knight Returned Home",b="Gryan Stoutmantle began his service far from the quiet fields of southern Azeroth. Traveling north to Lordaeron as a young man, he took vows as a Knight of the Silver Hand and endured the horrors of the Third War, even witnessing the tragic purge of Stratholme by Prince Arthas Menethil. When news reached him that his native province of Westfall was collapsing into lawlessness, overrun by organized brigands and abandoned by the crown, Gryan left the northern fronts behind. He traded imperial battlefields for the defense of honest farmers, swearing that his home would not fall as the north had.",sp=0},{t="The People's Militia",b="Upon his return, Gryan found Westfall virtually undefended. Due to royal neglect and political paralysis within the House of Nobles, Stormwind refused to dispatch garrison troops. In response, Stoutmantle established the People's Militia at Sentinel Hill, rallying local farmers, sentries, and traveling mercenaries into a volunteer defense corps. His forces hold a precarious line against the Defias Brotherhood, riverpaw gnolls, and hostile mechanoids, unable even to spare reinforcements when neighbor settlements like Lakeshire plead for aid.",sp=0},{t="Unmasking the Kingpin",b="Refusing to fight blindly, Stoutmantle turned to an extensive intelligence network to uncover who was orchestrating Westfall's ruin. Calling in an old debt from the shady rogue Wiley the Black in Redridge and conferring with Mathias Shaw of SI:7, Gryan pierced the veil: the bandits were led by Edwin VanCleef, the slighted master architect of the Stonemasons' Guild. After the militia captured a bandit attempting to plunder a local wagon, Gryan used the traitor to pinpoint the Brotherhood's headquarters hidden beneath Moonbrook within the Deadmines, tasking veteran champions with striking down VanCleef directly.",sp=1}},faq={{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a paladin of the Silver Hand and the founder and commander of the People's Militia, the volunteer garrison headquartered at Sentinel Hill defending Westfall.",al={"who is gryan","stoutmantle lore","leader of westfall"}},{q="Why is the People's Militia needed if Westfall belongs to Stormwind?",a="Stormwind's House of Nobles refused to commit crown soldiers or treasury funds to protect the outlying province. Left to fend for themselves against marauders and gnolls, the local peasantry under Gryan's leadership formed their own independent defense force.",al={"why militia","where is stormwind army","why did stormwind abandon westfall"}},{q="What is Gryan's history with the Silver Hand?",a="Gryan traveled to Lordaeron in his youth to become a holy paladin of the Silver Hand. He served on northern battlefields during the Third War and was present during the culling of Stratholme before departing south to rescue his imperiled homeland.",al={"is gryan a paladin","gryan silver hand","gryan in lordaeron"}},{q="Why does Gryan refuse to send aid to Lakeshire?",a="When Magistrate Solomon of Lakeshire requested reinforcements against Redridge's gnolls and orcs, Gryan was forced to decline. The People's Militia is stretched to its absolute breaking point holding Sentinel Hill; sending even a small detachment would cause Westfall to fall to the Defias.",al={"magistrate solomon request","help redridge","why no troops to lakeshire"}},{q="How did Gryan discover where the Defias were hiding?",a="With intelligence from Wiley the Black and SI:7 spymaster Mathias Shaw, Gryan unmasked Edwin VanCleef as the mastermind. The militia then captured a thief known as the Defias Traitor, who guided Alliance forces straight to the Brotherhood's base in the Deadmines beneath Moonbrook.",al={"finding deadmines","who found vancleef","defias traitor story"},sp=1},{q="Who is Wiley the Black to Gryan?",a="Wiley the Black is a contact living at the inn in Lakeshire who owed his life to Gryan. Although Stoutmantle holds little affection for the rogue's unsavory nature, he leveraged that life debt to obtain crucial intelligence on Defias operations.",al={"wiley and gryan","wiley the black debt"}}},ang={["class:Paladin"]="Stoutmantle is a living example of Silver Hand duty: when the high councils of church and crown ignored the poor, he brought the Light's protection directly to the humble farmers who needed it most.",["faction:Alliance"]="Gryan's reliance on independent volunteers exposes the bitter cracks within the Alliance heartland, where political inaction in Stormwind forces loyal citizens to take up their own arms.",["race:Human"]="Born in Westfall, Gryan represents the resilience of Stormwind's rural folk, standing firm against both regional brigands and bureaucratic abandonment by the capital."},kw={"deadmines","gryan","people's militia","sentinel hill","silver hand","stoutmantle","vancleef","westfall","wiley"},rel={"subzone:sentinel-hill","zone:westfall","topic:defias-brotherhood","npc:edwin-vancleef","quest:12","quest:65","npc:wiley-the-black","subzone:deadmines"},src={"Gryan Stoutmantle"}}
E["npc:jasper-fel"] = {t="npc",n="Jasper Fel",z="westfall",s="Jasper Fel is a discreet supplier operating out of the SI:7 headquarters in Stormwind's Old Town. Providing daggers and assorted vials to operatives, he keeps a sharp eye on visitors and warns them to watch their tongues. His quiet trade supports the covert arm of the kingdom behind closed doors.",h="Jasper Fel is a discreet supplier operating out of the SI:7 headquarters in Stormwind's Old Town.",sec={{t="Supplies for the Shadows",b="Tucked away inside the barracks of SI:7 within Old Town, Jasper Fel caters to a very specific clientele. Rather than hawking standard arms to the city guard, he provides essential implements of tradecraft: simple daggers and the delicate vials required for brewing and applying poisons. Fel operates under the strict discipline of Mathias Shaw's intelligence division, curtly advising any who approach to mind their speech. In a stronghold dedicated to espionage and subtle lethality, casual chatter is an easy way to meet an early end.",sp=0}},faq={{q="Where can I find Jasper Fel?",a="Jasper Fel is stationed inside the SI:7 headquarters, located in the eastern portion of Old Town in Stormwind City.",al={"jasper fel location","where is jasper fel","jasper fel stormwind"}},{q="What does Jasper Fel sell?",a="He supplies basic daggers and various grades of empty vials, making him a useful stop for operatives stocking up on poison components.",al={"jasper fel vendor","what does fel sell","jasper fel wares"}},{q="Is Jasper Fel related to Morbent Fel?",a="They share a surname, which has led to speculation about a familial connection to the necromancer Morbent Fel in Duskwood, though Jasper himself keeps silent on personal matters.",al={"jasper fel morbent fel","is jasper fel related to morbent","fel family duskwood"}},{q="Why does Jasper Fel warn people to speak quietly?",a="He works directly inside SI:7, the heart of Stormwind's espionage apparatus. Loose talk in an organization filled with assassins and spies is considered dangerous, and Fel makes sure visitors treat the headquarters with appropriate caution.",al={"why speak quietly","jasper fel warning","wrong word throat cut"}}},ang={["class:Rogue"]="Jasper Fel provides the essential vials and backup blades required by covert operatives practicing their craft in Stormwind.",["faction:Alliance"]="Serving from the headquarters of SI:7, Fel ensures that the agents defending the kingdom from the shadows have reliable supplies."},kw={"daggers","jasper fel","morbent fel","old town","rogue supplies","si:7","stormwind","vials"},rel={"quest:2300","subzone:old-town","zone:stormwind","quest:55","topic:stormwind-kingdom","topic:alliance"},src={"Jasper Fel"}}
E["npc:marisa-du-paige"] = {t="npc",n="Marisa du'Paige",z="westfall",s="Marisa du'Paige is a rare human rogue spellcaster found lurking within the sprawling cave network outside the entrance to the Deadmines in southwestern Westfall. Aligned with the outlaws operating beneath Moonbrook, she wields arcane magic alongside the laborers and highwaymen guarding the tunnels.",h="Marisa du'Paige is a rare human rogue spellcaster found lurking within the sprawling cave network outside the...",sec={{t="Arcane Talent in the Tunnels",b="Deep inside the winding caverns that lead toward the Deadmines beneath Moonbrook, most defenders are rough-hewn cutpurses, renegade miners, and thugs. Marisa du'Paige stands out among them as a skilled human mage. While most spellcasters of the kingdom train within the sanctioned halls of Stormwind's Mage Quarter or serve the Kirin Tor, du'Paige has cast her lot with the outlaws and brigands hiding in Westfall's subterranean depths.",sp=0}},faq={{q="Who is Marisa du'Paige?",a="Marisa du'Paige is a rare human mage lurking in the outer cave system leading into the Deadmines. Unlike the typical common thieves and laborers found patrolling these passages, she wields arcane spells in defense of the underground network.",al={"marisa dupaige","who is marisa","rare in deadmines cave"}},{q="Where can she be found?",a="She spawns infrequently within the public cavern system beneath Moonbrook in Westfall, in the tunnels just outside the portal threshold of the Deadmines instance.",al={"marisa du'paige location","where is marisa dupaige","marisa spawn"}},{q="Why is a human mage hiding in the Deadmines caves?",a="Not every arcane practitioner remains loyal to the high towers of Stormwind. Deserters, renegades, and sympathetic commoners have flocked to the outlaw cause across Westfall, lending both steel and sorcery to their fortifications beneath Moonbrook.",al={"why is she here","marisa lore","marisa dupaige faction"}}},ang={["class:Mage"]="Marisa du'Paige is a reminder that arcane training in the kingdom is not confined to the towers of the Kirin Tor or Stormwind's wizard sanctum; rogue spellcasters readily sell their talents to criminal networks.",["faction:Alliance"]="Alliance adventurers scouting the tunnels beneath Moonbrook must stay alert for du'Paige, as an unexpected spellcaster amid hordes of cutpurses can quickly turn a skirmish deadly."},kw={"deadmines","human","mage","marisa du'paige","marisa dupaige","moonbrook","rare","westfall"},rel={"zone:westfall","zone:deadmines","topic:defias-brotherhood","topic:human"},src={"Marisa du'Paige"}}
E["npc:mathias-shaw"] = {t="npc",n="Mathias Shaw",z="westfall",s="Master Mathias Shaw is the leader of SI:7, the covert intelligence agency of the Kingdom of Stormwind. Operating from the shadows of Old Town, he directs spies and scouts to protect the realm from internal conspiracies and external horrors alike.",h="Master Mathias Shaw is the leader of SI:7, the covert intelligence agency of the Kingdom of Stormwind.",sec={{t="Master of SI:7",b="Mathias Shaw stands as Stormwind's foremost spymaster and assassin. From SI:7's discreet headquarters tucked behind the barracks in Old Town, Shaw coordinates a covert network that spans the Eastern Kingdoms and beyond. Pragmatic, calculating, and fiercely loyal to the House of Wrynn, he operates on the philosophy that Stormwind's safety depends just as much on unseen daggers and stolen missives as it does on gleaming armor and palace garrisons.",sp=0},{t="Shadow of VanCleef",b="Shaw shares a deeply personal history with Edwin VanCleef, leader of the rebel Defias Brotherhood. The two were childhood companions, and Shaw personally trained VanCleef in the arts of stealth and assassination, once hoping the gifted stonemason would put his talents toward serving the kingdom alongside him. Instead, when the Stonemasons Guild was cast out following the rebuilding of Stormwind, VanCleef turned those lethal lessons against the crown. Today, Shaw directs the surveillance and infiltration operations aimed at dismantling his old friend's insurrection across Westfall.",sp=1},{t="Eyes Across the Kingdoms",b="While domestic insurrection consumes Westfall and Elwynn, Shaw's attention is constantly drawn outward to lethal unknowns. When reports reached him of bizarre Forsaken operations in the Eastern Plaguelands, he dispatched five of his finest agents to investigate. Only one returned alive—babbling in terror about a champion named Nathanos Blightcaller before dying in his sleep. Shaw relies on trusted independent champions to venture where his scouts vanish, seeking to pierce the gloom gathering at the kingdom's borders.",sp=0}},faq={{q="Who is Mathias Shaw?",a="Mathias Shaw is the leader of SI:7, Stormwind's intelligence service and guild of assassins. Operating out of Old Town, he coordinates the kingdom's espionage and covert defense under the authority of the throne.",al={"who is shaw","leader of si7","mathias shaw lore","stormwind spymaster"}},{q="Where can Mathias Shaw be found?",a="He is located inside the SI:7 headquarters in the Old Town district of Stormwind City, secluded behind the military barracks.",al={"shaw location","where is mathias shaw","find mathias shaw"}},{q="What is his connection to Edwin VanCleef?",a="Shaw and Edwin VanCleef were childhood friends. Shaw personally trained VanCleef in roguecraft and espionage, hoping they would work together. After the Stonemasons' dispute turned violent, VanCleef used those very skills to forge the Defias Brotherhood.",al={"shaw and vancleef","vancleef friend","mathias and edwin"}},{q="What does SI:7 stand for?",a="SI:7 is the premier intelligence organization of Stormwind, specializing in surveillance, reconnaissance, espionage, and covert assassinations to safeguard the kingdom and Alliance interests.",al={"what is si:7","what does si7 mean","stormwind intelligence"}},{q="Why is Mathias Shaw interested in Westfall?",a="Westfall is the stronghold of the Defias Brotherhood. Shaw keeps active operatives in the region to spy on rebel activities and disrupt their plots against Stormwind.",al={"shaw westfall","si7 westfall","klaven's tower"}},{q="What happened to the agents Shaw sent to the Plaguelands?",a="Shaw dispatched five operatives to scout suspicious Forsaken movement in the Eastern Plaguelands. Four were killed near Marris Stead, and the sole survivor died raving about Nathanos Blightcaller shortly after staggering back to Stormwind.",al={"shaw plaguelands quest","five scouts shaw","marris stead scouts"}}},ang={["class:Rogue"]="Mathias Shaw represents the absolute pinnacle of human roguecraft. Alliance rogues are often sent to him for advanced tactical assignments and specialty poisons.",["faction:Alliance"]="As the kingdom's spymaster, Shaw serves as the first line of defense against subversion, gathering vital military intelligence for Highlord Bolvar Fordragon and the boy-king Anduin.",["race:Human"]="Shaw's tragic falling-out with his childhood friend Edwin VanCleef reflects the broader, bitter fracture within the Kingdom of Stormwind following its reconstruction."},kw={"assassin","blightcaller","kearnen","mathias shaw","old town","si:7","spymaster","stormwind","vancleef"},rel={"zone:stormwind","topic:defias-brotherhood","npc:edwin-vancleef","quest:2300","quest:2359","npc:nathanos-blightcaller","subzone:old-town","subzone:marris-stead"},src={"Mathias Shaw"}}
E["npc:old-murk-eye"] = {t="npc",n="Old Murk-Eye",z="westfall",s="Old Murk-Eye is an infamous, battle-hardened murloc prowling the southern coastline of Westfall. Revered among his kind and feared by coastal sailors, he serves as a lethal menace to anyone wandering near the Westfall Lighthouse.",h="Old Murk-Eye is an infamous, battle-hardened murloc prowling the southern coastline of Westfall.",sec={{t="Terror of the Coastline",b="While murlocs are a common pest along the shores of Westfall, Old Murk-Eye stands apart from the lesser scavengers. Considerably tougher and far more aggressive than his kin, this grizzled beast prowls the surf surrounding the Westfall Lighthouse. His continued presence has caused enough grief to local mariners that the spectral Captain Grayson seeks his death, offering a bounty for the creature's pristine scales to break his grip on the shallows.",sp=0}},faq={{q="Where does Old Murk-Eye wander?",a="He patrols the sandy shores and shallow waters of southwestern Westfall, directly along the coast near the Westfall Lighthouse.",al={"old murk eye location","where to find old murk eye","where is murk eye"}},{q="Why does Captain Grayson want Old Murk-Eye dead?",a="Captain Grayson considers Old Murk-Eye a persistent threat to the coastal waters. To curb the violence along the beach, he places a bounty on the legendary murloc, demanding a scale as proof of the deed.",al={"grayson murk eye","why kill old murk eye"}},{q="Is Old Murk-Eye different from ordinary murlocs?",a="Yes. He is notably stronger, more durable, and more aggressive than the Coastrunner and Tidehunter lackeys surrounding him, acting as a tribal champion among the local shoreline packs.",al={"how tough is murk eye","is murk eye an elite"}}},ang={["faction:Alliance"]="For Alliance adventurers clearing out Westfall, eliminating Old Murk-Eye removes a notorious predator that preys on stranded travelers and ship crews."},kw={"captain grayson","coastal menace","murk-eye","murloc","old murk-eye","westfall","westfall lighthouse"},rel={"npc:captain-grayson","subzone:westfall-lighthouse","quest:104","zone:westfall","topic:murloc"},src={"Old Murk-Eye"}}
E["npc:quartermaster-lewis"] = {t="npc",n="Quartermaster Lewis",z="westfall",s="Quartermaster Lewis is a human supply merchant stationed at Sentinel Hill in Westfall. Serving the local People's Militia, he provides rations, ammunition, and everyday provisions to travelers and defenders attempting to hold the frontier against the Defias Brotherhood.",h="Quartermaster Lewis is a human supply merchant stationed at Sentinel Hill in Westfall.",sec={{t="Keeper of the Tower's Stores",b="Perched inside Sentinel Tower, Quartermaster Lewis manages the meager logistical lifeline of the Westfall militia. With Stormwind's royal leadership offering little aid to the impoverished region, Sentinel Hill relies on local volunteers and whatever supplies they can gather. Lewis distributes standard field necessities, from dry rations and fresh water to arrows, shot, and throwing blades, ensuring the fighters standing watch have the bare essentials to survive Defias raids.",sp=0}},faq={{q="Who is Quartermaster Lewis?",a="He is the quartermaster stationed at Sentinel Tower in Westfall. Lewis handles mundane supplies, rations, and armaments for the People's Militia and any adventurers assisting their defense.",al={"quartermaster lewis lore","who is lewis","sentinel hill quartermaster"}},{q="What does Quartermaster Lewis sell?",a="He functions as a general goods vendor, offering fundamental survival items such as bread, milk, water, bags, flint, and various forms of ranged ammunition like arrows, bullets, and throwing daggers.",al={"what does lewis sell","lewis inventory","westfall vendor items"}},{q="What is his role in regional quests?",a="Lewis helps orient newcomers to local communications and courier routes around Sentinel Hill, sending adventurers on regional deliveries such as delivering messages to Thor, the gryphon master, and receiving responses.",al={"lewis quests","a swift message","return to lewis"}},{q="Is Lewis part of the Stormwind Army?",a="Like most defenders in Sentinel Hill, Lewis serves the People's Militia rather than an official detachment sent by the Stormwind crown. The region has been left largely to defend itself against the Defias Brotherhood.",al={"is lewis army","stormwind guard lewis","peoples militia lewis"}}},ang={["faction:Alliance"]="For Alliance recruits venturing into Westfall, Lewis provides a necessary resupply stop in a hostile territory where official crown resources are dangerously scarce.",["class:Hunter"]="Lewis is a vital field contact for marksmanship supplies in central Westfall, stocking both basic shot and arrows for ranged defenders."},kw={"lewis","peoples militia","quartermaster lewis","sentinel hill","sentinel tower","vendor","westfall"},rel={"subzone:sentinel-tower","zone:westfall","quest:6181","quest:6285","zone:deadmines"},src={"Quartermaster Lewis"}}
E["npc:salma-saldean"] = {t="npc",n="Salma Saldean",z="westfall",s="Salma Saldean is a hardy Westfall homesteader who tends Saldean's Farm alongside her husband, Farmer Saldean. In a region overrun by bandits and abandoned by Stormwind, she keeps her door open and provides warm meals to travelers in exchange for a little help around the homestead.",h="Salma Saldean is a hardy Westfall homesteader who tends Saldean's Farm alongside her husband, Farmer Saldean.",sec={{t="Hospitality in a Hard Land",b="While neighboring homesteads have been ransacked and burned by the Defias Brotherhood, the Saldeans manage to keep their hearth lit. Salma greets travelers with a warm demeanor and a hearty pot on the stove, always on the lookout for capable wanderers willing to assist around the farmstead.",sp=0},{t="Putting Food on the Table",b="Survival in Westfall requires resourcefulness. Salma makes use of whatever the land provides to feed her family and visitors, teaching travelers how to prepare local specialties like Goretusk liver pie and her famous Westfall stew from wild boar, vultures, murlocs, and stray okra.",sp=0}},faq={{q="Who is Salma Saldean?",a="Salma Saldean is a human farmer living at Saldean's Farm in central Westfall alongside her husband. She provides comfort and food to travelers while struggling to keep the farm running amid regional collapse.",al={"who is salma","salma saldean lore","saldean farm wife"}},{q="Where is Salma Saldean located?",a="She can be found outside her farmhouse at Saldean's Farm, situated along the road in central Westfall, just north of the crossroads leading down toward Sentinel Hill.",al={"salma location","where is salma saldean","where is saldean farm"}},{q="What recipes does Salma Saldean teach?",a="Salma shares the secrets to making hearty local provisions, most notably Goretusk Liver Pie and Westfall Stew, utilizing local ingredients scavenged from the wildlife around Westfall.",al={"westfall stew recipe","salma food","goretusk liver pie"}},{q="Why is it so hard for the Saldeans to find help?",a="Most farmers and laborers in Westfall have abandoned their lands and fled due to marauding bandits, rogue harvest golems, and the absence of Stormwind's royal army, leaving the few remaining homesteaders completely shorthanded.",al={"why abandoned farm","why help needed saldean","westfall farm abandoned"}},{q="How do the Saldeans survive the Defias Brotherhood?",a="The Saldeans rely on passing adventurers and their own resilience to defend the property. Though peril surrounds them, they stubbornly refuse to abandon their land and home.",al={"saldean defias","why hasn't farm burned down"}},{q="Who is Salma's husband?",a="She is married to Farmer Saldean, who works alongside her on the farm trying to deal with malfunctioning harvest watchers and rogue beasts.",al={"salma husband","farmer saldean"}}},ang={["profession:Cooking"]="Salma Saldean is a key contact for cooks traversing Westfall, offering practical recipes like Westfall Stew and Goretusk Liver Pie that make full use of local wildlife.",["faction:Alliance"]="Salma exemplifies the stubborn fortitude of Alliance homesteaders who refuse to yield their livelihoods despite the Crown's neglect.",["race:Human"]="For human travelers, visiting Salma offers a poignant reminder of the hardship faced by Stormwind's common folk outside the kingdom's fortified capital."},kw={"farmer saldean","goretusk liver pie","saldean's farm","salma saldean","stew","westfall","westfall stew"},rel={"subzone:saldean-s-farm","quest:36","quest:22","zone:westfall","topic:stormwind-kingdom"},src={"Salma Saldean"}}
E["npc:sprite-jumpsprocket"] = {t="npc",n="Sprite Jumpsprocket",z="westfall",s="Sprite Jumpsprocket is an apprentice gnome engineer currently residing in the busy Dwarven District of Stormwind City. Like many gnomes who sought refuge following the fall of Gnomeregan, she pursues technical craft and innovation alongside her fellow tinkers. Her presence highlights the thriving community of dwarven and gnomish artisans who keep the capital city supplied with gears, gadgets, and mechanical expertise.",h="Sprite Jumpsprocket is an apprentice gnome engineer currently residing in the busy Dwarven District of...",sec={{t="A Tinker in Stormwind",b="In the soot-covered streets and bustling workshops of the Dwarven District, gnomes and dwarves work shoulder-to-shoulder forging metal and designing intricate contraptions. Sprite Jumpsprocket serves as an apprentice engineer in this vibrant hub. Having integrated into the kingdom's capital, apprentice tinkers like Sprite hone their craft under experienced masters, contributing their inventive minds to the everyday mechanisms and technological marvels of the Alliance.",sp=0},{t="Gnomish Ingenuity in Exile",b="Following the devastating loss of Gnomeregan, displaced gnomes dispersed across Alliance lands, bringing their singular knack for tinkering, chemistry, and mechanics with them. In Stormwind City, gnomes found a welcoming sanctuary within the Dwarven District, where blast furnaces and workbenches are plentiful. Sprite Jumpsprocket represents this resilient, forward-looking spirit—determined to master the complex discipline of engineering despite the hardships faced by her kin.",sp=0}},faq={{q="Who is Sprite Jumpsprocket?",a="Sprite Jumpsprocket is a female gnome apprentice engineer living and working within the Dwarven District of Stormwind City.",al={"sprite jumpsprocket","who is sprite","sprite jumpsprocket lore"}},{q="Where can I find Sprite Jumpsprocket?",a="She can be found in the Dwarven District of Stormwind City, surrounded by workshops, anvils, and fellow engineering enthusiasts.",al={"sprite jumpsprocket location","where is sprite","find sprite jumpsprocket"}},{q="What role does she serve in Stormwind?",a="Sprite is an apprentice engineer. She represents the ongoing presence of gnomish tinkerers honing their inventive crafts in the Alliance capital.",al={"sprite jumpsprocket role","what does she do","sprite jumpsprocket purpose"}},{q="Why are gnomes like Sprite living in Stormwind?",a="After the catastrophic fall of Gnomeregan, many gnomes sought refuge among their dwarven cousins in Ironforge and throughout human lands, particularly Stormwind City, where their industrial ingenuity is in high demand.",al={"why gnomes in stormwind","gnomes dwarven district","gnome refugees"}},{q="Is Sprite Jumpsprocket tied to any notable quests?",a="Sprite plays a minor role in the local neighborhood of the Dwarven District, mainly standing as part of the district's engineering community.",al={"sprite jumpsprocket quest","quests for sprite"}},{q="Is she associated with Westfall?",a="While sometimes indexed near surrounding southern kingdoms records, Sprite is stationed squarely in the Dwarven District of Stormwind City, though engineering creations throughout the region often share gnomish designs.",al={"sprite jumpsprocket westfall","westfall engineer"}}},ang={["profession:Engineering"]="For budding tinkers, Sprite Jumpsprocket stands as a fellow student of sprockets, copper tubing, and volatile concoctions in Stormwind's most industrial enclave.",["race:Gnome"]="Sprite is a reminder of the perseverance of Gnomeregan's exiles, continuing their love of craft and mechanical mastery far from their lost homeland.",["faction:Alliance"]="Her work in the Dwarven District illustrates the everyday cooperation between humans, dwarves, and gnomes supporting the capital's infrastructure."},kw={"apprentice","dwarven district","engineer","gnome","jumpsprocket","sprite jumpsprocket","stormwind","tinker"},rel={"subzone:dwarven-district","zone:stormwind","topic:gnome","topic:stormwind-kingdom","zone:westfall"},src={"Sprite Jumpsprocket"}}
E["npc:the-defias-traitor"] = {t="npc",n="The Defias Traitor",z="westfall",s="The Defias Traitor is a captured outlaw held at the base of the Sentinel Hill watchtower in Westfall. Caught red-handed by the People's Militia, he traded the secret location of the Brotherhood's headquarters to save his own neck.",h="The Defias Traitor is a captured outlaw held at the base of the Sentinel Hill watchtower in Westfall.",sec={{t="A Bargain for Survival",b="Not every member of the Defias Brotherhood possesses fanatical loyalty to Edwin VanCleef's cause. When this petty thief was caught attempting to rob Farmer Saldean of his wagon, Gryan Stoutmantle's militia had him dead to rights. Facing the gallows, the thief chose self-preservation over brotherhood, offering up the exact whereabouts of their hidden base of operations in exchange for his life.",sp=0},{t="Leading the Way to Moonbrook",b="Guarded beneath the watchtower at Sentinel Hill, the turncoat's task is simple yet dangerous: guide Alliance champions straight through hostile territory to the hidden entrance beneath the ruined town of Moonbrook. Though hated by his former comrades and despised by his captors, his betrayal provides the People's Militia with the breakthrough they need to strike at the Brotherhood's heart.",sp=1}},faq={{q="Who is the Defias Traitor?",a="He is a former member of the Defias Brotherhood captured by the People's Militia while trying to steal a wagon from Farmer Saldean. To escape execution, he agreed to lead Militia allies to the Brotherhood's secret lair.",al={"who is this guy","defias traitor identity","who is the traitor at sentinel hill"}},{q="Why is he standing outside the tower in Sentinel Hill?",a="He is held in custody by Gryan Stoutmantle and the People's Militia right outside their stronghold. He remains there under armed watch until volunteers step forward to escort him to the Defias hideout.",al={"traitor location","why is he at sentinel hill","where is the traitor"}},{q="Where does he lead you?",a="He guides travelers southwest across the plains of Westfall into the derelict town of Moonbrook, pointing out the concealed entrance to the Defias Hideout.",al={"where does the traitor go","traitor escort destination","where is defias hideout"}},{q="Why did he turn against the Defias Brotherhood?",a="Simple self-preservation. Facing execution after getting caught stealing from Farmer Saldean, he offered up the Defias Brotherhood's greatest secret in exchange for his life.",al={"why betray defias","traitor motive","why did he flip"}}},ang={["faction:Alliance"]="For the People's Militia and local defenders, this prisoner represents the long-awaited turning point in the struggle against the outlaws terrorizing Westfall.",["class:Rogue"]="A stark reminder of the fragile loyalty within criminal syndicates: when cornered by the law, thieves and cutpurses rarely hesitate to sell out their own."},kw={"defias hideout","defias traitor","farmer saldean","moonbrook","peoples militia","sentinel hill","westfall"},rel={"quest:65","subzone:sentinel-hill","subzone:defias-hideout","subzone:moonbrook","topic:defias-brotherhood","npc:farmer-saldean","zone:westfall","quest:12"},src={"The Defias Traitor"}}
E["npc:thor"] = {t="npc",n="Thor",z="westfall",s="Thor is the gryphon flight master stationed atop the fortified tower at Sentinel Hill in Westfall. As the vital aerial link between the beleaguered People's Militia and the capital city of Stormwind, he oversees the dispatch of couriers, scouts, and urgent messages across kingdom skies.",h="Thor is the gryphon flight master stationed atop the fortified tower at Sentinel Hill in Westfall.",sec={{t="The Eyrie of Sentinel Hill",b="Perched on the ramparts of Sentinel Hill, Thor manages the flight roost that ties Westfall's frontier defenders to the heart of the kingdom. While the People's Militia struggles on the ground against roaming bandits, gnolls, and malfunctioning harvest golems, Thor ensures that crucial military dispatches and travelers can bypass the perilous roads altogether. Through his tamed gryphons, urgent requests for aid and reports from Gryan Stoutmantle reach the court in Stormwind far quicker than any ground messenger could manage.",sp=0}},faq={{q="Who is Thor?",a="Thor is a human flight master stationed at Sentinel Hill in Westfall. He tends to the trained gryphons that provide aerial travel between Westfall and other Alliance settlements, notably Stormwind City.",al={"who is this guy","sentinel hill flight master","thor npc"}},{q="What role does he play in Westfall?",a="He serves as the aerial lifeline for Sentinel Hill. Thor coordinates couriers carrying vital military correspondence between the People's Militia and the high command in Stormwind, ensuring commanders remain informed despite Defias activity on the roads.",al={"what does thor do","thor purpose"}},{q="Why is gryphon travel important here?",a="The roads connecting Westfall to Elwynn Forest and Duskwood are rife with Defias highwaymen, Riverpaw gnolls, and dangerous wildlife. Gryphon flights provide a secure, swift bypass that keeps supply and communication lines intact.",al={"why fly in westfall","westfall flight path"}}},ang={["faction:Alliance"]="For Alliance champions assisting the People's Militia, Thor provides the quickest route back to the capital to deliver field intelligence and restock supplies."},kw={"courier","flight master","gryphon","peoples militia","sentinel hill","thor","westfall"},rel={"subzone:sentinel-hill","zone:westfall","quest:6181","quest:6281","topic:stormwind-kingdom"},src={"Thor"}}
E["npc:tiffin-ellerian-wrynn"] = {t="npc",n="Tiffin Ellerian Wrynn",z="westfall",s="Queen Tiffin Ellerian Wrynn was the beloved wife of King Varian Wrynn and the mother of young King Anduin. Her tragic death during the Stonemasons' riot shattered the royal household and triggered the exile of the craftsmen who would become the Defias Brotherhood.",h="Queen Tiffin Ellerian Wrynn was the beloved wife of King Varian Wrynn and the mother of young King Anduin.",sec={{t="A Beloved Queen",b="Born to the minor House of Ellerian, which held modest holdings in Westfall, Tiffin's betrothal to Prince Varian Wrynn was arranged at birth to secure her family a seat in Stormwind's House of Nobles. Though the two initially chafed at the arrangement, their bond grew deep and enduring. Tiffin's calm demeanor grounded Varian's temper, and her kindness made her widely cherished by commoners and nobility alike.",sp=0},{t="Tragedy in Stormwind",b="When tensions over payment for Stormwind's reconstruction boiled over into civil strife, Queen Tiffin stood as one of the few prominent voices urging the House of Nobles to pay the Stonemasons' Guild in full. While trying to appease the furious laborers during a riot in the streets, she was struck and killed by a thrown rock. Her sudden death plunged King Varian into profound grief and hardened his wrath against the rioters, driving Edwin VanCleef and the stonemasons into exile across Westfall.",sp=0}},faq={{q="Who was Queen Tiffin Wrynn?",a="Queen Tiffin Ellerian Wrynn was the queen consort of Stormwind, wife of King Varian Wrynn, and mother of the boy-king Anduin. She came from the minor Ellerian noble family with landholdings in Westfall.",al={"who is tiffin","anduin mother","varian wife"}},{q="How did Tiffin Wrynn die?",a="She was killed during the Stonemasons' riot in Stormwind City. As she stepped forward in an effort to calm the enraged crowd, a thrown rock struck her fatally, an accident that broke the King's spirit and sparked intense royal retribution.",al={"how did tiffin die","who killed tiffin","queen death"}},{q="What did Queen Tiffin think of the Stonemasons?",a="Unlike many in the House of Nobles, Queen Tiffin strongly advocated for the Stonemasons' Guild, insisting they receive the full payment originally promised for rebuilding Stormwind.",al={"tiffin defias","did tiffin support stonemasons","tiffin payment"}},{q="How did her death affect Stormwind?",a="Her death threw King Varian into a devastating depression and prompted him to crack down violently on the rioting stonemasons. Fearing execution, the guild fled Stormwind into the Westfall countryside, eventually organizing into the outlaw Defias Brotherhood.",al={"consequences of tiffin death","why did vancleef rebel","varian depression"}}},ang={["race:Human"]="For humans of Stormwind and Westfall, Queen Tiffin is remembered as a gentle peacemaker whose tragic end shattered the peace of the realm.",["faction:Alliance"]="The sorrow of Queen Tiffin's loss still hangs heavily over the royal court, explaining King Varian's temper before his disappearance and the heavy burden resting on young King Anduin."},kw={"anduin","ellerian","queen","stonemasons","tiffin","varian","westfall","wrynn"},rel={"topic:varian-wrynn","topic:stormwind-kingdom","topic:house-of-nobles","zone:westfall"},src={"Tiffin Ellerian Wrynn"}}
E["npc:verna-furlbrow"] = {t="npc",n="Verna Furlbrow",z="westfall",s="Verna Furlbrow is an evicted farmer currently stranded beside her broken-down wagon near the northern border of Westfall. After bandits seized her family's pumpkin patch, she and her husband attempted to flee toward Elwynn Forest, only to find themselves stuck on the dangerous open road.",h="Verna Furlbrow is an evicted farmer currently stranded beside her broken-down wagon near the northern border...",sec={{t="A String of Misfortunes",b="Verna and her husband once worked their own pumpkin farm in northern Westfall, but the rising tide of lawlessness sweeping the countryside drove them out. When outlaws overran their land, the couple piled what possessions they could onto their cart and hitched up their faithful horse, Old Blanchy, intending to escape to the safety of Elwynn Forest. Disastrously, their wagon broke down just down the road from the abandoned Jansen Stead. With no means to repair the axle or move forward, Verna has been left to endure the elements, bandit raids, and scavengers while relying on traveling adventurers to keep her household fed and guarded.",sp=0},{t="Heart of the Hearth",b="Despite being reduced to squatting along the roadside, Verna maintains a welcoming and resourceful spirit. Known across the region as the creator of Westfall Stew, she regularly shares meals and warm fires with wandering transients and refugees who have suffered similar fates. She relies on passing wanderers to scour the fields for ingredients—such as boar snouts, murloc eyes, okra, and stringy vulture meat—to replenish her cooking pot, transforming whatever the harsh frontier yields into hearty sustenance for the destitute.",sp=0}},faq={{q="Why is Verna Furlbrow camped along the road?",a="Verna and her husband fled their pumpkin farm after outlaws overran northern Westfall. As they headed toward Elwynn Forest to find refuge, their wagon broke down near the Jansen Stead, leaving them stranded on the roadside.",al={"why is verna furlbrow here","verna furlbrow location","what happened to verna"}},{q="Who is Farmer Furlbrow to her?",a="Farmer Theodore Furlbrow is Verna's husband. Together they worked their Westfall homestead until bandits forced them off their land.",al={"verna furlbrow husband","is farmer furlbrow her husband"}},{q="What is Westfall Stew?",a="Westfall Stew is a regional frontier dish invented by Verna. She concocts it from wild boar snouts, stringy vulture meat, murloc eyes, and okra harvested from neighboring abandoned farms to sustain stranded refugees.",al={"westfall stew quest","verna furlbrow stew","what does verna cook"}},{q="What happened to the Furlbrows' farm?",a="The Furlbrows owned a pumpkin farm in northern Westfall, but organized bandits drove them from their land during the kingdom's recent security breakdown, forcing them to abandon their home and fields.",al={"furlbrow pumpkin farm","furlbrows farm what happened"}}},ang={["profession:Cooking"]="Verna is the creator of the iconic Westfall Stew, teaching fledgling frontier chefs how to turn scavenged meats and wild crops into a fortifying meal.",["faction:Alliance"]="The stranded Furlbrows exemplify the human cost of Stormwind's neglected borders, where ordinary citizens are driven from their homes with no royal soldiers sent to defend them."},kw={"broken wagon","furlbrow","jansen stead","old blanchy","refugee","theodore furlbrow","verna furlbrow","westfall stew"},rel={"npc:farmer-furlbrow","quest:36","quest:151","quest:64","subzone:jansen-stead","zone:westfall","topic:defias-brotherhood","topic:stormwind-kingdom"},src={"Verna Furlbrow"}}
E["npc:wiley-the-black"] = {t="npc",n="Wiley the Black",z="westfall",s="Wiley the Black is an elusive rogue currently lying low at the Lakeshire Inn in Redridge. Though shady and reticent, he owes a life-debt to Gryan Stoutmantle and serves as a vital underworld contact regarding the Defias Brotherhood.",h="Wiley the Black is an elusive rogue currently lying low at the Lakeshire Inn in Redridge.",sec={{t="A Scoundrel's Debt",b="Tucked away inside the Lakeshire Inn, Wiley the Black keeps a low profile away from the open turmoil of Westfall and the gnoll-infested borders of Redridge. Despite his roguish nature and questionable past, Wiley is bound by honor to Gryan Stoutmantle, commander of the People's Militia. Stoutmantle once saved Wiley's life—or as Stoutmantle grumbles, spared him from rotting in a cell. When the People's Militia desperately needs insight into the inner workings of the Defias conspiracy, Wiley is the informant they turn to, reluctantly parting with covert intelligence to clear his debt.",sp=0}},faq={{q="Where can I find Wiley the Black?",a="Wiley the Black is located inside the Lakeshire Inn in the town of Lakeshire, nestled within the Redridge Mountains.",al={"wiley location","where is wiley the black","wiley redridge","lakeshire inn wiley"}},{q="Why is Wiley helping Gryan Stoutmantle?",a="Gryan Stoutmantle saved Wiley's life in the past. Even though Gryan views him as an infuriating scoundrel and Wiley is reluctant to stick his neck out, Wiley honors the debt by relaying vital information about the Defias Brotherhood.",al={"why help gryan","wiley gryan relationship","wiley stoutmantle debt"}},{q="How does Wiley know about the Defias Brotherhood?",a="Wiley possesses intimate knowledge of underworld movements and Defias operations. His underworld connections and secretive nature suggest he has deep ties to the criminal network operating out of Westfall, perhaps even as a former associate.",al={"is wiley defias","how does wiley know defias","wiley defias connection"}},{q="What role does he play in the Defias investigation?",a="When the People's Militia captures mysterious clues pointing to a larger conspiracy, Stoutmantle sends adventurers to Lakeshire with a message for Wiley. Wiley examines the situation and provides a written note directing the militia toward the leaders orchestrating the rebellion.",al={"wiley quest role","what does wiley do","defias brotherhood wiley"}}},ang={["class:Rogue"]="Wiley demonstrates the delicate craft of staying alive through tradecraft and intelligence. For rogues, he is a classic example of an operative who survives by knowing when to trade information and whom to repay.",["faction:Alliance"]="With Stormwind's army absent, the Alliance relies on unofficial assets like Wiley to piece together the rebellion festering in Westfall."},kw={"defias","gryan stoutmantle","informant","lakeshire","redridge","wiley","wiley the black"},rel={"quest:65","npc:gryan-stoutmantle","topic:defias-brotherhood","subzone:lakeshire-inn","subzone:lakeshire","zone:redridge","zone:westfall"},src={"Wiley the Black"}}
E["quest:102"] = {t="quest",n="Patrolling Westfall",z="westfall",s="Patrolling Westfall is a bounty quest issued by Captain Danuvin at Sentinel Hill. Frustrated by Stormwind's lack of military support, the local People's Militia recruits willing volunteers to cull the aggressive gnoll packs wandering the grasslands. Danuvin suspects these scavengers have aligned themselves with the thieves entrenched in the Deadmines.",h="Patrolling Westfall is a bounty quest issued by Captain Danuvin at Sentinel Hill.",sec={{t="Abandoned by the Crown",b="Sentinel Hill stands as the last organized line of defense in Westfall, but its garrison does not march under royal orders from Stormwind Keep. With the capital refusing to dispatch troops to safeguard the outer farmlands, the local populace organized into the People's Militia. Captain Danuvin, a former farmer himself, refuses to surrender his homeland. Without an official army, the militia relies heavily on passing travelers and adventurers to keep the perimeter from collapsing entirely.",sp=0},{t="The Scavengers of the Grasslands",b="Gnolls have long lurked on the fringes of human civilization, but their growing audacity in Westfall is an immediate danger to the refugees and squatters clinging to survival. Worse still, Danuvin's scouts report that these feral packs appear to be working in coordination with the bandits operating out of the Deadmines. By sending hunters out to collect paws, Danuvin aims to suppress their expanding patrols and shatter whatever cooperation has formed between the beasts and the outlaws.",sp=0}},faq={{q="Who is Captain Danuvin?",a="Captain Danuvin is one of the defensive commanders stationed at Sentinel Hill. A former local farmer, he stepped up to lead volunteer defenders after Stormwind withdrew its official support, swearing never to abandon the citizens remaining in Westfall.",al={"captain danuvin","who is danuvin","quest giver sentinel hill"}},{q="Why is the People's Militia fighting gnolls instead of Stormwind soldiers?",a="The House of Nobles in Stormwind has largely turned a blind eye to Westfall's plight, leaving the region without royal soldiers. The displaced farmers and laborers had to form the People's Militia to defend their own land against bandits and wild beasts.",al={"why no stormwind army","where are stormwind guards","why militia"}},{q="Are the gnolls in Westfall organized?",a="While gnolls are notoriously chaotic scavengers, Captain Danuvin notes troubling signs that these packs are coordinating with the thieves operating out of the Deadmines, effectively acting as an outer buffer for the criminal syndicate.",al={"are gnolls working with defias","gnoll alliance","deadmines thieves gnolls"}},{q="Why does Captain Danuvin ask for gnoll paws?",a="Bounties across the kingdoms require physical proof of confirmed kills. Gnoll paws serve as undeniable evidence that the roaming beasts have been permanently removed from the grasslands.",al={"why gnoll paws","paw bounty","proof of kills"}},{q="Where are the gnolls typically found?",a="Gnoll hunting parties and camps are scattered across the central and southern plains of Westfall, frequently roving the open fields around abandoned homesteads and near the hillsides.",al={"gnoll locations","where to find gnolls westfall"}},{q="What happens once the gnoll threat is pushed back?",a="The People's Militia hopes that by continuously thinning the ranks of gnolls and outlaws, the plains can eventually be reclaimed and restored to the prosperous breadbasket that once fed the kingdom.",al={"what next westfall","militia goal","breadbasket of stormwind"}}},ang={["faction:Alliance"]="This patrol highlights the deep political divide between the struggling rural peasantry of Westfall and the indifferent aristocracy presiding over Stormwind Keep.",["race:Human"]="For humans, witnessing Westfall's golden fields overrun by savage gnoll packs is a bitter reminder of how fragile the kingdom's recovery remains after the recent wars."},kw={"danuvin","deadmines","gnolls","paws","peoples militia","sentinel hill","stormwind","westfall"},rel={"npc:captain-danuvin","subzone:sentinel-hill","zone:westfall","quest:12","topic:gnoll","zone:deadmines","topic:stormwind-kingdom","subzone:deadmines"},m={start="Captain Danuvin",level="14",faction="Alliance",id=102},src={"Patrolling Westfall"}}
E["quest:103"] = {t="quest",n="Keeper of the Flame",z="westfall",s="Keeper of the Flame is a quest offered by Captain Grayson, a spectral sailor haunting the rocky shores of the Westfall Lighthouse. In the wake of a brutal murloc massacre that wiped out the living keepers, Grayson seeks oil to keep the coastal beacon burning and guide ships safely past treacherous reefs.",h="Keeper of the Flame is a quest offered by Captain Grayson, a spectral sailor haunting the rocky shores of the...",sec={{t="A Spectral Duty",b="Perched on a craggy islet off the southwest shore of Westfall, the lighthouse once safely guided mariners navigating the treacherous shallows of the Great Sea. That came to a bloody end when the murloc raider Old Murk-Eye led an assault, slaughtering the keeper and his family. The ghost of Captain Grayson, who met his own watery demise upon these very rocks, now watches over the tower. Powerless to stop the massacre in death, Grayson refuses to allow the lighthouse to go dark.",sp=0},{t="Fueling the Beacon",b="Without a living keeper to tend the flame, maintaining the light requires an unusual source of fuel. The rogue Harvest Watchers wandering the abandoned farmlands of Westfall carry flasks of machinery oil in their rusted bellies. Grayson sends adventurers back ashore to salvage this oil from the haywire constructs, ensuring the flame endures and preventing other wayward captains from sharing his grim fate.",sp=0}},faq={{q="Who is Captain Grayson?",a="Captain Grayson is the restless spirit of a mariner who shipwrecked and died along the perilous coastline of Westfall. Unable to move on, he took it upon himself to watch over the Westfall Lighthouse and protect living sailors from suffering the same tragic end.",al={"captain grayson","lighthouse ghost","who is the ghost at westfall lighthouse"}},{q="What happened to the original lighthouse keepers?",a="The lighthouse keeper and his family were brutally murdered in a raid led by Old Murk-Eye, an infamous murloc chieftain prowling the shoreline. Captain Grayson was forced to watch helplessly as an apparition while the massacre unfolded.",al={"what happened to lighthouse keeper","who killed the lighthouse keeper","keeper family dead"}},{q="Where does the oil for the lighthouse flame come from?",a="The oil is scavenged from the mechanical Harvest Watchers that run rampant through the fallow fields and abandoned grain farms of Westfall.",al={"where to get oil","harvest monster oil","flask of oil"}},{q="Why does Grayson care about keeping the beacon lit?",a="Grayson considers it his afterlife's solemn duty to save mortal sailors on the Great Sea from steering into the jagged rocks of the coastline, having died needlessly upon those exact reefs in life.",al={"why light the torch","grayson motivation","lighthouse flame purpose"}},{q="Who is Old Murk-Eye?",a="Old Murk-Eye is a notorious and vicious murloc that prowls the Westfall coastline. He is infamous for organizing attacks on mortal settlements along the shore, including the slaughter of the lighthouse keeper's household.",al={"old murk-eye","murk eye","murloc leader westfall"}},{q="Where is the Westfall Lighthouse located?",a="The lighthouse stands on a jagged rocky islet just off the southwestern coast of Westfall, accessible by swimming out across the shallow coastal waters.",al={"lighthouse location","where is westfall lighthouse","find lighthouse"}}},ang={["faction:Alliance"]="Keeping the Westfall beacon burning protects trade ships and naval vessels bound for Stormwind Harbor from running aground along the kingdom's crumbling coast.",["profession:Engineering"]="The mechanical Harvest Watchers running wild across Westfall's farms carry volatile machine fluids that double as lantern fuel in a pinch."},kw={"beacon","captain grayson","flask of oil","great sea","harvest monsters","old murk-eye","westfall lighthouse"},rel={"npc:captain-grayson","subzone:westfall-lighthouse","zone:westfall"},m={start="Captain Grayson",level="16",id=103},src={"Keeper of the Flame (Classic)"}}
E["quest:104"] = {t="quest",n="The Coastal Menace",z="westfall",s="Captain Grayson's restless ghost watches the rocky coast of Westfall, haunted by the memory of the shipwreck that took his life and the slaughter of the lighthouse keeper's family. He charges travelers with hunting down the vicious murloc chieftain responsible: Old Murk-Eye. Slaying the beast brings a measure of justice to the shore and helps safeguard future sailors.",h="Captain Grayson's restless ghost watches the rocky coast of Westfall, haunted by the memory of the shipwreck...",sec={{t="A Beacon in the Dark",b="The Westfall Lighthouse stands as the lone guide through the jagged shallows of the southern coast, but its flame has flickered through bloody tragedies. Captain Grayson lost his life when his vessel broke against the rocks in the dark, an accident precipitated when murlocs terrified the lighthouse keeper's family into fleeing their post. Though the family later returned and relit the flame, the reprieve was brief. The shoreline remained stalked by a particularly cunning and ruthless predator.",sp=0},{t="The Scourge of the Coast",b="Old Murk-Eye is not merely another wild beast prowling the tide pools. Grayson recounts watching the creature sway the weaker-minded murlocs along the coast, rallying them into a coordinated strike against the lighthouse. The second raid proved fatal, wiping out the keeper's family before Grayson's helpless spectral eyes. To bring peace to the dead and preserve what remains of safety on the Great Sea, the ghostly captain demands Murk-Eye's death and a scale as proof.",sp=0}},faq={{q="Who is Old Murk-Eye?",a="Old Murk-Eye is a notorious, cunning murloc chieftain who prowls the southern coastline of Westfall. Unlike ordinary murlocs, he possesses enough malicious intelligence to rally and direct his brethren into coordinated, lethal attacks on human settlements along the shore.",al={"murk-eye","murk eye","who is murk eye","who is the coastal menace"}},{q="Why does Captain Grayson want Old Murk-Eye dead?",a="Grayson's ship crashed upon the rocks because Murk-Eye and his followers frightened off the lighthouse keeper, plunging the shore into darkness. Later, Grayson helplessly watched as Murk-Eye led a second raid that butchered the returned keeper and his family.",al={"grayson grudge","why kill murk eye","grayson backstory"}},{q="Where can Old Murk-Eye be found?",a="Old Murk-Eye patrols the open beaches and shallows along the coast of Westfall, typically near the waters surrounding the Westfall Lighthouse and the neighboring murloc encampments.",al={"murk-eye location","where is murk eye","find murk eye"}},{q="What proof does Grayson ask for?",a="Captain Grayson asks for a single scale stripped from Old Murk-Eye's hide to confirm the coastal terror has finally been destroyed.",al={"proof of death","scale of murk eye","quest turn in"}},{q="Who was Captain Grayson in life?",a="Captain Grayson was a sea captain whose ship met its end on the rocks below the Westfall Lighthouse. In death, his spirit lingers near the shore, seeking retribution against the murlocs and attempting to make the waters safer for passing vessels.",al={"captain grayson","ghost at the lighthouse","lighthouse ghost"}},{q="What happened to the lighthouse keeper's family?",a="The keeper's family originally fled when Old Murk-Eye harassed the tower. After they bravely returned to relight the lantern, Murk-Eye coerced a band of murlocs to raid the tower a second time, slaughtering the entire family.",al={"keeper family","who lived at lighthouse","lighthouse massacre"}}},ang={["faction:Alliance"]="The coastal waters of Westfall are vital shipping lanes for Stormwind. Culling leaders like Old Murk-Eye keeps the southern sea routes open and safe from sabotage.",["race:Human"]="The murder of the lighthouse keeper's family is another grim chapter in the loss of Westfall's safety, adding a personal weight to avenging fellow citizens of the kingdom."},kw={"captain grayson","coastal menace","great sea","murloc","old murk-eye","scale of old murk-eye","westfall","westfall lighthouse"},rel={"npc:captain-grayson","subzone:westfall-lighthouse","zone:westfall","topic:murloc"},m={start="Captain Grayson",level="20",id=104},src={"The Coastal Menace (Classic)"}}
E["quest:109"] = {t="quest",n="Report to Gryan Stoutmantle",z="westfall",s="This directive points seasoned adventurers crossing out of Elwynn Forest toward Westfall's beleaguered frontier. With the crown neglecting the outer farmlands, local defenders rely on willing sellswords to rally under Gryan Stoutmantle at Sentinel Hill.",h="This directive points seasoned adventurers crossing out of Elwynn Forest toward Westfall's beleaguered...",sec={{t="A Plea Across the River",b="Whether offered by guardsmen stationed along the Elwynn borders or desperate farmers fleeing westward, the summons remains the same: skilled fighters are needed across the river. Westfall is rapidly descending into chaos as brigands, gnolls, and hostile harvest golems overrun what was once the breadbasket of the kingdom. Without formal royal battalions answering the call, those who wish to defend the realm must look to local volunteers.",sp=0},{t="Sentinel Hill and the Militia",b="Upon following the road into Westfall, recruits find Gryan Stoutmantle stationed in the fortified stone tower atop Sentinel Hill. Stoutmantle leads the People's Militia, an unsanctioned coalition of resident farmers, retired veterans, and mercenaries organized in direct response to royal inaction. Reaching him marks an adventurer's entry into the bitter guerrilla war waged to keep the farmlands from falling completely into lawlessness.",sp=0}},faq={{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a veteran fighter and the commander of the People's Militia. Stationed inside the tower atop Sentinel Hill, he organizes defense efforts and recruits willing combatants to protect Westfall from the bandits and beasts threatening its farmers.",al={"gryan stoutmantle","who is stoutmantle","sentinel hill leader"}},{q="Why is the People's Militia needed?",a="The Stormwind army has withdrawn its focus to the immediate capital, leaving outer territories like Westfall with little to no crown support. The residents formed the People's Militia as a self-defense force to stave off bandits, rogue harvest automatons, and marauding Riverpaw gnolls.",al={"why militia","why no stormwind army","why is westfall abandoned"}},{q="Where is Sentinel Hill located?",a="Sentinel Hill stands near the center of Westfall along the main road. The hill is crowned with a sturdy stone watchtower and a fortified encampment where the People's Militia gathers.",al={"find sentinel hill","sentinel hill location","where to find stoutmantle"}},{q="Who sends adventurers on this assignment?",a="Several concerned figures offer this referral once an adventurer proves capable, including Goldshire's Marshal Dughan, border guards like Guard Thomas and Deputy Rainer, or displaced locals like Farmer Furlbrow and Farmer Saldean.",al={"who gives quest","quest givers","report to gryan quest giver"}},{q="What happens after reporting to Gryan?",a="Once you report to Stoutmantle, he enlists your combat prowess directly into the service of the People's Militia, beginning with assignments to cull the Defias brigands and gnolls threatening the region.",al={"what next","stoutmantle follow up","militia quest chain"}},{q="Is Westfall technically still part of the Alliance?",a="Yes, Westfall is an Alliance territory under the nominal authority of the Stormwind Kingdom. However, local frustration runs high because the crown's royal garrison has neglected the province, leaving its survival in the hands of armed citizens.",al={"is westfall alliance","does stormwind own westfall"}}},ang={["race:Human"]="For humans of the kingdom, walking into Westfall highlights the stark divide between the safe marble streets of Stormwind City and the harsh, neglected realities of its outlying farmlands.",["faction:Alliance"]="The assignment showcases the internal strain testing the Alliance: while the royal court argues over politics in Stormwind, ordinary citizens must organize their own militias to survive.",["class:Warrior"]="Gryan Stoutmantle values seasoned martial discipline above all else, making veteran frontline fighters indispensable assets to the outnumbered People's Militia."},kw={"defias","elwynn","gryan stoutmantle","marshal dughan","people's militia","sentinel hill","stormwind","westfall"},rel={"npc:gryan-stoutmantle","subzone:sentinel-hill","zone:westfall","quest:12","topic:stormwind-kingdom"},m={start="Marshal Dughan,Guard Thomas,Deputy Rainer,Farmer Furlbrow, orFarmer Saldean",["end"]="Gryan Stoutmantle",level="10",faction="Alliance",id=109},src={"Report to Gryan Stoutmantle"}}
E["quest:117"] = {t="quest",n="Thunderbrew",z="westfall",s="Thunderbrew is a straightforward brewing errand undertaken for the wandering dwarf Grimbooze Thunderbrew in Westfall. To prevent his latest batch from tasting more like stew than rich dwarven lager, Grimbooze requires fresh hops gathered from the surrounding countryside. Adventurers who assist him are rewarded with a fresh, frothy keg of his potent craft.",h="Thunderbrew is a straightforward brewing errand undertaken for the wandering dwarf Grimbooze Thunderbrew in...",sec={{t="A Dwarven Passion in Westfall",b="Even in the turbulent plains of Westfall, dwarven craftsmanship persists—particularly when it involves brewing. Grimbooze Thunderbrew, a member of the storied dwarven brewing clan, continues his family tradition far from the icy halls of Dun Morogh. Brewing good stout and lager requires precise ingredients, and Grimbooze insists that without proper hops, his current concoction threatens to turn into thick stew rather than refreshing ale.",sp=0},{t="The Art of the Keg",b="Grimbooze operates with rhythmic, rhyming enthusiasm, celebrating the foundational ingredients of hops, barley, yeast, and malt. When provided with fresh hops, he completes the fermentation process on the spot. Adventurers who keep him supplied receive whole kegs of Thunderbrew Lager, renowned for delivering an absolute assault on the taste buds.",sp=0}},faq={{q="Who is Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew is a dwarven brewer found roaming the landscape of Westfall. True to his famous clan's heritage, he is passionate about concocting potent lagers wherever he sets up camp, often speaking and chanting in cheerful rhymes.",al={"grimbooze","who is grimbooze","grimbooze lore"}},{q="Why does Grimbooze need hops?",a="Without fresh hops, Grimbooze's latest batch risks tasting thick and heavy like stew rather than crisp, potent lager. Hops provide the necessary bitterness and flavor balance essential to dwarven brewing.",al={"why hops","grimbooze hops","what are hops for"}},{q="What is Thunderbrew Lager?",a="Thunderbrew Lager is a heavy, celebrated dwarven beverage crafted by the Thunderbrew family. Grimbooze distributes it by the keg, promising a potent sensory experience that hits the palate with tremendous force.",al={"thunderbrew beer","keg of thunderbrew","what is thunderbrew"}},{q="Can you bring Grimbooze hops more than once?",a="Yes. Grimbooze's appetite for brewing is never truly sated, and he welcomes further deliveries of hops in exchange for additional kegs of his specialty brew.",al={"repeatable quest","is thunderbrew repeatable","more kegs"}},{q="Where does this task take place?",a="The task is carried out entirely in Westfall, where Grimbooze can be found camping and gathering supplies amidst the farmlands.",al={"thunderbrew location","where is grimbooze","quest zone"}},{q="Is Grimbooze related to the Thunderbrews in Dun Morogh?",a="Yes, Grimbooze shares his surname and trade with the renowned Thunderbrew brewing family of Kharanos in Dun Morogh, carrying their fiery passion for fermentation out into the wider kingdoms.",al={"thunderbrew distillery","grimbooze clan","thunderbrew family"}}},ang={["race:Dwarf"]="Finding a kinsman keeping the proud traditions of Kharanos alive on the rugged frontier of Westfall is always a welcome sight, especially when kegs are involved.",["profession:Cooking"]="Understanding the balance between barley, malt, and hops is second nature to anyone who appreciates the culinary arts and classic dwarven fermentation."},kw={"beer","brewing","dwarf","grimbooze","hops","keg","lager","thunderbrew","westfall"},rel={"npc:grimbooze-thunderbrew","zone:westfall"},m={start="Grimbooze Thunderbrew",level="15",faction="Alliance",id=117},src={"Thunderbrew (quest)"}}
E["quest:12"] = {t="quest",n="The People's Militia",z="westfall",s="This quest marks your first official trial under Gryan Stoutmantle at Sentinel Hill to prove yourself worthy of joining the People's Militia. With Stormwind's throne distracted and its army absent, local volunteers have taken up arms to defend Westfall against the brazen Defias Brotherhood. Your initial task sends you across the northern fields and mines to cull the outlaws choking local farmland.",h="This quest marks your first official trial under Gryan Stoutmantle at Sentinel Hill to prove yourself worthy...",sec={{t="The Price of Peace",b="Westfall was once the fertile breadbasket of Stormwind, but today it is overrun by outlaws, vagrants, and thieves. With the capital refusing to send royal soldiers to patrol the countryside, Gryan Stoutmantle organized the People's Militia as a desperate homegrown defense force based out of Sentinel Hill. To Stoutmantle, reclaiming the region requires decisive action, and anyone hoping to wear the militia's badge must demonstrate both combat readiness and absolute devotion to the protection of innocent settlers.",sp=0},{t="Clearing the Breadbasket",b="Before new recruits are trusted with deeper tactical operations, they are sent to break the Defias presence encroaching upon northern homesteads. Defias Trappers and Smugglers operate openly near the Jangolode Mine, Molsen Farm, and Furlbrow's Pumpkin Patch, pillaging stores and ambushing travelers. By cutting down these outlaws, prospective militia fighters disrupt the thieves' front-line foraging while proving to Stoutmantle's scouts that they possess the grit necessary to wage a protracted war on crime.",sp=0}},faq={{q="What is the People's Militia?",a="The People's Militia is a volunteer army organized by Gryan Stoutmantle and based at Sentinel Hill. Formed from local farmers, veterans, and commoners, they defend Westfall from the Defias Brotherhood because Stormwind's royal army has refused or failed to garrison the region.",al={"peoples militia","who are the militia","what is peoples militia"}},{q="Why isn't Stormwind sending its royal army?",a="With King Varian Wrynn missing, Stormwind's noble House of Nobles and council leadership have focused the kingdom's resources elsewhere, leaving outlying rural territories like Westfall to fend for themselves against rising outlaw bands.",al={"where is the army","why no guards in westfall","stormwind garrison"}},{q="Where can I find Defias Trappers and Smugglers?",a="They operate heavily in northern Westfall, particularly surrounding Furlbrow's Pumpkin Farm, Molsen Farm, and around the entrance to Jangolode Mine.",al={"trapper location","smuggler location","where are trappers"}},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a seasoned veteran and the commander of the People's Militia stationed at Sentinel Hill. Dedicated to defending the settlers of Westfall, he rallies volunteers to drive out the Defias Brotherhood and restore order to the countryside.",al={"who is stoutmantle","gryan stoutmantle lore","militia leader"}},{q="Does this quest lead to more militia assignments?",a="Yes. This task is only the introductory trial. Successful volunteers are assigned follow-up duties targeting increasingly dangerous echelons of the Defias Brotherhood scattered across the plains of Westfall.",al={"is this a chain","next quest","militia progression"}},{q="What is happening at Furlbrow's Pumpkin Farm?",a="The Furlbrows were driven away from their homestead when the Defias Brotherhood took control of the farmland, leaving outlaws and scavengers to pillage the fields and terrorize the northern roads.",al={"furlbrow farm","what happened to furlbrows","pumpkin farm"}}},ang={["faction:Alliance"]="This task demonstrates the stark divide within the kingdom: while Stormwind's nobility remains insulated behind capital walls, Alliance adventurers must stand alongside common settlers to preserve Westfall from ruin.",["race:Human"]="For humans of the kingdom, the plight of Westfall is deeply personal, as working-class families and generational farms fall victim to bandits while royal authorities look the other way.",["class:Paladin"]="Serving the People's Militia embodies the core calling of a paladin: offering protection to the defenseless and bringing righteous judgment to outlaws who exploit the vulnerable."},kw={"defias smuggler","defias trapper","furlbrow","gryan stoutmantle","jangolode","molsen farm","peoples militia","sentinel hill","westfall"},rel={"npc:gryan-stoutmantle","zone:westfall","subzone:sentinel-hill","subzone:jangolode-mine","subzone:furlbrow-s-pumpkin-farm","subzone:molsen-farm","topic:light"},m={start="Gryan Stoutmantle",level="12",faction="Alliance",id=12},src={"The People's Militia (quest)"}}
E["quest:13"] = {t="quest",n="The People's Militia",z="westfall",s="This task marks the escalating campaign of Gryan Stoutmantle's volunteer force to push the Defias Brotherhood out of Westfall. With the thieves moving from petty highway robbery to organized ransacking of key sites like Moonbrook and the Gold Coast Quarry, the People's Militia demands harsher retaliation.",h="This task marks the escalating campaign of Gryan Stoutmantle's volunteer force to push the Defias Brotherhood...",sec={{t="Escalating Violence",b="While early skirmishes with the Defias involved petty bandits harassing travelers on the roads, the threat rapidly deepens. Defias Looters and fire-slinging Pillagers have overrun critical economic centers across Westfall, thoroughly occupying Moonbrook, stripping the Alexston Farmstead, and commandeering the Gold Coast Quarry. Gryan Stoutmantle recognizes that if these brigands solidify their grip on these hubs, reclaiming the region will become impossible without a formal royal army.",sp=0},{t="The Militia's Philosophy",b="Lacking official soldiers or resources from Stormwind, Gryan Stoutmantle invokes the Holy Light and the moral fortitude of Westfall's remaining farmers. The Militia's war of attrition relies entirely on volunteers taking the fight directly into Defias strongholds. Driving out the looters is meant to deny the Brotherhood resources while signaling to fearful residents that there are still defenders willing to fight for Westfall's peace and prosperity.",sp=0}},faq={{q="What is the People's Militia?",a="The People's Militia is an armed volunteer defensive force organized by Gryan Stoutmantle. Composed largely of displaced Westfall farmers and sympathetic travelers, they formed to defend the province against the Defias Brotherhood after the royal court in Stormwind refused to deploy city guards.",al={"peoples militia","who are the militia","westfall militia"}},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a veteran human commander leading the defense of Westfall from the redoubt atop Sentinel Hill. Dedicated to the Light and his home, he coordinates the People's Militia in their desperate resistance against outlaw control.",al={"gryan","who is stoutmantle","stoutmantle lore"}},{q="Why are the Defias looting farms and quarries?",a="The Defias Brotherhood aims to cripple Westfall's food supply and seize raw materials. Taking the Gold Coast Quarry gives them control over stone and minerals, while capturing Moonbrook and farmsteads drives off honest folk and secures bases of operation for their criminal enterprise.",al={"why defias looting","defias in moonbrook","why pillagers at quarry"}},{q="Why hasn't Stormwind sent soldiers to Westfall?",a="King Varian Wrynn has mysteriously vanished, leaving the boy-king Anduin on the throne under Highlord Bolvar Fordragon's regency. Stormwind's noble House of Nobles is heavily gridlocked, leaving crown resources stretched thin and outlying territories like Westfall completely abandoned to local defenders.",al={"where are stormwind guards","why no help from stormwind","king varian westfall"}},{q="Where are Defias Pillagers and Looters found?",a="They concentrate heavily around captured settlements in south and western Westfall, notably the abandoned town of Moonbrook, the Gold Coast Quarry along the western bluffs, and the ruined Alexston Farmstead.",al={"pillager location","where are looters","defias locations"}}},ang={["faction:Alliance"]="This struggle highlights the bitter divide between the comfortable walls of Stormwind City and its starving borderlands, which are left entirely to their own devices.",["class:Paladin"]="Gryan Stoutmantle explicitly calls upon the Light to purge Westfall of criminal corruption, making this campaign a direct mission of justice for paladins.",["race:Human"]="For humans of the kingdom, fighting here is a tragic confrontation against former stonemasons and neighbors who have turned violently against their own people."},kw={"alexston farmstead","defias looter","defias pillager","gold coast quarry","gryan stoutmantle","moonbrook","peoples militia","sentinel hill","westfall"},rel={"quest:12","npc:gryan-stoutmantle","subzone:sentinel-hill","zone:westfall","subzone:moonbrook","subzone:gold-coast-quarry","subzone:alexston-farmstead","topic:light"},m={start="Gryan Stoutmantle",level="14",faction="Alliance",id=13},src={"The People's Militia (2)"}}
E["quest:132"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="This errand delivers vital underground intelligence from Wiley the Black back to Gryan Stoutmantle at Sentinel Hill. Wiley's dispatch reveals that the Defias Brotherhood is not merely a scattered gang of bandits, but an organized force colluding with local gnolls, kobolds, and goblins. Stoutmantle relies on this intelligence to measure the full scale of the conspiracy choking Westfall.",h="This errand delivers vital underground intelligence from Wiley the Black back to Gryan Stoutmantle at...",sec={{t="A Dangerous Dispatch",b="Wiley the Black claims that disclosing what he knows about the Defias could forfeit his life. Operating along the fringes of Redridge and Westfall, Wiley has caught wind of an operation far grander than highway robbery. His sealed note details how the Brotherhood has managed to coordinate efforts across disparate, normally hostile groups throughout the countryside.",sp=0},{t="Unlikely Alliances",b="The core of Wiley's warning is the alarming network the Defias has assembled. Rather than working in isolation, the red-masked outlaws have enlisted gnoll packs, kobold diggers, and opportunistic goblin engineers. This combination of brutal muscle, burrowing labor, and mechanical cunning signals an enterprise that outstrips anything the People's Militia initially anticipated.",sp=0},{t="Stoutmantle's Uneasy Reliance",b="Gryan Stoutmantle holds little love for Wiley, openly lamenting that he did not leave the rogue to rot when he had the opportunity. Even so, Westfall cannot afford pride. With Stormwind ignoring pleas for military aid, the People's Militia must take actionable intelligence wherever it can be found.",sp=0}},faq={{q="What is Wiley's Note about?",a="The note contains Wiley the Black's warning that the Defias Brotherhood is coordinating with gnolls, kobolds, and goblin engineers. It informs the People's Militia that the outlaws are preparing a massive operation far beyond petty banditry.",al={"wiley note","what is in the note","wiley the black note"}},{q="Who is Wiley the Black?",a="Wiley the Black is a shady contact stationed at Lakeshire in Redridge. Though Gryan Stoutmantle considers him an untrustworthy scoundrel, Wiley possesses extensive ties to the criminal underworld and critical information on Defias activities.",al={"who is wiley","wiley the black lore","wiley lakeshire"}},{q="Why would the Defias ally with gnolls and kobolds?",a="The Defias exploit local creatures for territory control and cheap labor. Gnolls provide brutish skirmishers to distract local defenders, while kobolds serve as tunnelers in regional mines, and goblin tinkers contribute heavy machinery and demolition tools.",al={"why defias use gnolls","kobolds and defias","defias allies"}},{q="Why does Gryan Stoutmantle dislike Wiley?",a="Gryan Stoutmantle is a disciplined former soldier who views Wiley as a common cutpurse and criminal. Stoutmantle regrets sparing him from prison in the past, though he concedes that Wiley's underworld ears are indispensable.",al={"stoutmantle and wiley","why hate wiley"}},{q="Where does this message fit into the militia's investigation?",a="This delivery represents the bridge between local reconnaissance and uncovering the deeper Defias conspiracy. Returning Wiley's message spurs Stoutmantle to probe further into the conspiracy's leadership and staging grounds.",al={"defias chain step","what quest is this"}},{q="Why isn't Stormwind handling this threat?",a="With King Varian Wrynn missing, the Stormwind House of Nobles refuses to divert royal soldiers or funding to defend Westfall. The region is left to defend itself through the ragtag People's Militia led by Stoutmantle.",al={"stormwind help westfall","where are the guards"}}},ang={["faction:Alliance"]="The discovery of cross-species coordination between human outlaws, gnolls, and goblins highlights the severe security vacuum left on Stormwind's western borders.",["class:Rogue"]="Wiley the Black is an example of an operative walking the line between outlaw and useful informant, illustrating how underworld connections drive wartime intelligence.",["race:Human"]="For the people of Westfall and Redridge, the note confirms that the bandits pillaging their family homesteads are executing a deliberate, coordinated campaign."},kw={"defias brotherhood","gnolls","goblins","gryan stoutmantle","kobolds","sentinel hill","westfall","wiley the black","wiley's note"},rel={"quest:65","npc:wiley-the-black","npc:gryan-stoutmantle","topic:defias-brotherhood","zone:westfall","topic:gnoll","topic:kobold","topic:goblin"},m={start="Wiley the Black",["end"]="Gryan Stoutmantle",level="18",faction="Alliance",id=132},src={"The Defias Brotherhood (2)"}}
E["quest:135"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="This quest marks a critical turning point in the Westfall campaign against the bandits plaguing the countryside. Gryan Stoutmantle sends you to Stormwind to deliver an intriguing note to Master Mathias Shaw, suspecting the Defias gang is connected to the old Stonemasons Guild.",h="This quest marks a critical turning point in the Westfall campaign against the bandits plaguing the...",sec={{t="A Slip of the Tongue",b="While investigating the chaos in Westfall, Gryan Stoutmantle notices a curious detail in Wiley's communications: a mention of the Stonemasons. The guild of builders that rebuilt Stormwind City after the First War has long been thought scattered or dissolved. If the Defias Brotherhood shares ties with them, this rural insurgency is far more than a disorganized mob of outlaws.",sp=0},{t="Old Town Secrets",b="Stoutmantle cannot verify these suspicions from Sentinel Hill. For true kingdom intelligence, he directs you to Master Mathias Shaw, leader of Stormwind's covert intelligence wing, SI:7. Operating from the Barracks in Old Town, Shaw gathers whispers and secrets from across the realm, making him the only man capable of untangling the Defias origins.",sp=0},{t="The Shadow Over the Crown",b="When presented with Wiley's Note, Shaw recognizes the gravity of the situation immediately. He confirms that the rebellion in Westfall runs much deeper and carries far more political complexity than a simple peasant militia commander like Stoutmantle understands, pointing directly back to Stormwind's own turbulent past.",sp=1}},faq={{q="Why does Gryan Stoutmantle send you to Stormwind?",a="Stoutmantle discovers a reference to the Stonemasons in Wiley's note. Realizing this points to potential political intrigue rather than simple banditry, he sends you to Master Mathias Shaw, Stormwind's spymaster, to confirm the connection.",al={"why go to stormwind","why stormwind quest","stoutmantle stormwind errand"}},{q="Who is Mathias Shaw?",a="Master Mathias Shaw is the head of SI:7, the covert intelligence and espionage branch of the Kingdom of Stormwind. He operates out of the headquarters tucked away in the Old Town Barracks.",al={"who is shaw","mathias shaw role","si7 leader"}},{q="Where do I find Mathias Shaw?",a="Shaw is located on the second floor of the SI:7 headquarters in the Barracks of Old Town, Stormwind City.",al={"where is shaw","shaw location","find mathias shaw"}},{q="What is the connection between the Defias and the Stonemasons?",a="The Stonemasons Guild rebuilt Stormwind after its destruction in the First War. After a bitter dispute over payment with the House of Nobles, the guild was cheated and exiled, subsequently reforming in secret as the Defias Brotherhood to exact revenge.",al={"defias stonemasons","are defias stonemasons","stonemason connection"},sp=1},{q="What is Wiley's Note?",a="It is a dispatch written by Wiley, an operative connected to the Westfall investigations, which inadvertently links the actions of the Defias Brotherhood to the former Stonemasons Guild.",al={"wileys note","what is the note","note to shaw"}},{q="Does Highlord Bolvar or the boy-king know about this?",a="Matters of covert state security are filtered through Mathias Shaw and SI:7 before reaching Highlord Bolvar Fordragon and the throne. Shaw's response reveals that the upper echelons of intelligence are already quietly tracking this crisis.",al={"does the king know","does bolvar know","stormwind government knowledge"}}},ang={["class:Rogue"]="Visiting SI:7 headquarters brings you face-to-face with Mathias Shaw, the grandmaster of Stormwind's rogues and spies, grounding Westfall's local turmoil in grander tradecraft.",["race:Human"]="For humans of Stormwind, this mission bridges the lawless frontier of Westfall with the bitter, unresolved political scandals that followed the rebuilding of their capital.",["faction:Alliance"]="The quest exposes internal fractures within the Alliance's primary kingdom, showing that not all threats come from monstrous outsiders, but from betrayed citizens."},kw={"brotherhood","defias","gryan stoutmantle","mathias shaw","old town","si:7","stonemasons","westfall","wiley's note"},rel={"npc:mathias-shaw","npc:gryan-stoutmantle","topic:defias-brotherhood","quest:65","subzone:old-town","zone:westfall","topic:stormwind-kingdom","quest:2300"},m={start="Gryan Stoutmantle",["end"]="Master Mathias Shaw",level="18",faction="Alliance",id=135},src={"The Defias Brotherhood (3)"}}
E["quest:136"] = {t="quest",n="Captain Sanders' Hidden Treasure",z="westfall",s="Captain Sanders' Hidden Treasure is the opening step of a multi-part treasure hunt along the coast of Westfall. Triggered by a battered parchment map, it sends treasure-seekers scouring the shoreline for the late captain's personal footlocker. Finding the buried locker sets off a pursuit across the region for his hidden plunder.",h="Captain Sanders' Hidden Treasure is the opening step of a multi-part treasure hunt along the coast of...",sec={{t="A Sailor's Last Bequest",b="The sea off Westfall's western coast is littered with shipwrecks, shattered hulls, and the restless spirits of drowned sailors. Among those lost to the depths was Captain Sanders, an old seafarer who met a watery grave. Rather than letting his hard-won fortune be lost to the Great Sea or stolen outright by scavengers, the old salt penned a series of cryptic instructions, leaving behind a trail that only a determined adventurer could retrace.",sp=0},{t="The Rusty Anchor",b="The first step of the hunt directs the finder toward a lone rusted anchor resting in the surf on the western coast. Hidden half-buried in the sand near a wreck, the captain's old footlocker has survived the battering waves. Inside lies not gold, but seawater, sand, and an unexpected guardian: a scurrying crab clutching the next piece of Sanders' puzzle.",sp=1}},faq={{q="Who was Captain Sanders?",a="Captain Sanders was a mariner whose vessel wrecked along the treacherous shores of Westfall. Knowing he was doomed to a watery grave, he left behind a map and a series of clues leading to his hidden plunder.",al={"captain sanders lore","who is sanders","sanders backstory"}},{q="Where is the footlocker located?",a="The footlocker is half-buried in the sand along the western coast of Westfall. While many shipwrecks line the beaches, Sanders noted that it lies near a distinctive, solitary rusty anchor resting near the shoreline.",al={"footlocker location","where is the rusty anchor","find sanders footlocker"}},{q="Does the footlocker contain the captain's treasure?",a="No. The footlocker only contains sand, seawater, and a shore crab scurrying away with a scrap of paper in its claws, revealing the next clue in Sanders' treasure trail.",al={"is treasure in the chest","what is in the footlocker","where is the gold"},sp=1},{q="How many clues are in Captain Sanders' treasure hunt?",a="The hunt spans four steps across the coast and countryside of Westfall, beginning with the map and culminating in the recovery of Captain Sanders' actual buried treasure chest.",al={"how long is sanders quest","how many parts","sanders quest chain"}},{q="Why did Captain Sanders bury his treasure in Westfall?",a="Sanders wrecked his vessel off the coast of Westfall. Faced with impending death, the captain hid his chest and split the clues across familiar coastal landmarks so that a worthy finder could salvage his worldly goods.",al={"why hide treasure","why westfall coast"}},{q="Can Horde players follow this treasure map?",a="Yes. Captain Sanders' map and the subsequent clues are neutral, allowing any adventurer who washes up on the coast or braves the shores of Westfall to follow his trail.",al={"can horde do this","horde sanders quest","faction neutral treasure"}}},ang={["class:Rogue"]="A pirate's treasure hunt is second nature to scoundrels and privateers who know the value of following a dead sailor's map along a lawless coast.",["faction:Alliance"]="Westfall's coast is fraught with coastal murlocs and wreckage, making any recovery of sea-bound fortune a small victory amidst the kingdom's frontier turmoil."},kw={"captain sanders","footlocker","hidden treasure","rusty anchor","shipwreck","treasure map","westfall coast"},rel={"zone:westfall"},m={start="Captain Sanders' Treasure Map",["end"]="Captain's Footlocker",level="16",faction="Neutral",id=136},src={"Captain Sanders' Hidden Treasure (Classic 1)"}}
E["quest:138"] = {t="quest",n="Captain Sanders' Hidden Treasure",z="westfall",s="This quest is the second leg of a treasure hunt devised by the enigmatic pirate Captain Sanders across Westfall. Following instructions recovered from an abandoned seaside footlocker, searchers must venture east away from the coast to find another clue hidden inside an old barrel near ruined stonework.",h="This quest is the second leg of a treasure hunt devised by the enigmatic pirate Captain Sanders across...",sec={{t="A Trail of Inland Riddles",b="Rather than burying his plunder under a single marked cross on a sandy beach, Captain Sanders scattered riddles across the countryside. Those who successfully crack his first cipher along the shore are told to leave the churning tide behind and scale the rocky bluffs inland, following a route that climbs steadily toward the main thoroughfares of Westfall.",sp=0},{t="Ruins Along the Road",b="The clue directs seekers directly toward an old chimney standing among roadside ruins, where a discarded, weathered barrel conceals the next message. The pirate evidently knew the landmarks of Westfall intimately, using remnants of ruined farmsteads to safeguard the milestones of his elaborate scavenger hunt.",sp=0}},faq={{q="Who was Captain Sanders?",a="Captain Sanders was a pirate captain who operated along the coasts of Westfall. Instead of stashing his loot in an ordinary hoard, he scattered a chain of clues and riddles across the territory to challenge anyone aspiring to claim his hidden wealth.",al={"captain sanders lore","who is sanders","sanders pirate"}},{q="Where does this clue send you?",a="The clue directs searchers due east up the bluffs from the western sea, continuing until they hit the road. There, beside an old ruined stone chimney, sits a broken barrel hiding the subsequent piece of the puzzle.",al={"where do i go","clue location","chimney location"}},{q="Why did Sanders hide his treasure in pieces?",a="Pirates routinely hid their ill-gotten gains to keep them out of the hands of rivals and the authorities. Sanders took additional precautions by dividing his directions into multi-step riddles, ensuring only someone persistent and resourceful could trace the trail to the final cache.",al={"why clues","why the scavenger hunt"}},{q="Is the treasure hunt dangerous to follow?",a="While the clues themselves are parchment and old containers, traversing Westfall brings searchers into contact with wandering beasts, prowling gnolls, and hostile members of the Defias Brotherhood who control the surrounding fields and abandoned homesteads.",al={"is it safe","westfall dangers"}},{q="What kind of ruins is the barrel hidden near?",a="The barrel sits beside the crumbling stone chimney of a ruined building near the roadside, one of many homesteads across Westfall left abandoned or demolished during recent years of turmoil.",al={"chimney ruins","which building"}},{q="Does this quest reveal the treasure itself?",a="No. This step only yields another clue. Sanders designed his scavenger hunt to lead seekers through several stages across the region before uncovering the actual prize.",al={"is this the final chest","do i get loot now"}}},ang={["class:Rogue"]="Deciphering pirate ciphers and navigating abandoned ruins in search of forgotten spoils is second nature to those who favor stealth, cunning, and quick profit.",["faction:Alliance"]="While Westfall's local militia struggles against organized outlaws, pursuing Sanders' trail provides a rare diversion that traverses both the lawless coastlines and untended inland roads."},kw={"broken barrel","captain sanders","chimney","pirate","sanders treasure","treasure hunt","westfall"},rel={"quest:136","zone:westfall"},m={start="Captain's Footlocker",["end"]="Broken Barrel",level="16",faction="Neutral",id=138},src={"Captain Sanders' Hidden Treasure (Classic 2)"}}
E["quest:139"] = {t="quest",n="Captain Sanders' Hidden Treasure",z="westfall",s="This quest represents the third leg of Captain Sanders' scavenger hunt across the shores of Westfall. Found inside a broken barrel, this parchment directs treasure seekers north toward an old jug resting by a coastal windmill. Following these cryptic directions draws adventurers further along the late pirate's trail toward his fabled stash.",h="This quest represents the third leg of Captain Sanders' scavenger hunt across the shores of Westfall.",sec={{t="A Pirate's Breadcrumb Trail",b="Captain Sanders was careful never to leave the whereabouts of his plunder on a single sheet of parchment. Instead, he divided his directions into a sequential scavenger hunt scattered across the western shoreline of Westfall. Each discovered clue points only to the next intermediate container, ensuring that any opportunistic looter would need to physically traverse the pirate-infested bluffs to claim the prize.",sp=0},{t="North Toward the Bluffs",b="The clue retrieved from the broken barrel instructs seekers to head directly north, straight as a crow flies, toward the sea cliffs. Perched upon these bluffs stands an isolated windmill, beside which an abandoned jug conceals the next link in the pirate's puzzle. For travelers navigating coastal Westfall, following Sanders' clues means navigating territory crawled by murlocs and Defias scavengers alike.",sp=0}},faq={{q="What is Captain Sanders' Hidden Treasure?",a="Captain Sanders was a buccaneer who hid his riches along the Westfall coastline. Rather than drawing a traditional map, he left a trail of written riddles in barrels, chests, and jugs stretching across the countryside.",al={"sanders treasure","what is this quest","who is sanders"}},{q="Where does this third clue lead?",a="The parchment instructs you to travel due north from the broken barrel to the bluffs overlooking the ocean. There, near a lone windmill, sits an old jug containing the final clue.",al={"where do i go","jug location","where is the windmill"}},{q="Why did Sanders hide his directions in pieces?",a="Pirates along the Great Sea often took elaborate precautions to protect their spoils from mutinous crewmates and rival marauders. By splitting the route into multiple hidden markers, Sanders ensured that finding one clue would not automatically forfeit his treasure.",al={"why clues","why not a full map"}},{q="Can Horde players complete this trail?",a="The clues and objects tied to Captain Sanders' cache are neutral and can be interacted with by any adventurer who finds them, though Westfall lies deep within Alliance-aligned territory.",al={"is this alliance only","horde sanders treasure"}},{q="Does this clue directly reveal the chest?",a="No. The jug near the coastal windmill contains another clue that points to the actual final resting place of Sanders' chest, making this the penultimate step in the hunt.",al={"is the treasure in the jug","final step"}},{q="What dangers surround the trail to the windmill?",a="The western bluffs and beaches of Westfall are heavily prowled by Riverpaw gnolls, coastal murlocs, and roving Defias bandits, making a straight march north treacherous for the unwary.",al={"dangers on the bluffs","what mobs are there"}}},ang={["class:Rogue"]="Following a scoundrel's trail of dead drops and concealed messages along the bluffs feels like second nature to any rogue who appreciates coastal contraband.",["faction:Alliance"]="While Westfall struggles under the grip of famine and Defias outlaws, finding Sanders' lost pirate plunder offers independent adventurers a welcome windfall."},kw={"bluffs","broken barrel","captain sanders","hidden treasure","old jug","pirate clue","westfall","windmill"},rel={"quest:136","zone:westfall"},m={start="Broken Barrel",["end"]="Old Jug",level="16",faction="Neutral",id=139},src={"Captain Sanders' Hidden Treasure (Classic 3)"}}
E["quest:14"] = {t="quest",n="The People's Militia",z="westfall",s="This task marks the culmination of Gryan Stoutmantle's campaign to clear Westfall's roads and farmlands of the Defias Brotherhood. By hunting down the seasoned brigands entrenched in the southern Dagger Hills, volunteers prove their dedication and earn full induction into Sentinel Hill's People's Militia.",h="This task marks the culmination of Gryan Stoutmantle's campaign to clear Westfall's roads and farmlands of...",sec={{t="Purging the Dagger Hills",b="The northern farmlands of Westfall have suffered greatly under the Defias Brotherhood, but the outlaws who escaped Stoutmantle's early sweeps retreated south into the rocky crags of the Dagger Hills. Operating out of the rugged terrain, Defias Highwaymen, Pathstalkers, and Knuckledusters have continued to raid rural homesteads and intercept travelers. To break their hold over the southern half of the region, the People's Militia sends hardened recruits into the hills to dismantle these raiding bands directly.",sp=0},{t="Stoutmantle's Crusade",b="Gryan Stoutmantle formed the People's Militia after returning home from fighting the Scourge in Lordaeron, only to discover Westfall completely abandoned by the royal garrison in Stormwind. Faced with an unchecked criminal syndicate and starving farmers driven from their land, he organized local volunteers to take up arms. Fully completing this final tier of patrol duty earns adventurers formal induction into the militia, carrying Stoutmantle's blessing in the Light as the fight against the brotherhood deepens.",sp=0}},faq={{q="Where are the Dagger Hills?",a="The Dagger Hills lie in southern Westfall, southwest of Sentinel Hill. The rugged ridges and abandoned mineheads there serve as a staging ground and redoubt for the Defias Brotherhood's tougher fighters.",al={"dagger hills location","where to find dagger hills","where are the highwaymen"}},{q="Why is the People's Militia fighting the Defias alone?",a="With King Varian Wrynn missing and resources stretched thin, the House of Nobles in Stormwind refuses to deploy the royal army to protect rural Westfall. Gryan Stoutmantle and the local farmers had no choice but to form their own volunteer force to defend their homes.",al={"why no stormwind guards","where is stormwind army","why is westfall abandoned"}},{q="What does completing this task achieve?",a="Eliminating the highwaymen, pathstalkers, and knuckledusters breaks the Defias hold on southern Westfall's roads and earns you formal induction into the People's Militia under Gryan Stoutmantle's command.",al={"peoples militia completion","militia induction","what do i get for finishing"}},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a veteran soldier who fought during the third war in Lordaeron. Upon returning home to Westfall and witnessing the Kingdom of Stormwind abandon its rural peasantry, he established the People's Militia at Sentinel Hill to fight back against the Defias.",al={"gryan background","who is stoutmantle","sentinel hill leader"}},{q="What kind of Defias hide in the Dagger Hills?",a="The Dagger Hills shelter experienced Defias Highwaymen, deadly Pathstalkers, and brutal Knuckledusters who orchestrate raids against southern Westfall and guard the Brotherhood's deeper strongholds.",al={"defias mobs southern westfall","what are pathstalkers and knuckledusters","who is in dagger hills"}},{q="How does this connect to Lordaeron?",a="Gryan Stoutmantle references having recently returned from the 'tainted lands of Lordaeron,' where the Alliance fought against the Scourge. Surviving that grim theater gave him the resolve to organize Westfall's defence when local authorities failed.",al={"stoutmantle lordaeron","tainted lands of lordaeron","gryan war history"}}},ang={["race:Human"]="For humans of Stormwind, this assignment represents standing up for forgotten countrymen whose livelihoods were abandoned by the capital's political elite.",["class:Paladin"]="Stoutmantle invokes the blessing of the Light upon inductees, reflecting the holy ideals of justice and protecting the defenseless against predatory outlaws.",["faction:Alliance"]="The failure of Stormwind to protect Westfall forces the Alliance's common folk to shed their own blood to maintain order in their homeland."},kw={"dagger hills","defias highwayman","defias knuckleduster","defias pathstalker","gryan stoutmantle","people's militia","sentinel hill","westfall"},rel={"npc:gryan-stoutmantle","subzone:sentinel-hill","subzone:dagger-hills","quest:12","zone:westfall","topic:lordaeron","topic:light"},m={start="Gryan Stoutmantle",level="17",faction="Alliance",id=14},src={"The People's Militia (3)"}}
E["quest:140"] = {t="quest",n="Captain Sanders' Hidden Treasure",z="westfall",s="This marks the conclusion of Captain Sanders' scavenger hunt across Westfall. Following a whiskey-soaked note discovered inside an old jug, fortune seekers are directed off the western coast to claim a long-buried stash. The venture leads out into the open sea, away from the troubles of the mainland to a remote coastal islet.",h="This marks the conclusion of Captain Sanders' scavenger hunt across Westfall.",sec={{t="A Sailor's Trail",b="Captain Sanders left a trail of clues scattered across the Westfall coastline, daring any adventurous soul to piece them together. The final parchment, pulled from the dregs of his favorite whiskey jug, provides the final bearing. With smudged ink and a distinct smell of liquor, the captain's instructions are straightforward: head directly west to the water's edge and plunge into the waves.",sp=0},{t="The Lonely Islet",b="Off the coast of Westfall, small rocky outcroppings jut out from the churning Great Sea. Swimming due west leads straight to one such isolated isle where Captain Sanders cached his prize. Half-hidden and braving years of salty surf, the locked chest's rusty hinges stubbornly give way to those persistent enough to see the buccaneer's game through to its end.",sp=1}},faq={{q="Where does the final clue lead?",a="The whiskey-soaked note inside the Old Jug directs treasure hunters to head directly west to the Westfall shore and keep swimming out into the ocean. The chest sits waiting on a small island out in the water.",al={"where is the chest","sanders treasure location","final clue destination"}},{q="Who was Captain Sanders?",a="Captain Sanders was a buccaneer who sailed the waters along Westfall. Rather than keeping his spoils in a bank or stronghold, he created a riddle-filled trail of clues along the shoreline, burying his lockbox out on a remote island off the coast.",al={"who is captain sanders","sanders lore","captain sanders background"}},{q="Why is the final clue smelling like whiskey?",a="The final instructions were tucked inside Captain Sanders' discarded whiskey jug near the coast. The dampness and spirits caused the ink to run over time, though the directions remain legible enough to follow.",al={"whiskey note","old jug clue"}},{q="How many steps are in this treasure hunt?",a="The hunt consists of four stages in total. It begins with a sea-battered treasure map found along the coast and winds through several hidden containers—including a footlocker, a barrel, and a whiskey jug—before concluding at the buried chest.",al={"how long is sanders chain","sanders quest parts","captain sanders questline"}},{q="Is the island dangerous to reach?",a="The primary challenge is the long swim offshore into the Great Sea. While coastal waters in Westfall are frequently troubled by aggressive murlocs and sea beasts, the islet itself serves mainly as Sanders' private cache.",al={"swimming to sanders chest","island danger","murlocs near chest"}},{q="What state is the treasure chest in?",a="Exposed to the damp sea air and crashing surf, the chest has suffered from the elements. Its hinges are heavily rusted, though with a bit of leverage, it can be forced open to claim the goods left inside.",al={"condition of chest","is the chest locked","rusty chest"}}},ang={["class:Rogue"]="Following a scoundrel's trail across deserted beaches and out to sea feels like second nature to any rogue who appreciates pirate contraband.",["race:Human"]="For humans defending Westfall from Defias brigands and gnolls, tracking down a forgotten local pirate's stash offers a welcome respite from farm patrol."},kw={"captain sanders","final clue","hidden treasure","island","locked chest","old jug","treasure hunt","westfall"},rel={"quest:136","zone:westfall"},m={start="Old Jug",["end"]="Locked Chest",level="16",faction="Neutral",id=140},src={"Captain Sanders' Hidden Treasure (Classic 4)"}}
E["quest:141"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="Carrying intelligence from Master Mathias Shaw back to Westfall, this mission uncovers the mastermind behind the red-masked brigands. Shaw's report reveals that the Defias Brotherhood is led by Edwin VanCleef, the very architect who rebuilt Stormwind City after the First War.",h="Carrying intelligence from Master Mathias Shaw back to Westfall, this mission uncovers the mastermind behind...",sec={{t="A Builder Turned Bandit",b="For months, Gryan Stoutmantle and the People's Militia fought a seemingly faceless uprising of highwaymen, thieves, and cutthroats across Westfall. When Master Mathias Shaw of SI:7 examines the evidence gathered from Defias couriers, he pieces together a shocking truth: the guild of architects and stonemasons who reconstructed the white ramparts of Stormwind never disbanded. Instead, their leader, Edwin VanCleef, took them underground.",sp=1},{t="Bitterness and Betrayal",b="Following the devastation of the First War, Stormwind lay in ashes. VanCleef's Stonemasons' Guild undertook the monumental effort of restoring the kingdom's capital, transforming it into the jewel of humanity once again. Yet when the work concluded, a bitter dispute arose over compensation. Dissatisfied with their treatment by the crown and the House of Nobles, VanCleef and his artisans took up daggers and red bandanas, turning from civic craft to violent rebellion against the throne.",sp=1},{t="Stoutmantle's Disbelief",b="When Shaw's report reaches Sentinel Hill, Gryan Stoutmantle finds the news difficult to stomach. Stoutmantle remembers VanCleef not as a cutthroat skulking in the shadows of the countryside, but as an industrious and gifted artisan whose work sheltered thousands of returning citizens. Faced with such an alarming accusation, the militia commander demands concrete evidence before fully accepting that Stormwind's chief architect is orchestrating Westfall's ruin.",sp=1}},faq={{q="What is Shaw's Report?",a="It is a confidential intelligence briefing prepared by Master Mathias Shaw, leader of SI:7. It outlines the history of the Stonemasons' Guild, their fallout with the royal court after rebuilding Stormwind, and the revelation that Edwin VanCleef is the ringleader behind the Defias Brotherhood.",al={"shaws report","mathias shaw document","the report to stoutmantle"}},{q="Who is Edwin VanCleef?",a="Edwin VanCleef was the Grand Master of the Stonemasons' Guild. He oversaw the reconstruction of Stormwind City after it was razed by the orcs during the First War. After an unpaid labor dispute with the crown, he organized his disenfranchised laborers into the Defias Brotherhood.",al={"vancleef identity","who is edwin vancleef","edwin vancleef lore"}},{q="Why is Gryan Stoutmantle skeptical of the report?",a="Gryan Stoutmantle remembers Edwin VanCleef as a brilliant, hardworking civic leader who rebuilt the nation's capital. The idea that such an esteemed craftsman could fall so far and become a ruthless bandit king terrorizing innocent farmers is hard for him to accept without undeniable proof.",al={"why doesnt gryan believe it","stoutmantle reaction","why does gryan need proof"}},{q="Why did the Stonemasons turn against Stormwind?",a="After rebuilding the capital from the ruins of the First War, the Stonemasons' Guild found themselves mistreated and shortchanged by the King and the House of Nobles. Feeling cheated out of their fair wage and cast aside, VanCleef and his followers rebelled.",al={"why are defias mad","stonemason dispute","vancleef motive"}},{q="What role does SI:7 play in this quest?",a="Master Mathias Shaw leads SI:7, Stormwind's intelligence service operating from Old Town. While the People's Militia fights on the front lines in Westfall, SI:7 pieces together captured coded communications to identify the true leadership and motives behind the uprising.",al={"why mathias shaw","si7 involvement","rogue guild stormwind"}},{q="Where does this investigation lead next?",a="Because Stoutmantle demands irrefutable proof of VanCleef's complicity, he directs his agents to track down a former associate who can provide direct testimony confirming VanCleef's leadership of the Defias.",al={"what comes next","next quest defias","after shaws report"},sp=1}},ang={["faction:Alliance"]="The rebellion of the Stonemasons reveals deep fractures within the kingdom: the very workers who rebuilt Stormwind's stone ramparts now threaten to tear them down.",["class:Rogue"]="Carrying intelligence directly from Mathias Shaw showcases the reach of SI:7, highlighting the contrast between the crown's shadow operatives and VanCleef's rogue highwaymen.",["race:Human"]="For humans of Stormwind, this revelation hits close to home. The walls of their homes and the Cathedral itself were built by the very men now pillaging the Westfall countryside."},kw={"defias","sentinel hill","shaw","stonemasons","stormwind","stoutmantle","vancleef","westfall"},rel={"npc:gryan-stoutmantle","npc:edwin-vancleef","topic:defias-brotherhood","zone:westfall","topic:stormwind-kingdom","topic:first-war"},m={start="Master Mathias Shaw",["end"]="Gryan Stoutmantle",level="18",faction="Alliance",id=141},src={"The Defias Brotherhood (4)"}}
E["quest:142"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="This critical mission sends adventurers along the dusty roads of Westfall to hunt down a roving Defias Messenger. Intercepting his dispatches allows Gryan Stoutmantle and the People's Militia to uncover vital intelligence regarding the bandit uprising.",h="This critical mission sends adventurers along the dusty roads of Westfall to hunt down a roving Defias...",sec={{t="Intercepting the Courier",b="Gryan Stoutmantle's scouts noticed an elusive Defias Messenger traveling between the key outlaw hubs of Moonbrook, the Gold Coast Quarry, and the Jangolode Mine. Unlike the ordinary thugs holding the countryside, this courier carries vital written orders across the region. Stoutmantle orders the courier captured or killed so that the People's Militia can read the contents of his satchel and deduce where the brotherhood commands its forces.",sp=0},{t="A Trail of Ink",b="The message recovered from the courier provides undeniable confirmation that Edwin VanCleef, the legendary former leader of the Stonemasons Guild, is personally orchestrating the Defias insurgency. While the intercepted note affirms VanCleef's command over the local cells, it still falls short of pinpointing his secret base of operations.",sp=1},{t="A Fortuitous Turn",b="Just as the messenger's orders confirm VanCleef's leadership, the People's Militia catches a major break. A desperate bandit caught attempting to steal farmer Saldean's wagon agrees to turn traitor in exchange for his life. With written proof in hand, Stoutmantle shifts his focus to this turncoat, hoping he will escort an escort into the heart of the Defias hideout.",sp=1}},faq={{q="Where does the Defias Messenger travel?",a="The Defias Messenger begins his patrol in Moonbrook outside the blacksmith shop. From there, he walks the roads north to inspect the Gold Coast Quarry and the Jangolode Mine, entering both underground digs before retracing his path back to Moonbrook.",al={"messenger route","where is defias messenger","find messenger"}},{q="What does the intercepted message reveal?",a="The mysterious message provides undeniable, written evidence that Edwin VanCleef is personally running the Defias Brotherhood and directing their criminal operations across the region.",al={"what was in the message","mysterious message text","vancleef note"},sp=1},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is the field commander of the People's Militia, headquartered at Sentinel Hill. Frustrated by the lack of royal Stormwind guards, he organizes volunteers and adventurers to defend Westfall from Defias raiders.",al={"stoutmantle role","who gives this quest"}},{q="Why is the messenger visiting the mines?",a="The brotherhood has overrun Westfall's mineral wealth, using sites like the Jangolode Mine and Gold Coast Quarry for raw supplies, shelter, and staging grounds. The messenger keeps these disparate operations unified under VanCleef's directives.",al={"why gold coast quarry","why jangolode mine"}},{q="Does catching the messenger reveal the Defias hideout?",a="No. While the message proves VanCleef's active role, it does not reveal the location of the Defias headquarters. However, a thief captured at Farmer Saldean's wagon during your mission agrees to betray the gang and lead the way.",al={"did we find the hideout","where is hideout"},sp=1},{q="Who is Edwin VanCleef?",a="Edwin VanCleef was the Grand Mason of the Stonemasons Guild who rebuilt Stormwind City after the First War. When the nobility refused to pay for the work, VanCleef organized the stonemasons and common folk into the vengeful Defias Brotherhood.",al={"who is vancleef","defias leader"}}},ang={["faction:Alliance"]="Stormwind's silence forces Westfall's People's Militia to handle regional intelligence on their own, tracking couriers along lonely dirt roads without royal garrison support.",["class:Rogue"]="Tracking Defias couriers highlights how skilled scouts and cutpurses coordinate a sprawling shadow network right under the militia's nose.",["race:Human"]="For humans of the kingdom, tracing the dispatches to Edwin VanCleef exposes the bitter, lingering fallout of Stormwind's political and labor disputes."},kw={"defias","jangolode","messenger","moonbrook","quarry","saldean","stoutmantle","vancleef","westfall"},rel={"npc:gryan-stoutmantle","topic:defias-brotherhood","zone:westfall","subzone:moonbrook","subzone:gold-coast-quarry","subzone:jangolode-mine","subzone:defias-hideout"},m={start="Gryan Stoutmantle",level="18",faction="Alliance",id=142},src={"The Defias Brotherhood (5)"}}
E["quest:144"] = {t="quest",n="Messenger to Westfall",z="westfall",s="Messenger to Westfall is a diplomatic errand that carries Gryan Stoutmantle's sober reply from Sentinel Hill back to Magistrate Solomon in Lakeshire. Solomon, beleaguered by local threats in Redridge, sought military reinforcement from the People's Militia, only to learn that Westfall is equally forsaken by the crown.",h="Messenger to Westfall is a diplomatic errand that carries Gryan Stoutmantle's sober reply from Sentinel Hill...",sec={{t="A Plea Across Shifting Frontiers",b="Magistrate Solomon of Lakeshire found himself facing mounting crises in the Redridge Mountains without the backing of Stormwind's royal garrison. Looking across the southern regions of the kingdom for allies, he reached out to Gryan Stoutmantle, commander of the People's Militia in Westfall. Solomon hoped the organized volunteer force securing Sentinel Hill might spare troops to bolster Lakeshire's defenses, unaware of the grim realities gripping the western plains.",sp=0},{t="A Bitter Refusal",b="Gryan Stoutmantle's response is an unambiguous, heavy-hearted refusal. Westfall is consumed by its own desperate war against the Defias Brotherhood and marauding gnolls, a struggle made necessary only because the House of Nobles and the crown have abandoned their breadbasket. Stoutmantle makes clear that the People's Militia exists out of sheer survival; they are losing good men daily and cannot spare a single fighter to rescue Redridge.",sp=0},{t="The Kingdom's Fracturing Realm",b="Returning Stoutmantle's reply to Lakeshire shatters Solomon's illusions. The Magistrate realizes that the kingdom's frontier territories share the same abandonment, with local magistrates and citizen militias left to fend for themselves while the Stormwind Army remains inexplicably withheld. This disappointment drives Solomon to look south, setting his sights on Darkshire in Duskwood for aid.",sp=1}},faq={{q="Why did Magistrate Solomon ask Westfall for help?",a="Magistrate Solomon faces mounting threats in Lakeshire without support from Stormwind's army. Knowing that Gryan Stoutmantle organized the People's Militia to defend Westfall, Solomon hoped the frontier force had spare strength to offer military aid to Redridge.",al={"why ask westfall","solomon letter to stoutmantle","why westfall militia"}},{q="Why does Gryan Stoutmantle refuse to send aid?",a="The People's Militia is already stretched past its breaking point fighting the Defias Brotherhood and defending Westfall's farms. Stoutmantle explains that if Stormwind had not deserted Westfall, the Militia would not even need to exist, and they have no soldiers to spare.",al={"why stoutmantle says no","militia refuse lakeshire","stoutmantle response"}},{q="Where is the Stormwind Army during these crises?",a="The royal army is concentrated around Stormwind City and withheld from the rural territories by the ruling council. Both Solomon and Stoutmantle express bewilderment and resentment that the capital leaves its outer provinces undefended.",al={"why stormwind not helping","where is the army","stormwind desertion"}},{q="What happens after returning Stoutmantle's letter to Solomon?",a="Realizing Westfall cannot help, Magistrate Solomon turns his attention to Duskwood, sending the courier on to Darkshire in the hope that Mayor Ello Ebonlocke's Night Watch might send aid instead.",al={"next quest after messenger to westfall","what does solomon do next"},sp=1},{q="What is the People's Militia?",a="The People's Militia is a volunteer army organized by Gryan Stoutmantle and based at Sentinel Hill. Composed of local farmers, veterans, and residents, they defend Westfall from outlaws and gnolls in the total absence of crown troops.",al={"who are the peoples militia","westfall militia"}},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a veteran soldier who took command of the defense of Westfall. Operating from the tower at Sentinel Hill, he rallies volunteers and coordinates the war against the Defias Brotherhood.",al={"gryan stoutmantle lore","who is stoutmantle"}}},ang={["faction:Alliance"]="This correspondence exposes the deep fracture between the rulers in Stormwind Keep and the outlying provinces, revealing that Westfall and Redridge are left entirely to their own devices.",["race:Human"]="For human travelers, delivering this message highlights the tragic isolation of provincial towns, where commoners and veterans bleed to hold territory that Stormwind's nobles refuse to protect."},kw={"gryan stoutmantle","lakeshire","magistrate solomon","messenger to westfall","peoples militia","redridge","sentinel hill","westfall"},rel={"npc:gryan-stoutmantle","npc:magistrate-solomon","quest:143","quest:145","quest:12","zone:westfall","subzone:lakeshire","topic:stormwind-army"},m={start="Gryan Stoutmantle",["end"]="Magistrate Solomon",level="14",faction="Alliance",id=144},src={"Messenger to Westfall (2)"}}
E["quest:151"] = {t="quest",n="Poor Old Blanchy",z="westfall",s="Poor Old Blanchy is a task given by Verna Furlbrow along the main road in Westfall. After their wagon breaks down during an attempted escape, the Furlbrows find their elderly mare exhausted and starving. Adventurers are asked to scavenge scattered sacks of oats from nearby abandoned farmsteads to nourish the tired beast.",h="Poor Old Blanchy is a task given by Verna Furlbrow along the main road in Westfall.",sec={{t="A Stranded Household",b="Traveling along the dusty highway of Westfall, travelers encounter Verna and Westley Furlbrow stranded by the roadside. Like many working families in the region, the Furlbrows have been displaced by rampant banditry and rogue mechanical harvest golems. Attempting to haul their worldly possessions to safety, their wagon suffered a catastrophic breakdown, leaving them marooned in open country.",sp=0},{t="Comfort for a Faithful Mare",b="At the center of their immediate plight is Old Blanchy, a venerable working mare who has served the family across long seasons of plowing and hauling. Exhausted from pulling the overloaded cart and starved by the unexpected delay, the gentle horse is fading fast. Verna begs passersby to slip onto nearby compromised farmsteads to scavenge surviving sacks of grain, braving hostile threshers and gnoll scavengers just to give the faithful animal a decent meal.",sp=0}},faq={{q="Who is Old Blanchy?",a="Old Blanchy is the beloved, aging workhorse of the Furlbrow family. Having pulled their plows and carts across Westfall for years, she is now exhausted and stranded on the roadside after their wagon axle broke.",al={"who is blanchy","what is old blanchy","blanchy lore"}},{q="Why is the Furlbrow wagon broken down?",a="The Furlbrows were attempting to flee their farm with all their belongings when their wagon gave out under the strain. They are left stranded along the highway, exposed to bandits and prowling beasts.",al={"why are they stuck","furlbrow wagon","broken wagon road"}},{q="Where do the oats come from?",a="Sacks of oats remain strewn across the fields and outbuildings of Westfall's overrun farmsteads, left behind when homesteaders fled rogue harvest machines and bandits.",al={"where are oats","find oats","sacks of oats"}},{q="What threats guard the grain in the fields?",a="The agricultural fields southwest of the road are plagued by rogue mechanical harvest watchers and roving bands of Riverpaw gnolls who scavenge the deserted barns.",al={"what attacks at farms","farm dangers","harvest golems oats"}},{q="Why hasn't the family moved Old Blanchy to safety?",a="Old Blanchy is completely spent and starving, unable to pull or travel far without sustenance, while the Furlbrows refuse to abandon both their loyal mare and their worldly goods.",al={"why stay with wagon","can horse walk","why not go sentinel hill"}},{q="Does Stormwind send aid to farmers like the Furlbrows?",a="Stormwind's royal court provides almost no protection or assistance to Westfall's homesteaders. Rural folk are largely left to fend for themselves or rely on the struggling People's Militia.",al={"stormwind help westfall","where are guards","alliance aid westfall"}}},ang={["faction:Alliance"]="The stranded Furlbrows demonstrate the desperate neglect suffered by rural human subjects while the capital remains paralyzed by political stagnation.",["class:Hunter"]="Tending to a spent draft animal underscores the bond between working folk and the beasts that faithfully bear their burdens."},kw={"harvest golem","horse","oats","old blanchy","poor old blanchy","verna furlbrow","wagon","westfall"},rel={"npc:verna-furlbrow","zone:westfall","topic:gnoll"},m={start="Verna Furlbrow",level="14",faction="Alliance",id=151},src={"Poor Old Blanchy"}}
E["quest:152"] = {t="quest",n="The Coast Isn't Clear",z="westfall",s="Along the jagged western edge of Westfall, shipwrecks litter the shoals while murloc tribes overrun the beaches. The ghostly Captain Grayson at the Westfall Lighthouse recruits capable adventurers to clear out these aquatic raiders so that shipwrecked mariners stand a chance of surviving their landfall.",h="Along the jagged western edge of Westfall, shipwrecks litter the shoals while murloc tribes overrun the...",sec={{t="A Graveyard of Ships",b="The Great Sea is notoriously treacherous along Westfall's western boundary. Reefs, sudden squalls, and jagged rocks have smashed countless vessels into flotsam over the years. Under normal circumstances, survivors might cling to wreckage and crawl onto the sand to await rescue. Unfortunately for any shipwrecked sailor, the shoreline has fallen entirely under the control of aggressive murloc tribes that show no mercy to washed-up castaways.",sp=0},{t="The Ghostly Lookout",b="Perched on a lonely outcropping southwest of the mainland stands the Westfall Lighthouse, tended by the spirit of Captain Grayson. Though death has bound him to this post, Grayson remains duty-bound to the safety of passing ships and wayward sailors. Recognizing that the murloc tribes—ranging from simple Coastrunners in the north to deadly Tidehunters, Warriors, and Oracles in the south—render the beaches lethal, he calls upon travelers to mount a systematic purge of the coastline.",sp=0}},faq={{q="Who is Captain Grayson?",a="Captain Grayson is a spectral sea captain who haunts the Westfall Lighthouse. Despite his undead state, he feels a persistent duty toward the sailors who navigate the treacherous waters off the coast, seeking to safeguard the shorelines for any who might survive a shipwreck.",al={"captain grayson","ghost in the lighthouse","lighthouse keeper westfall"}},{q="Why does Grayson want the murlocs cleared from the coast?",a="The waters off Westfall are littered with sunken ships, and surviving sailors frequently wash ashore. With aggressive murloc tribes swarming the beaches from north to south, any shipwrecked sailor who makes it to land is quickly attacked and killed unless the shoreline is kept clear.",al={"why kill murlocs westfall","coast isn't clear reason","why clear the coast"}},{q="Where are these different murlocs located?",a="Murloc Coastrunners generally inhabit the northern stretches of the Westfall coast. The more formidable Murloc Warriors, Oracles, and Tidehunters are found concentrated in settlements and camps along the southern beaches.",al={"murloc locations westfall","where are coastrunners","where are tidehunters"}},{q="Is Captain Grayson hostile to the Alliance or Horde?",a="Captain Grayson is a neutral figure. Bound by his seafaring responsibilities rather than political allegiance, he will offer his requests and rewards to any capable adventurer willing to help make the coast safer.",al={"is grayson friendly","grayson faction","can horde do this quest"}},{q="Does this quest require relighting the lighthouse first?",a="No. Captain Grayson will task you with culling the coast regardless of whether you have assisted him with relighting the Westfall Lighthouse.",al={"do i need keeper of the flame first","prerequisite for coast isnt clear"}},{q="Are the murlocs working for the Defias Brotherhood?",a="No. The murlocs act independently out of territorial aggression. While the Defias Brotherhood operates nearby in the Moonbrook region and the southern coves, the coastal murloc tribes attack anyone who intrudes on their shoreline hunting grounds.",al={"are defias allied with murlocs","defias murloc connection"}}},ang={["faction:Alliance"]="With the Stormwind army absent from Westfall, the People's Militia struggles just to protect inland farms, leaving coastal defense entirely to solitary allies like Captain Grayson.",["race:Human"]="Human merchant vessels and fishermen have long navigated the waters off Westfall; seeing the shore turned into a murloc-infested death trap is a bitter reminder of the kingdom's fallen frontiers."},kw={"captain grayson","coastrunner","great sea","murloc","oracle","shipwrecks","tidehunter","westfall lighthouse"},rel={"npc:captain-grayson","subzone:westfall-lighthouse","quest:103","quest:104","topic:murloc","zone:westfall"},m={start="Captain Grayson",["end"]="Captain Grayson",level="19",faction="neutral",id=152},src={"The Coast Isn't Clear (Classic)"}}
E["quest:153"] = {t="quest",n="Red Leather Bandanas",z="westfall",s="Red Leather Bandanas is a bounty task issued by Scout Galiaan at Sentinel Hill in Westfall. As the Peoples Militia struggles to track the Defias Brotherhood across the plains, Galiaan offers a reward to anyone willing to thin their numbers and bring back the distinctive red cloth masks worn by the outlaws.",h="Red Leather Bandanas is a bounty task issued by Scout Galiaan at Sentinel Hill in Westfall.",sec={{t="A Mark of Allegiance",b="Across Westfall, the red bandana has become the unmistakable calling card of the Defias Brotherhood. While the gang employs common cutpurses, looters, and traitors from all walks of life, they bind their ranks together under this crimson standard. For Scout Galiaan and the beleaguered People's Militia at Sentinel Hill, collecting these trophies serves two purposes: confirming the elimination of bandits and gathering intelligence on their shifting fronts across the countryside.",sp=0},{t="The Militia's Scouting Efforts",b="With Stormwind denying Westfall proper military reinforcement, the People's Militia relies heavily on seasoned observers like Scout Galiaan to chart Defias activities. Galiaan spends his days monitoring outlaw patrols from the safety of Sentinel Hill, relying on passing adventurers and militia volunteers to do the bloody work of cutting down the highwaymen who have driven honest farmers from their soil.",sp=0}},faq={{q="Why do the Defias wear red leather bandanas?",a="The red leather bandana serves as the unified uniform and symbol of allegiance for the Defias Brotherhood. It disguises the identities of former laborers, thieves, and outlaws while striking terror into the remaining farmers of Westfall.",al={"defias red mask meaning","why red masks","defias bandana lore"}},{q="Who is Scout Galiaan?",a="Scout Galiaan is a member of the People's Militia stationed at Sentinel Hill. He monitors the movements and shifting fronts of the Defias Brotherhood across Westfall, coordinating bounty tasks for adventurers to curb outlaw activity.",al={"scout galiaan","who gives red leather bandanas","sentinel hill scout"}},{q="Why does the Militia need adventurers to collect these bandanas?",a="The People's Militia is stretched desperately thin, operating without royal soldiers or funding from Stormwind. By offering bounties for proof of slain bandits, scouts like Galiaan can chip away at the Defias forces without leaving the defense of Sentinel Hill undermanned.",al={"why collect bandanas","why militia bounty"}},{q="Where are the bandits carrying these bandanas found?",a="Defias outlaws roam virtually every corner of Westfall, occupying abandoned farmsteads, prowling the crossroads, and camping along the Gold Coast and around the Moonbrook hills.",al={"where find defias bandanas","defias locations westfall"}},{q="What happens to the bandanas after you turn them in?",a="Scout Galiaan uses them as proof of fallen outlaws to track their shifting fronts and gauge how severely the militia's campaigns are affecting the Brotherhood's numbers in the region.",al={"what does galiaan do with bandanas"}},{q="Is the Stormwind Army involved in this bounty?",a="No. The Stormwind military has largely abandoned Westfall to focus on other internal troubles, leaving local defense entirely in the hands of Gryan Stoutmantle and the volunteer People's Militia.",al={"stormwind guard westfall","does stormwind help sentinel hill"}}},ang={["faction:Alliance"]="Taking bounties for the People's Militia directly supports Westfall's local defense when Stormwind's royal leadership fails to send aid.",["class:Rogue"]="The crimson masks worn by Defias highwaymen are a grim reminder of how skilled rogues and cutpurses have organized into an army on Stormwind's doorstep."},kw={"bandanas","defias brotherhood","peoples militia","red leather bandanas","scout galiaan","sentinel hill","westfall"},rel={"subzone:sentinel-hill","zone:westfall"},m={start="Scout Galiaan",level="15",faction="Alliance",id=153},src={"Red Leather Bandanas"}}
E["quest:155"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="This critical stage of the investigation sees the People's Militia make a breakthrough with the help of a turncoat rogue. In exchange for protection, the Defias Traitor agrees to guide Alliance champions directly to the Brotherhood's hidden base of operations. The journey cuts straight through the occupied ghost town of Moonbrook to uncover Edwin VanCleef's inner sanctum.",h="This critical stage of the investigation sees the People's Militia make a breakthrough with the help of a...",sec={{t="A Turncoat's Bargain",b="Gryan Stoutmantle's campaign against the Defias Brotherhood hits a turning point once a captured brigand agrees to talk. Facing execution or assassination by his former brothers, the Defias Traitor cuts a deal with the People's Militia: escort him safely through hostile territory, and he will expose the location where Edwin VanCleef and his ringleaders are hiding. Knowing the thieves' network will ruthlessly silence anyone who speaks out, the turncoat requires armed protection every step of the road.",sp=0},{t="The Road Through Moonbrook",b="The path to the hideout leads straight southwest from Sentinel Hill down into Moonbrook, a township completely overrun by the Brotherhood. The traitor guides his protectors right past the abandoned town square and fountain, drawing the fury of every brigand, looter, and highwayman patrolling the ruins. The turncoat leads the way directly to the entrance of the sprawling Deadmines beneath Moonbrook, confirming the militia's worst fears: VanCleef has fortified an underground stronghold right under Westfall's nose.",sp=1}},faq={{q="Who is the Defias Traitor?",a="He is a former member of the Defias Brotherhood who turned informant for Gryan Stoutmantle and the People's Militia. Fearing death at the hands of his former comrades, he traded the secret location of Edwin VanCleef's underground redoubt in exchange for an escort to safety.",al={"who is the traitor","defias traitor identity","defias rat"}},{q="Where does the traitor lead you?",a="He leads you from Sentinel Hill down the road into Moonbrook, marching straight through the ruined town square past the fountain to the entrance of the Deadmines tunnels beneath the town.",al={"where is the defias hideout","traitor path","where does he go"}},{q="Why does Gryan Stoutmantle need this information?",a="Although the People's Militia has battled highwaymen across Westfall, they did not know where Edwin VanCleef was directing operations. Discovering the entrance to his underground lair gives the militia a clear target to strike at the heart of the rebellion.",al={"why do we escort the traitor","stoutmantle purpose","why find the hideout"}},{q="Why is Moonbrook crawling with Defias?",a="Moonbrook was once a thriving agricultural center, but when the Kingdom of Stormwind fell into neglect and bandits moved in, the town was abandoned by its residents. The Defias Brotherhood claimed the empty buildings as an above-ground perimeter guarding the entrance to the Deadmines.",al={"why are there defias in moonbrook","moonbrook takeover","who owns moonbrook"}},{q="What happens after you discover the hideout?",a="Once the traitor reveals the entrance to the Deadmines, you report back to Gryan Stoutmantle at Sentinel Hill. Armed with proof of VanCleef's location, the militia prepares a direct assault on the underground lair.",al={"what comes next","after defias escort","quest progression"},sp=1},{q="Why does the Brotherhood want the traitor dead?",a="The Defias rely on secrecy, operating from hidden tunnels while orchestrating operations throughout Stormwind's territories. A turncoat revealing the front door of their central operation threatens to dismantle their entire conspiracy.",al={"why kill traitor","defias attacking traitor"}}},ang={["faction:Alliance"]="Uncovering the hideout is a major military breakthrough for the embattled People's Militia, offering the first real chance to strike a decisive blow against Westfall's criminal insurgency.",["class:Rogue"]="Walking alongside a former Defias rogue offers a harsh look at the price of betrayal in the criminal underworld, where broken vows are answered with daggers.",["race:Human"]="For humans of Stormwind, seeing Moonbrook fallen to lawlessness and occupied by former Stonemasons underscores just how deeply the kingdom has fractured since the Third War."},kw={"deadmines","defias traitor","edwin vancleef","escort","gryan stoutmantle","moonbrook","peoples militia","sentinel hill","westfall"},rel={"npc:the-defias-traitor","subzone:moonbrook","subzone:defias-hideout","npc:gryan-stoutmantle","subzone:sentinel-hill","topic:defias-brotherhood","zone:westfall","quest:65"},m={start="The Defias Traitor",["end"]="Gryan Stoutmantle",level="18",faction="Alliance",id=155},src={"The Defias Brotherhood (6)"}}
E["quest:1651"] = {t="quest",n="The Tome of Valor",z="westfall",s="A pivotal trial for developing paladins, this task demands the defense of Daphne Stilwell's homestead against a coordinated Defias raid. Outnumbered in the open fields of Westfall, the paladin must hold the line to embody the core tenet of valor.",h="A pivotal trial for developing paladins, this task demands the defense of Daphne Stilwell's homestead against...",sec={{t="A Stand in the Dust",b="While pursuing the virtues recorded in the Tome of Valor, a paladin is directed to the embattled homestead of Daphne Stilwell in Westfall. The farm sits squarely in territory contested by the Defias Brotherhood, who have made repeated attempts to overrun the property and eliminate Daphne. Knowing a retaliatory strike is imminent after earlier skirmishes, the defender must make a resolute stand beside her house rather than retreat to safer ground.",sp=0},{t="The Trial of Valor",b="Armed with only her personal firearm and what blessings the Holy Light can provide, Daphne and the paladin face wave after wave of Defias raiders. Unlike solitary combat, this trial tests a guardian's ability to protect the vulnerable under crushing pressure. Weathering the onslaught proves that true valor is not merely the pursuit of personal glory, but the willingness to stand between innocent civilians and ruthless violence.",sp=0}},faq={{q="Who is Daphne Stilwell?",a="Daphne Stilwell is a resilient human homesteader living in the grasslands of Westfall. Despite regular incursions by the Defias Brotherhood, she refuses to abandon her land and actively fights back against bandit raids.",al={"daphne stilwell","who is daphne","stilwell westfall"}},{q="Why are the Defias attacking this specific farm?",a="The Defias Brotherhood has largely seized control of Westfall's countryside, driving off or subjugating local farmers. Daphne's defiant refusal to bow to their extortion or abandon her property makes her farm an active target for their raiders.",al={"why defias attack","defias raid daphne","why attack stilwell"}},{q="What is the Tome of Valor?",a="The Tome of Valor is a sacred instructional text used by the Church of the Holy Light to guide young paladins. Knights-in-training undertake physical and spiritual trials across the kingdom to embody the virtues described within its pages.",al={"what is tome of valor","tome of valor quest","paladin valor tome"}},{q="What happens if Daphne falls during the battle?",a="If Daphne Stilwell falls in battle, the trial ends in failure. The core test of valor requires safeguarding her life alongside your own against the bandit assault.",al={"can daphne die","daphne stilwell dies"}},{q="Where does this attack take place?",a="The encounter takes place outside Daphne Stilwell's farmhouse, a small farm in the Dagger Hills overlooking the Longshore in southern Westfall.",al={"daphne stilwell location","where is the farm"}},{q="What comes after defending the farm?",a="After proving your courage and driving off the Defias raiders, Daphne acknowledges your devotion, directing you toward the next phase of your paladin trials.",al={"next quest tome of valor","after defending daphne"}}},ang={["class:Paladin"]="This battle tests your role as an unyielding protector. Holding the line at Daphne's side demonstrates the core virtue of valor, showing that holy warriors exist primarily to shield the innocent from harm.",["faction:Alliance"]="With Stormwind's garrison spread thin and unable to safeguard rural homesteads, the task of defending Westfall's loyal citizens falls squarely on individual heroes."},kw={"daphne stilwell","defias brotherhood","defias raiders","paladin trial","tome of valor","westfall"},rel={"npc:daphne-stilwell","zone:westfall","topic:light"},m={start="Daphne Stilwell",level="25",faction="Alliance",id=1651},src={"The Tome of Valor (4)"}}
E["quest:184"] = {t="quest",n="Furlbrow's Deed",z="westfall",s="Furlbrow's Deed is a stolen land grant carried by Defias thieves in Elwynn Forest. Returning the document to the displaced Farmer Furlbrow near the Westfall border offers the fleeing couple their only hope of one day reclaiming their stolen homestead.",h="Furlbrow's Deed is a stolen land grant carried by Defias thieves in Elwynn Forest.",sec={{t="A Clue on Stolen Paper",b="While clashing with Defias bandits across Elwynn Forest, travelers often recover a crumpled land deed signed by Theodore and Verna Furlbrow. On the back of the parchment, crude handwriting reveals the bandits' scheme: having strong-armed the elderly farmer off his property, they smuggled the document across the river into Elwynn to use as a template for forging deeds to other seized land. The scrawl also notes that the Furlbrows were seen stranded by the road just over the border, immobilized by a broken wagon.",sp=0},{t="The Plight of Westfall's Farmers",b="The Furlbrows' loss is emblematic of the tragedy engulfing Westfall. With the Stormwind army absent and the realm's resources strained, the Defias Brotherhood has driven dozens of families from their ancestral soil, using force and legal manipulation to consolidate their hold on the kingdom's breadbasket. Though Theodore and Verna are abandoning their farm for their own safety, retaining their lawful deed preserves their single claim against the rogue uprising should order ever be restored to the province.",sp=0}},faq={{q="Where do I find this deed?",a="The deed drops from various members of the Defias Brotherhood lurking around southern and western Elwynn Forest, such as those near the Jerod's Landing area or hiding in local camps.",al={"deed drop","how to get furlbrows deed","where does the deed drop"}},{q="Where is Farmer Furlbrow?",a="Farmer Furlbrow and his wife Verna are stranded beside a broken wagon along the main road just inside Westfall, shortly after crossing the bridge west from Elwynn Forest.",al={"furlbrow location","where to turn in furlbrows deed","where is the farmer"}},{q="Why did the Defias want the deed in the first place?",a="A note on the back reveals the bandits intended to use Furlbrow's legitimate deed as a template to forge claims on other properties across the region, cementing their control over stolen farms through counterfeit paperwork.",al={"why did bandits steal the deed","why do defias want deeds"}},{q="Are the Furlbrows returning to their farm?",a="Not anytime soon. The couple is actively fleeing the region due to lawlessness and bandit attacks. However, having their deed in hand ensures they can legally reclaim their land if Westfall is ever pacified.",al={"are furlbrows going home","what happens to the furlbrow farm"}},{q="Why isn't Stormwind protecting these farms?",a="Stormwind is paralyzed by the sudden disappearance of King Varian Wrynn and domestic political tension. With royal resources focused on the capital, outer territories like Westfall have been left to defend themselves against the surging Defias Brotherhood.",al={"why no guards in westfall","why is stormwind ignoring westfall"}},{q="What is the connection between Elwynn and Westfall in this quest?",a="The quest serves as a breadcrumb leading adventurers from Elwynn Forest across the river into Westfall, demonstrating how far the Defias network reaches into the kingdom's core territories.",al={"why was deed in elwynn","connection between zones"}}},ang={["faction:Alliance"]="The plight of the Furlbrows highlights the failure of the Stormwind crown to protect its taxpaying citizens outside the capital's fortified walls.",["class:Paladin"]="Restoring stolen deeds to destitute refugees embodies the holy vows to defend the defenseless and bring justice to lawless borderlands."},kw={"defias","elwynn","furlbrow","theodore furlbrow","verna furlbrow","westfall","westfall deed"},rel={"npc:farmer-furlbrow","zone:westfall","topic:defias-brotherhood","zone:elwynn","quest:65"},m={start=":Westfall Deed",["end"]="Farmer Furlbrow",level="9",faction="Alliance",id=184},src={"Furlbrow's Deed (Classic)"}}
E["quest:22"] = {t="quest",n="Goretusk Liver Pie",z="westfall",s="Goretusk Liver Pie is a culinary errand undertaken for Salma Saldean at the Saldean Farm in Westfall. With the breadbasket of the kingdom ravaged by drought and bandits, local homesteaders rely on hunting the aggressive local boars to put a hearty meal on the table. Assisting Salma provides a rare taste of comfort and home-cooked hospitality in an otherwise bleak frontier.",h="Goretusk Liver Pie is a culinary errand undertaken for Salma Saldean at the Saldean Farm in Westfall.",sec={{t="Frontier Hospitality",b="Westfall was once the fertile breadbasket of Stormwind, but recent years have brought hard times. With neglected infrastructure, roving outlaws, and overgrown fields, everyday life has become a grind for the few remaining settlers. At the Saldean Farm, Salma Saldean works tirelessly to maintain a sense of hearth and home despite the encroaching dangers. Preparing a traditional meat pie represents one of the few modest luxuries available to homesteaders trying to preserve their way of life.",sp=0},{t="Westfall's Feral Beasts",b="The plains of Westfall teem with goretusks, aggressive wild boars known for their tough hides and vicious tusks. While dangerous to lone farmhands, they are also a vital source of meat for families cut off from regular trade. Salma's recipe calls for careful preparation—crushed rosemary, minced garlic, chopped dill, and simmering gravy—to turn the pungent organs of these hardy beasts into a rich, savory feast.",sp=0}},faq={{q="Who is Salma Saldean?",a="Salma Saldean is a resilient homesteader who lives with her husband, Farmer Saldean, at their farm in central Westfall. Known for her home-cooked meals, she does her best to keep spirits high despite the dangers posed by bandits and wild beasts.",al={"salma saldean","who is salma","saldean wife"}},{q="Why does Salma want goretusk livers?",a="Salma is preparing her famous savory meat pie to share with her husband. The pie crust is already baked and the seasonings are prepped, needing only the livers from local goretusks to finish simmering the filling.",al={"why goretusk liver","what is the pie made of","liver pie purpose"}},{q="Where are goretusks typically found in Westfall?",a="Goretusks roam extensively across the golden plains and fallow farm plots throughout Westfall, rooting through abandoned fields and wandering along the dirt roads.",al={"goretusk locations","where to find boars","goretusk liver hunt"}},{q="Are goretusks dangerous to the local farmers?",a="Yes. Goretusks are aggressive, territorial wild boars equipped with sharp tusks. They pose a significant threat to livestock and unprotected travelers across the plains.",al={"are goretusks hostile","boar danger westfall"}},{q="Why is food so scarce in Westfall right now?",a="A combination of crippling droughts, lack of royal support from Stormwind, and raids by organized bandits has forced many farmers off their land, turning the former breadbasket of the kingdom into a struggling, impoverished frontier.",al={"westfall famine","why no food westfall","westfall hard times"}},{q="Does completing this task help the Saldean farm survive?",a="While it does not solve the broader crises facing Westfall, gathering fresh meat directly sustains the Saldean family and provides travelers with hearty rations for the road ahead.",al={"does the pie matter","saldean food supply"}}},ang={["profession:Cooking"]="Salma's dish illustrates traditional rural human cooking, using garden aromatics like garlic, rosemary, and dill weed to elevate wild game offal into a staple meal.",["faction:Alliance"]="Helping rural homesteaders like the Saldeans directly supports the loyal human families struggling to maintain the kingdom's frontier in the absence of Stormwind's army."},kw={"boar","cooking","goretusk","liver pie","saldean farm","salma saldean","westfall"},rel={"npc:salma-saldean","npc:farmer-saldean","zone:westfall"},m={start="Salma Saldean",level="12",faction="Alliance",id=22},src={"Goretusk Liver Pie (quest)"}}
E["quest:36"] = {t="quest",n="Westfall Stew",z="westfall",s="Westfall Stew begins as a neighborly exchange between fleeing homesteaders and the few farmers still holding ground. With her family forced to abandon their land due to rampant banditry, Verna Furlbrow passes her cherished local recipe to Salma Saldean before departing the region.",h="Westfall Stew begins as a neighborly exchange between fleeing homesteaders and the few farmers still holding...",sec={{t="A Recipe Passed On",b="The Furlbrows' departure highlights the worsening collapse across Westfall's countryside. Driven off their family acreage by Defias thieves and mechanical harvest reapers gone wild, Verna and Farmer Furlbrow are packing their wagon to seek refuge behind Stormwind's walls. Reluctant to let her home-cooked tradition vanish along with her farm, Verna entrusts her signature recipe for Westfall Stew to her neighbor, Salma Saldean.",sp=0},{t="Homestead Solidarity",b="Salma Saldean still clings to her homestead just down the road, stubbornly holding out alongside her husband Farmer Saldean. Receiving Verna's recipe is a bittersweet moment: while it marks the loss of another neighbor to the growing unrest, it also preserves a staple of local farm life. With the instructions in hand, Salma sets out to gather the necessary rustic ingredients to feed those still struggling to survive on the frontier.",sp=0}},faq={{q="Why are the Furlbrows leaving their farm?",a="Thieves and bandits have overrun their fields, turning their land far too dangerous to work. Verna and Farmer Furlbrow are repairing their wagon to flee to the safety of Stormwind City.",al={"why furlough leaving","furlbrows leaving westfall","why verna packing"}},{q="Who is Salma Saldean?",a="Salma Saldean is a Westfall homesteader living on Saldean's Farm, just past the fork in the road from the Furlbrow homestead. She and her family continue to work their land despite the surrounding lawlessness.",al={"who is salma","salma saldean lore"}},{q="What is Westfall Stew?",a="It is a traditional, hearty regional dish concocted from native ingredients found across the Westfall plains, long shared among local farming households.",al={"what is westfall stew","westfall stew recipe"}},{q="Where are the Furlbrows planning to go?",a="They are heading north toward the safety of Stormwind City, where Verna's friends believe she will fit right in.",al={"where furlbrows going","furlbrow destination"}},{q="Where is Saldean's Farm located?",a="Saldean's Farm lies just beyond the fork in the main road, situated south of the Furlbrow pumpkin patch in Westfall.",al={"saldean farm location","where is salma saldean"}},{q="Does this quest reward the actual cooking recipe?",a="Delivering the written instructions to Salma Saldean is only the first step. To actually prepare the dish, Salma will ask for help sourcing the rustic ingredients needed for the pot.",al={"recipe reward","do i get westfall stew recipe"}}},ang={["profession:Cooking"]="The dish represents the quintessential frontier cooking of human homesteaders, turning scavenged prairie game and hardy root vegetables into sustenance.",["race:Human"]="The delivery reflects the crumbling frontier of the kingdom of Stormwind, where ordinary rural citizens are steadily driven from their ancestral farms into urban exile."},kw={"cooking","farmer furlbrow","recipe","saldean's farm","salma saldean","stew","verna furlbrow","westfall"},rel={"npc:verna-furlbrow","npc:salma-saldean","subzone:saldean-s-farm","npc:farmer-furlbrow","zone:westfall","topic:stormwind-kingdom"},m={start="Verna Furlbrow",["end"]="Salma Saldean",level="10",faction="Alliance",id=36},src={"Westfall Stew (Classic)"}}
E["quest:38"] = {t="quest",n="Westfall Stew",z="westfall",s="Westfall Stew is a hearty local recipe prepared by Salma Saldean on the Saldean Farm. Cobbled together from the rugged wildlife and foraging grounds of Westfall, the dish represents the resilient survival spirit of the region's homesteaders.",h="Westfall Stew is a hearty local recipe prepared by Salma Saldean on the Saldean Farm.",sec={{t="A Homesteader's Necessity",b="Westfall is a harsh frontier beset by bandits, famine, and rampaging beasts, leaving frontier settlers with little access to the lavish larders of Stormwind. Families like the Saldeans have learned to make do with what the land provides. Salma Saldean's stew transforms what many city folk would consider pests or inedible scraps into a sustaining staple capable of keeping working farmhands on their feet.",sp=0},{t="The Ingredients of Survival",b="The recipe calls for a peculiar blend of frontier forage: local okra to thicken the bubbling broth, stringy scavenger meat cut from circling vultures, and snouts from the wild goretusks that root across the plains. Most notorious of all are fresh murloc eyes gathered from coastal raiders. While the thought of eating river beasts and carrion birds turns delicate stomachs in Elwynn, Westfall cooks swear the strange combination makes for a rich, fortifying meal.",sp=0}},faq={{q="Why does the recipe use murloc eyes?",a="Westfall farmers face constant resource shortages and frequent raids by aggressive murlocs along the coast and riverbanks. Salma Saldean uses fresh murloc eyes to add unique moisture and flavor to the broth, turning an invasive threat into a practical source of food.",al={"murloc eyes in food","why eat murlocs","murloc stew"}},{q="Who is Salma Saldean?",a="Salma Saldean is an Alliance homesteader living with her husband, Farmer Saldean, at the Saldean Farm in northern Westfall. Known for her hospitality and culinary resourcefulness, she feeds travelers and farmhands despite the encroaching banditry and chaos in the region.",al={"salma","salma saldean lore","who makes westfall stew"}},{q="Where does the okra come from?",a="Okra is one of the few hardy vegetable crops still harvested on Westfall's struggling farms. Its pods release natural juices when boiled, serving as an essential thickening agent for frontier broths.",al={"where to find okra","saldean okra","okra origin"}},{q="Is Westfall Stew considered good food?",a="To refined nobles in Stormwind, a broth filled with boiled goretusk snouts and murloc eyes sounds grotesque. To the dirt-poor farmers and weary wanderers of Westfall, it is a warm, filling, and deeply cherished comfort meal.",al={"does westfall stew taste good","is westfall stew gross"}},{q="Why do the Saldeans need adventurers to gather the ingredients?",a="Westfall has become exceedingly dangerous. Wild goretusks, aggressive vultures, and hostile murlocs roam the fields and beaches, making foraging too hazardous for ordinary farmers who must remain behind to defend their homestead.",al={"why gather ingredients","why salma needs help"}},{q="What animal provides the meat for the stew?",a="The stew relies primarily on stringy vulture meat taken from the carrion birds soaring across Westfall, along with the snouts of wild goretusks hunted across the plains.",al={"what meat is in westfall stew","westfall stew meat"}}},ang={["profession:Cooking"]="Salma's dish is a masterclass in rustic frontier cooking, teaching aspiring chefs how to turn rough game, pungent snouts, and unusual shoreline harvests into a fortifying meal.",["race:Human"]="For humans outside the safety of Elwynn's protective walls, dishes like Westfall Stew embody the sheer grit and endurance needed to scratch out a living in the kingdom's forgotten breadbasket.",["faction:Alliance"]="While Stormwind's court enjoys fine wine and polished poultry, frontier Alliance outposts rely on rustic dishes like this to sustain their defense against local threats."},kw={"goretusk snout","murloc eye","okra","saldean farm","salma saldean","vulture meat","westfall","westfall stew"},rel={"quest:36","npc:salma-saldean","zone:westfall","topic:murloc"},m={start="Salma Saldean",level="13",faction="Alliance",id=38},src={"Westfall Stew (Classic 2)"}}
E["quest:3861"] = {t="quest",n="CLUCK!",z="westfall",s="CLUCK! is an unusual, secretive interaction that allows an adventurer to gain the trust of ordinary barnyard poultry. By mimicking chicken calls and providing the proper grain, travelers can receive a prize egg to hatch a feathered companion of their own.",h="CLUCK!",sec={{t="A Strange Communion",b="While most travelers pay little mind to the simple chickens wandering the farmsteads of Azeroth, these birds hold a surprisingly perceptive nature. If an adventurer stoops to mimic their gestures and clucking long enough, the chicken ceases its mindless pecking and regards the mortal with uncanny interest. In that brief moment of connection, the bird scratches letters in the dirt, hinting at its hunger and directing the curious toward the proper farmer who can feed it.",sp=0},{t="The Farmer's Feed",b="Satisfying the bird's cryptic request requires acquiring Special Chicken Feed. In Westfall, the Saldean family keeps such grain on hand for their flock. Presenting this specialized feed and offering enthusiastic encouragement causes the bird to eagerly peck down the meal. In exchange, the chicken produces a warm, freshly laid egg that can be nurtured into a loyal companion.",sp=0}},faq={{q="How does a chicken offer a quest?",a="If you mimic the bird by using chicken or flapping gestures repeatedly in front of it, it will eventually pause and inspect you curiously. At that point, the chicken becomes responsive and communicates its hunger by scratching a name into the dirt.",al={"chicken quest start","how to talk to chicken","cluck quest unlock"}},{q="What does the chicken spell out in the dirt?",a="The chicken scratches out the letters 'S-A-L-D-E-A-N' into the soil before wandering off. This points the traveler toward Farmer Saldean and his wife at the Saldean Farm in central Westfall, who sell the specialized grain the bird craves.",al={"chicken scratch words","what does the chicken write","saldean chicken"}},{q="Where do you get the Special Chicken Feed?",a="In Westfall, Farmer Saldean stocks Special Chicken Feed at the Saldean Farmstead. Across the sea in the Tirisfal Glades, a vendor in the town of Brill also sells the grain.",al={"chicken feed vendor","where to buy chicken feed","saldean feed"}},{q="Can you do this with any chicken in the world?",a="Any standard barnyard chicken found throughout settled lands can respond to the gesture, though they are most commonly encountered around human farmlands such as those in Westfall.",al={"which chickens work","does any chicken work","where to find chicken"}},{q="How do you complete the quest once you have the feed?",a="Find a chicken while carrying the Special Chicken Feed and cheer at it enthusiastically. The chicken will look at you expectantly, accept the feed, and lay an egg underneath itself that you can collect.",al={"how to turn in cluck","feed chicken egg","cluck quest hand in"}},{q="What do you get for finishing the quest?",a="The fed chicken lays a Farm Chicken Egg at its feet. Looting this egg grants a Chicken Egg item, which allows you to summon your own faithful Westfall chicken to follow you on your adventures.",al={"cluck quest reward","chicken egg pet","westfall chicken reward"}}},ang={["faction:Alliance"]="The quest revolves around the Saldean Farmstead in Westfall, making this bizarre feathered ritual a staple tale among young Alliance adventurers exploring the battered rural kingdom.",["profession:Cooking"]="The Special Chicken Feed required by the fowl is entirely edible, though most cooks prefer to save the coarse grain for the birds rather than snack on it themselves."},kw={"chicken","chicken egg","cluck","poultry","saldean","saldean farm","special chicken feed","westfall chicken"},rel={"zone:westfall","subzone:brill","topic:alliance","topic:horde"},m={start="Chicken",faction="Neutral",id=3861},src={"CLUCK!"}}
E["quest:6181"] = {t="quest",n="A Swift Message",z="westfall",s="Quartermaster Lewis at Sentinel Hill needs urgent armor shipments from Stormwind to equip the People's Militia. Because Westfall receives almost no official military aid, he sends you to Thor the gryphon master to carry an urgent requisition note to the capital by air.",h="Quartermaster Lewis at Sentinel Hill needs urgent armor shipments from Stormwind to equip the People's...",sec={{t="A Plea Across the Skies",b="Sentinel Hill stands isolated against a rising tide of Defias outlaws and gnolls, starved of direct military aid from Stormwind. Quartermaster Lewis relies on private contacts in the capital to keep the People's Militia supplied with weapons and armor. With gear running thin, his only lifeline is Osric Strang, an armorer located in Old Town. Getting an urgent requisition to him requires swift travel, leading Lewis to enlist travelers to contact Westfall's gryphon master, Thor.",sp=0},{t="The Flight Network",b="Gryphons provide the Kingdom of Stormwind with an invaluable rapid transit and courier network. Perched at Sentinel Hill, Thor manages the outpost's aerial link back to the capital. Handing Lewis's note to Thor opens the skies between Westfall and the royal city, demonstrating how crucial the gryphon riders are to sustaining frontier garrisons cut off from formal aid.",sp=0}},faq={{q="Why does Quartermaster Lewis need to send a note to Stormwind?",a="Westfall receives little direct military aid from Stormwind's government, leaving the People's Militia critically low on armor. Lewis must reach out to a trusted merchant in the city, Osric Strang, to secure fresh supplies.",al={"why send note","lewis note purpose","why contact stormwind"}},{q="Who is Osric Strang?",a="Osric Strang is an armorer whose shop, Limited Immunity, is located in Old Town within Stormwind. He serves as Lewis's dependable private supplier when official channels fail.",al={"osric strang","who is osric","limited immunity owner"}},{q="Who is Thor?",a="Thor is the gryphon master stationed at Sentinel Hill. He handles the flying mounts that connect Westfall to Stormwind, enabling fast courier transit and travel.",al={"who is thor","westfall flight master","thor gryphon master"}},{q="Why isn't Stormwind sending soldiers and gear to Westfall directly?",a="With King Varian Wrynn missing and resources stretched thin, Stormwind's leadership has largely neglected the outlying farmlands. Frontier outposts like Sentinel Hill must rely on volunteer militias and private arrangements to survive.",al={"why no stormwind help","why stormwind ignores westfall","where is the army"}},{q="Can any adventurer undertake this task?",a="This errand is entrusted specifically to human adventurers who have proved themselves in Westfall, serving as an introduction to using the kingdom's gryphon flight network.",al={"who can take this quest","human only quest","can dwarves do this quest"}},{q="Where does this courier mission lead next?",a="After presenting the note to Thor, he prepares a gryphon flight directly to Stormwind, where you will continue to Dungar Longdrink at the capital's roost and then seek out Osric Strang in Old Town.",al={"next step","what happens after thor","where do i go next"}}},ang={["race:Human"]="For humans of the kingdom, carrying Lewis's note highlights the strained state of Stormwind's provinces and introduces the vital gryphon routes connecting home territories.",["faction:Alliance"]="The errand reveals the deep logistical fracture between the grand capital of Stormwind and its struggling frontier outposts in Westfall."},kw={"armor","flight master","gryphon","old town","osric strang","peoples militia","quartermaster lewis","sentinel hill","stormwind","thor"},rel={"quest:6281","npc:quartermaster-lewis","npc:thor","npc:osric-strang","quest:6261","quest:6285","zone:westfall","subzone:old-town"},m={start="Quartermaster Lewis",["end"]="Thor",level="10",faction="Alliance",id=6181},src={"A Swift Message (Classic)"}}
E["quest:6281"] = {t="quest",n="Continue to Stormwind",z="westfall",s="This errand introduces adventurers in Westfall to the speed and convenience of the Kingdom of Stormwind's gryphon network. Entrusted with an urgent requisition from Sentinel Hill, travelers take flight directly to Old Town to deliver word to the merchant Osric Strang.",h="This errand introduces adventurers in Westfall to the speed and convenience of the Kingdom of Stormwind's...",sec={{t="Taking Wing",b="After Quartermaster Lewis in Sentinel Hill prepares a requisition note, the local gryphon master Thor offers the fastest route out of the contested plains. For a modest fee, travelers mount one of the kingdom's trained gryphons and soar above the dusty farmlands, the river border of Elwynn Forest, and over the high white ramparts of Stormwind City itself.",sp=0},{t="Old Town Supply Lines",b="Upon landing in the capital's trade roosts, the courier heads into Old Town to locate Osric Strang at his shop, Limited Immunity. Osric provides equipment and supplies to the frontier, though his grim reception highlights the growing rift between the beleaguered People's Militia in Westfall and the distracted rulers in Stormwind Keep.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest serves as a practical introduction to the Alliance's gryphon flight paths, teaching adventurers how to quickly travel between distant outposts and the capital city.",al={"why do this quest","quest purpose","continue to stormwind objective"}},{q="Where is Osric Strang located?",a="Osric Strang runs the shop Limited Immunity, located along the winding streets of Old Town inside Stormwind City.",al={"where is osric strang","find osric strang","limited immunity location"}},{q="Why does Sentinel Hill need supplies from Stormwind?",a="The People's Militia at Sentinel Hill is struggling against the Defias Brotherhood and receive little formal military aid from the capital, forcing Quartermaster Lewis to purchase gear directly from civilian merchants.",al={"why need supplies","westfall supply issue","sentinel hill gear"}},{q="Who is Thor?",a="Thor is the Alliance gryphon master stationed at Sentinel Hill, managing the flight routes connecting Westfall to Stormwind City and other friendly hubs.",al={"who is thor","westfall gryphon master","thor westfall"}},{q="What is inside Lewis' Note?",a="It is an urgent requisition from Quartermaster Lewis detailing gear and provisions desperately required to keep the Sentinel Hill garrison equipped.",al={"lewis note","what does the note say","contents of note"}},{q="What happens after delivering the note?",a="After receiving the requisition, Osric directs you to speak with the Stormwind gryphon master, Dungar Longdrink, to arrange the transport of the ordered supplies back to Westfall.",al={"what next","follow up quest","after osric strang"}}},ang={["faction:Alliance"]="The flight network maintained by gryphon masters binds the scattered outposts of the Alliance together, keeping remote garrisons tethered to the capital.",["race:Human"]="Returning to Old Town reveals how disconnected common citizens and isolated frontiersmen feel from the politics of the grand House of Nobles."},kw={"flight path","gryphon","lewis' note","limited immunity","old town","osric strang","sentinel hill","thor"},rel={"quest:6181","quest:6261","quest:6285","npc:thor","npc:osric-strang","npc:quartermaster-lewis","subzone:sentinel-hill","subzone:old-town"},m={start="Thor",["end"]="Osric Strang",level="10",faction="Alliance",id=6281},src={"Continue to Stormwind (Classic)"}}
E["quest:64"] = {t="quest",n="The Forgotten Heirloom",z="westfall",s="Farmer Furlbrow and his wife Verna fled their home when masked brigands overran their pumpkin patch in Westfall. In the frantic rush to escape, Furlbrow left behind a cherished family heirloom inside his farmhouse wardrobe. Recovering the pocket watch represents a rare chance to salvage something personal from the encroaching chaos gripping the region.",h="Farmer Furlbrow and his wife Verna fled their home when masked brigands overran their pumpkin patch in...",sec={{t="A Midnight Eviction",b="Like many homesteaders throughout Westfall, Farmer Furlbrow and his wife Verna were driven from their land through brute force. Roused from their beds by sudden shouts and violence among the pumpkin patches, the couple had only moments to bundle what few belongings they could carry before fleeing their farm. In the panic, Furlbrow was forced to leave behind a pocket watch gifted to him by Verna's father on their wedding day, leaving it behind in the wardrobe of their occupied farmhouse.",sp=0},{t="Hooligans in the Fields",b="The Furlbrow pumpkin farm now teems with Defias thugs, looters, and opportunistic thieves such as Benny Blaanco who pick through the remains of abandoned homes. For ordinary folk, returning to retrieve personal treasures is a death sentence. By securing the watch from the wardrobe amidst the ransacked rooms, adventurers deliver a small measure of dignity to a family that has lost nearly everything else to the rising tide of lawlessness.",sp=0}},faq={{q="Why is the pocket watch so important to Farmer Furlbrow?",a="The pocket watch was a wedding gift from Verna's father. As destitute refugees with their livelihood destroyed, the watch is one of the only remaining sentimental connections to their past life and family heritage.",al={"why watch important","furlbrow watch significance","who gave furlbrow the watch"}},{q="Who drove the Furlbrows away from their farm?",a="Defias brigands and looters overwhelmed the farm during the night. The lawlessness sweeping Westfall has forced numerous farming families to abandon their fields and homes under threat of violence.",al={"who attacked the farm","who took furlbrow farm","what happened to the furlbrows"}},{q="Where is the watch hidden?",a="The watch is stored inside a bedroom wardrobe within the Furlbrow homestead, located at the pumpkin patches west of the Furlbrows' roadside camp in northern Westfall. Squatters and Defias outlaws currently occupy the dwelling.",al={"where is the pocket watch","find watch","wardrobe location"}},{q="Who is Benny Blaanco?",a="Benny Blaanco is an outlaw found lingering inside the Furlbrow farmhouse alongside Defias companions, ransacking the abandoned residence and guarding the stolen territory against reclaimers.",al={"benny blaanco lore","who is the guy in the house"}},{q="Where are the Furlbrows staying now?",a="Having fled their land, Farmer Furlbrow and Verna can be found stranded by the roadside in Westfall, sheltering near their wagon as they try to survive the regional collapse.",al={"where are furlbrows","where is farmer furlbrow"}},{q="Does Stormwind send guards to help recover farms like this?",a="Stormwind's official military presence in Westfall is practically nonexistent due to political indifference and missing leadership in the capital. The People's Militia at Sentinel Hill lacks the manpower to reclaim individual farmsteads, leaving settlers entirely vulnerable.",al={"stormwind help westfall","why no guards at farm"}}},ang={["faction:Alliance"]="The plight of the Furlbrows highlights the severe breakdown of civil order in the kingdom's breadbasket, forcing Alliance travelers to handle matters the crown has neglected.",["race:Human"]="For humans of Stormwind, seeing honest farmers displaced by violent outlaws within a day's march of the capital is a sobering reminder of the kingdom's domestic troubles."},kw={"benny blaanco","defias","furlbrow","pocket watch","pumpkin patch","verna furlbrow","wardrobe","westfall"},rel={"npc:farmer-furlbrow","zone:westfall"},m={start="Farmer Furlbrow",level="12",faction="Alliance",id=64},src={"The Forgotten Heirloom"}}
E["quest:65"] = {t="quest",n="The Defias Brotherhood",z="westfall",s="This errand marks the opening step in unraveling the covert syndicate terrorizing Westfall. Dispatched by Gryan Stoutmantle of Sentinel Hill, travelers are directed eastward into Redridge to consult a shady contact who might know where the thieves hide.",h="This errand marks the opening step in unraveling the covert syndicate terrorizing Westfall.",sec={{t="The Threat in the Dust",b="Westfall has descended into ruin, stripped of its harvests and overrun by bandits wearing red bandanas. Gryan Stoutmantle and the People's Militia hold Sentinel Hill against near-constant harassment, yet they fight in the dark. Stoutmantle realizes that hacking away at stray looters will never save the region without finding the cartel's inner circle and identifying who commands them.",sp=0},{t="An Out-of-Town Contact",b="Rather than relying on official military channels or Stormwind's absentee nobles, Stoutmantle turns to his personal debts. He sends trusted adventurers past Elwynn into the Redridge Mountains. In the quiet lakeside village of Lakeshire, lurking on the upper floor of the local inn, sits a rogue named Wiley the Black. Knowing the underworld far better than any militia captain, Wiley represents the first thread in unraveling the Brotherhood's hideouts.",sp=0}},faq={{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is the leader of the People's Militia, a ragtag defense force stationed at Sentinel Hill in Westfall. With Stormwind neglecting the borderlands, he coordinates the defense of the few remaining local farmers and refugees.",al={"gryan stoutmantle","who gives this quest","quest giver westfall"}},{q="Why does Stoutmantle send you to Lakeshire?",a="The People's Militia lacks underground informants within Westfall itself. Stoutmantle calls in an old personal favor from Wiley the Black, a rogue residing in Lakeshire's inn, hoping underworld contacts can reveal who leads the thieves.",al={"why lakeshire","why go to redridge","why wiley"}},{q="Who is Wiley the Black?",a="Wiley the Black is a rogue staying on the second floor of the Lakeshire Inn in Redridge Mountains. He owes Gryan Stoutmantle a favor, making him a useful conduit for underground rumors and criminal connections.",al={"who is wiley","wiley lakeshire","wiley the black"}},{q="What is the Defias Brotherhood?",a="The Defias Brotherhood is a ruthless criminal cartel wearing red masks that has seized control of Westfall's farms, roads, and abandoned mines, actively driving out homesteaders and challenging the authority of Stormwind.",al={"defias brotherhood","what is defias","red bandana bandits"}},{q="Where can I find Wiley in Lakeshire?",a="Wiley the Black is located upstairs on the second floor of the Lakeshire Inn, which sits near the bridge in the Redridge Mountains town of Lakeshire.",al={"where is wiley","find wiley","wiley location"}},{q="Does this quest involve any combat?",a="No. This initial step is entirely informational. You simply journey from Sentinel Hill in Westfall across Elwynn Forest to the inn in Lakeshire to make contact with Wiley.",al={"is this quest hard","combat in defias brotherhood quest","enemies"}}},ang={["class:Rogue"]="Stoutmantle recognizes that formal soldiering cannot crack a criminal syndicate; it takes someone who understands shadows and street favors, leading directly to Wiley the Black.",["faction:Alliance"]="The long journey from Westfall to Redridge highlights how deeply Stormwind's outer territories must rely on one another while the capital remains indifferent."},kw={"defias","gryan stoutmantle","lakeshire","redridge","sentinel hill","westfall","wiley the black"},rel={"npc:gryan-stoutmantle","npc:wiley-the-black","topic:defias-brotherhood","zone:westfall","zone:redridge","subzone:lakeshire","subzone:lakeshire-inn"},m={start="Gryan Stoutmantle",["end"]="Wiley the Black",level="18",faction="Alliance",id=65},src={"The Defias Brotherhood (quest)"}}
E["quest:8675"] = {t="quest",n="Skychaser the Elder",z="westfall",s="Elder Skychaser is an ancestral spirit who manifests during the Lunar Festival atop the Sentinel Tower in Westfall. Honoring her allows travelers across the dust-swept plains to pay homage to the wisdom of ages past. In return, the elder acknowledges the burning vigor of the living and grants her blessing.",h="Elder Skychaser is an ancestral spirit who manifests during the Lunar Festival atop the Sentinel Tower in...",sec={{t="A Beacon in the Dust",b="Amid the troubled scrublands of Westfall, Sentinel Hill stands as the lone fortified redoubt against Defias raiders and roving scavengers. During the Lunar Festival, an ancestral spirit named Elder Skychaser takes her place on the open platform atop the Sentinel Tower. High above the dust and wind, she keeps a patient vigil over the weary soldiers and beleaguered settlers below, welcoming anyone who makes the climb to show respect.",sp=0},{t="Honoring the Ancestors",b="The Lunar Festival marks a sacred season observed across Azeroth, celebrating wisdom, heritage, and the deeds of ancient spirits who walked the earth before the present struggles. When approached, Elder Skychaser recognizes the vital spark within the traveler, accepting their homage and bestowing a token of her favor as a gift of kinship between the living and the honored dead.",sp=0}},faq={{q="Where can I find Elder Skychaser?",a="Elder Skychaser is located at the very top of Sentinel Tower at Sentinel Hill in Westfall. Climb the spiral stairs within the tower out onto the upper lookout ramparts.",al={"skychaser location","where is elder skychaser","skychaser westfall"}},{q="Why is Elder Skychaser standing on top of Sentinel Tower?",a="Ancestral spirits choose prominent and symbolic locations across Azeroth during the Lunar Festival. The heights of Sentinel Tower provide a watchful vantage over the Westfall basin, allowing the elder to witness travelers braving the frontier.",al={"why is he in sentinel tower","skychaser tower"}},{q="What is the purpose of this quest?",a="Seeking out Elder Skychaser is part of honoring ancestral elders during the Lunar Festival. Showing respect grants a Coin of Ancestry and a blessing celebrating the living spirit of the adventurer.",al={"skychaser quest reward","why honor elder skychaser"}},{q="Can Horde players honor Elder Skychaser?",a="Elder Skychaser herself is a peaceful spirit who welcomes all pilgrims. However, Sentinel Hill is a heavily defended Alliance outpost, making reaching her perilous for Horde adventurers.",al={"can horde visit skychaser","is skychaser hostile to horde"}},{q="Does Elder Skychaser participate in the defense of Sentinel Hill?",a="No. The elders who visit during the Lunar Festival are spiritual manifestations focused solely on tradition and ancient remembrance. Elder Skychaser takes no part in the People's Militia's skirmishes against the Defias Brotherhood.",al={"does skychaser fight defias","is skychaser part of the people's militia"}},{q="What does Skychaser say when you greet her?",a="Upon greeting her, Elder Skychaser remarks that your spirit burns brightly with life, graciously accepts the homage you bring, and offers an ancestral token in return.",al={"skychaser dialogue","what does the elder say"}}},ang={["faction:Alliance"]="Elder Skychaser is conveniently stationed within the heart of the People's Militia base at Sentinel Hill, making her an easy elder to honor while questing through Westfall.",["faction:Horde"]="Reaching Elder Skychaser requires stealth, speed, or brute force, as Sentinel Hill is filled with hostile Alliance guards and militia scouts.",["class:Druid"]="Druids hold the Lunar Festival sacred, recognizing ancestral manifestations like Skychaser as an enduring link to ancient traditions and deep natural reverence."},kw={"coin of ancestry","elder skychaser","lunar festival","sentinel hill","sentinel tower","skychaser","westfall"},rel={"subzone:sentinel-tower","subzone:sentinel-hill","zone:westfall"},m={start="Elder Skychaser",id=8675},src={"Skychaser the Elder"}}
E["quest:9"] = {t="quest",n="The Killing Fields",z="westfall",s="The Killing Fields is an Alliance quest offered by Farmer Saldean in Westfall. Saldean tasks adventurers with destroying the rogue Harvest Watchers that overrun his crops and the neighboring farmlands. It illustrates the collapse of local agriculture in the wake of the Defias Brotherhood's disruption.",h="The Killing Fields is an Alliance quest offered by Farmer Saldean in Westfall.",sec={{t="A Beleaguered Homestead",b="While many farmers across Westfall abandoned their acreage when bandits and outlaws swept through the region, Farmer Saldean and his family resolved to hold their ground. Unfortunately, squatting thieves are not the only threat choking the Saldean farm. The mechanical Harvest Watchers intended to tend and safeguard the grain have gone rampant, pacing the furrows and attacking anyone who approaches.",sp=0},{t="Clearing the Soil",b="To keep his farm operable, Saldean enlists passing travelers to dismantle twenty of the hostile automatons across his fields and adjoining plots. Culling these constructs offers temporary relief for Saldean's harvest, preserving a rare pocket of stubborn hope that Westfall's breadbasket might one day be reclaimed.",sp=0}},faq={{q="Who offers the quest The Killing Fields?",a="Farmer Saldean gives the quest from Saldean's Farm, situated along the road in central Westfall.",al={"quest giver killing fields","who gives the killing fields","saldean quest"}},{q="What are Harvest Watchers?",a="Harvest Watchers are clockwork scarecrows built to tend crops and guard fields from pests. Following the unrest and abandonment of Westfall, many of these mechanical constructs were left untended or reprogrammed, turning aggressively upon the very farmers they were designed to serve.",al={"what are harvest watchers","harvest watcher lore","mechanical scarecrows westfall"}},{q="Why has Farmer Saldean not fled Westfall like the others?",a="Unlike the neighbors who abandoned their homesteads to thieves and brigands, Saldean refuses to surrender his livelihood. He stubbornly maintains his plot with help from hired adventurers to repel the rogue machinery.",al={"why is saldean still here","farmer saldean lore","saldean staying"}},{q="What are the objectives of The Killing Fields?",a="You are tasked with destroying twenty Harvest Watchers found roaming Saldean's fields and the surrounding abandoned farms.",al={"killing fields objective","how many harvest watchers","what to kill for killing fields"}},{q="Who are the 'thieves' Saldean mentions?",a="Saldean is referring to the thieves and brigands loosely organized under the Defias Brotherhood, whose raids and extortion drove most homesteaders off their land.",al={"who are the thieves","saldean thieves","who drove farmers out westfall"}},{q="Does completing this quest fix Westfall's farming troubles?",a="Destroying the twenty Harvest Watchers provides immediate breathing room for Saldean's farm, but the overarching bandit threat and broken machinery across the broader region remain unresolved.",al={"does westfall recover","killing fields ending","saldean outcome"}}},ang={["faction:Alliance"]="For Alliance travelers, helping Saldean represents a direct effort to protect one of the few surviving food supplies in a territory abandoned by the Stormwind crown.",["profession:Engineering"]="Engineers will recognize the Harvest Watchers as automated clockwork wonders gone haywire in the absence of proper maintenance."},kw={"clockwork","defias","farmer saldean","harvest watchers","killing fields","saldean's farm","scarecrows","westfall"},rel={"npc:farmer-saldean","zone:westfall"},m={start="Farmer Saldean",level="15",faction="Alliance",id=9},src={"The Killing Fields"}}
E["quest:92742"] = {t="quest",n="Testing the Wells",z="westfall",s="Testing the Wells is an investigative task assigned by Alba Fairmoon to determine the source of poison seeping through Westfall's soil. Adventurers are sent with sampling kits to collect groundwater from the wells at the Jansen Stead and Molsen Farm.",h="Testing the Wells is an investigative task assigned by Alba Fairmoon to determine the source of poison...",sec={{t="Blight in the Aquifer",b="Westfall's open plains have suffered severe neglect and banditry, but an insidious contamination beneath the earth threatens whatever agriculture remains. To understand how the farmland is being tainted, Alba Fairmoon directs investigators to test the groundwater directly. By drawing water samples from settled farmsteads, investigators hope to identify the nature of the toxins plaguing the region's soil and life.",sp=0},{t="Farms of the Frontier",b="The survey focuses on two vital locations: the Jansen Stead and the Molsen Farm. Both plots lie among the scattered homesteads vulnerable to roaming Defias outlaws and feral wildlife. Drawing samples from their wellheads offers a baseline for whether the blighting agent is naturally emerging, magically induced, or deliberately seeded into the water table feeding the region.",sp=0}},faq={{q="What is the purpose of Testing the Wells?",a="Alba Fairmoon seeks to uncover the source and composition of the poison afflicting Westfall. Gathering fresh groundwater samples from farm wells provides the raw material needed to analyze the contamination.",al={"why test the wells","testing the wells goal","what is this quest for"}},{q="Who assigns this task?",a="The quest is given by Alba Fairmoon, who is investigating the spreading corruption and unnatural poisons plaguing the agrarian land of Westfall.",al={"who gives testing the wells","alba fairmoon quest","quest giver"}},{q="Which locations need to be sampled?",a="Water samples must be drawn from the working wells located at the Jansen Stead and the Molsen Farm in Westfall.",al={"where do i go","which wells","well locations"}},{q="What is threatening Westfall's water and soil?",a="An unknown blight or poison is actively corrupting the land. Testing local well water is the first step in assessing whether the aquifer beneath the local homesteads has been compromised.",al={"why is westfall poisoned","what is poisoning the land","poison source"}},{q="Is the contamination natural or artificial?",a="That remains the central question of the investigation. The samples from Jansen Stead and Molsen Farm are intended to reveal whether the rot stems from natural groundwater corruption or deliberate sabotage.",al={"is the water poisoned on purpose","who poisoned the wells"}},{q="Why focus on Jansen Stead and Molsen Farm?",a="These two homesteads represent established domestic wells tapping the subterranean water table across the plains, making them prime candidates for testing how far the corruption extends.",al={"why jansen and molsen","why these farms"}}},ang={["faction:Alliance"]="Restoring food production in Westfall is critical for the survival of the Kingdom of Stormwind, making the health of these farm wells a matter of kingdom-wide security.",["class:Druid"]="Unnatural toxins leeching through soil and fresh groundwater signal a severe wound in the balance of the land that demands remediation."},kw={"alba fairmoon","groundwater","jansen stead","molsen farm","poison","testing the wells","water sample","westfall"},rel={"zone:westfall","subzone:jansen-stead","subzone:molsen-farm"},m={start="Alba Fairmoon",level="12",faction="Alliance",id=92742},src={"Testing the Wells"},fv=true}
E["quest:92744"] = {t="quest",n="Murloc Gills",z="westfall",s="Murloc Gills is an Alliance task in Westfall given by Alba Fairmoon. Amid concerns that the crop blight could poison coastal fisheries, adventurers are dispatched to the Longshore to collect murloc gills for ecological analysis. Because murloc physiology is acutely sensitive to maritime contaminants, their gills reveal whether toxins have infiltrated the sea.",h="Murloc Gills is an Alliance task in Westfall given by Alba Fairmoon.",sec={{t="A Threat to the Coastline",b="Westfall is already on the verge of ruin due to widespread crop failure, displaced farmers, and banditry. Alba Fairmoon fears an even deadlier development: that the corruption afflicting the inland harvest has begun draining into the Great Sea. If Westfall's coastal waters are tainted, the fish stocks that feed the peasantry and supplement the tables of Stormwind City could vanish entirely, tipping a strained kingdom into outright famine.",sp=0},{t="Sentinels of Water Quality",b="While murlocs are notoriously stubborn and violent creatures, their amphibious biology makes them keen natural bio-indicators. Murloc respiratory systems constantly filter seawater, making their gill tissue exceptionally receptive to foreign poisons, blights, and unnatural pollutants. By studying freshly harvested gills taken from the tide-dwellers prowling the Longshore, Fairmoon hopes to measure the exact severity of the encroaching contamination.",sp=0}},faq={{q="Why does Alba Fairmoon want murloc gills?",a="Alba Fairmoon is investigating whether the blight ruining Westfall's crops has leached into the ocean. Murlocs are highly sensitive to aquatic contaminants, meaning their gills act as biological filters that quickly display any trace toxins or pollution present in the seawater.",al={"why murloc gills","alba fairmoon murlocs","purpose of quest"}},{q="Where are the murlocs located for this task?",a="The murlocs inhabit the Longshore, the long stretch of beach forming the western coast of Westfall. They prowl the shallows and tidal flats just past the bluffs.",al={"where are murlocs","longshore murloc location","murloc gill spot"}},{q="What is the broader danger if the ocean is corrupted?",a="Westfall is the primary breadbasket of the kingdom of Stormwind. With inland crops already failing, coastal fishing provides critical sustenance. If toxins poison the marine life along the shore, the kingdom could plunge into an inescapable famine.",al={"why does this matter","westfall famine danger","threat to stormwind"}},{q="Are murlocs particularly prone to disease?",a="Murlocs are hardy and resilient survivors in harsh environments, but their amphibious respiratory systems react immediately to chemical or magical impurities in the water, making them ideal subjects for studying waterborne pollution.",al={"murloc physiology","do murlocs get sick"}},{q="Does this quest connect to the Defias Brotherhood?",a="While the Defias Brotherhood is responsible for much of the chaos and neglected farmland across Westfall, this investigation focuses specifically on ecological blight and the preservation of food sources for the kingdom.",al={"defias connection","is this defias"}},{q="Who is Alba Fairmoon?",a="Alba Fairmoon is an Alliance researcher stationed in Westfall monitoring the blight and environmental decline threatening the region's agricultural viability.",al={"who is fairmoon","alba fairmoon lore"}}},ang={["faction:Alliance"]="With King Varian missing and food shortages already stoking unrest, protecting Westfall's remaining food supply is vital for keeping Stormwind stable.",["class:Druid"]="The spread of inland blight into coastal ecosystems threatens to corrupt native wildlife, making biological monitoring of indicator species like murlocs an essential safeguard.",["race:Human"]="For the people of Stormwind, Westfall's decline is an immediate existential threat to their homes, farmlands, and dinner tables."},kw={"alba fairmoon","blight","famine","longshore","murloc gills","seawater","stormwind","toxins","westfall"},rel={"zone:westfall","subzone:longshore","topic:murloc","topic:stormwind-kingdom"},m={start="Alba Fairmoon",level="12",faction="Alliance",id=92744},src={"Murloc Gills"},fv=true}
E["quest:92745"] = {t="quest",n="The State of the Mines",z="westfall",s="The State of the Mines is a task given by Alba Fairmoon to combat environmental contamination across Westfall. Toxic runoff from the region's seized dig sites threatens to ruin the farmland for decades. To stop this ecological disaster, adventurers are sent to disrupt Defias-led excavations at both Jangolode Mine and the Gold Coast Quarry.",h="The State of the Mines is a task given by Alba Fairmoon to combat environmental contamination across Westfall.",sec={{t="Poisoning the Land",b="Westfall was once the primary breadbasket of Stormwind, but recent water samples retrieved from local wells reveal dangerous levels of toxic metals. The reckless extraction methods practiced by the Defias Brotherhood have caused industrial runoff to seep deep into the regional aquifers. If this pollution continues unchecked, the surrounding earth will be rendered barren and unable to sustain crops for decades to come.",sp=0},{t="Forced and Enlisted Labor",b="Rather than relying solely on their own highwaymen, the Defias have conscripted and organized local creature populations to strip Westfall of its natural wealth. Riverpaw gnolls are set to backbreaking work digging out stone and mineral veins at the Gold Coast Quarry, while kobold diggers are put to work tunneling into the depths of the Jangolode Mine. Cutting down their workforce strikes directly at their ability to process and distribute contaminated minerals.",sp=0}},faq={{q="Why are the mines of Westfall leaking toxic metals?",a="The Defias Brotherhood has completely disregarded safety and conservation while ruthlessly stripping Westfall of raw materials. Their uncontrolled mining operations have contaminated groundwater with harmful metallic runoff, poisoning the soil and nearby settlement wells.",al={"why toxic water westfall","westfall mine pollution","toxic runoff westfall"}},{q="Who is behind the mining operations in Westfall?",a="The Defias Brotherhood controls the operations. They have seized former kingdom infrastructure and organized subservient creatures—specifically Riverpaw gnolls and kobolds—to handle the dangerous manual labor of extracting minerals.",al={"who runs the mines","who controls westfall mines","defias mining"}},{q="Where are the Riverpaw gnolls and kobolds working?",a="Riverpaw gnolls operate as miners out in the Gold Coast Quarry along the western shores, while kobold diggers are stationed inside the Jangolode Mine to the north.",al={"where are the miners","gold coast quarry location","jangolode mine location"}},{q="Who is Alba Fairmoon?",a="Alba Fairmoon is a concerned investigator and ally in Westfall who tests local water supplies and seeks to prevent the long-term devastation of the region's agricultural landscape.",al={"who gives state of the mines","alba fairmoon lore","quest giver"}},{q="Why are gnolls and kobolds working for the Defias?",a="The Defias frequently exploit, coerce, or hire local pest populations like the Riverpaw pack and subterranean kobolds to serve as expendable, cheap labor in their quarries and excavations.",al={"why defias hire gnolls","kobolds working for defias"}},{q="Can the land in Westfall recover from this contamination?",a="According to Alba Fairmoon, the soil can recover only if the source of the toxicity is severed quickly. If the mining continues uninterrupted, the earth will remain infertile and blighted for decades.",al={"will westfall soil heal","can crops grow again"}}},ang={["profession:Mining"]="Seeing the chaotic, unrefined operations at Jangolode and the Gold Coast Quarry makes it clear that the Defias value rapid extraction far more than safety or structural integrity.",["class:Druid"]="The seeping metallic poisons represent an urgent ecological threat to the plains and coastal ecosystems of Westfall, requiring immediate containment.",["faction:Alliance"]="Westfall is vital to feeding the population of Stormwind; allowing the Defias to ruin its arable earth threatens the entire kingdom with long-term famine."},kw={"alba fairmoon","defias","gold coast quarry","jangolode mine","kobold digger","mining","riverpaw","toxic runoff","westfall"},rel={"zone:westfall","subzone:jangolode-mine","subzone:gold-coast-quarry","topic:kobold"},m={start="Alba Fairmoon",level="14",faction="Alliance",id=92745},src={"The State of the Mines"},fv=true}
E["quest:92747"] = {t="quest",n="Moonbrook Espionage",z="westfall",s="Moonbrook Espionage is an Alliance task assigned by Alba Fairmoon to scout the overrun settlement of Moonbrook. Believing a mysterious toxin did not come from lesser Westfall dig sites, investigators turn their attention toward the ancient, long-abandoned Deadmines beneath the town to uncover evidence of active industrial operations.",h="Moonbrook Espionage is an Alliance task assigned by Alba Fairmoon to scout the overrun settlement of...",sec={{t="A Toxic Trail",b="After looking into local mines across Westfall, investigators hit a dead end: the poison plaguing the region does not appear to originate from any known surface excavation. This leaves only one major excavation left unexplored—the cavernous, sprawling shafts of the Deadmines resting directly beneath the ruined township of Moonbrook.",sp=0},{t="Secrets of the Deadmines",b="Official accounts claim the Deadmines were abandoned following the First War when the Horde overran the region. However, the discovery of modern industrial gear and supplies scattered throughout Moonbrook strongly suggests that someone is secretly running an extensive mining and manufacturing operation behind the facade of a ruined ghost town.",sp=1}},faq={{q="Who assigns Moonbrook Espionage?",a="The quest is assigned by Alba Fairmoon, who has been investigating suspicious toxins and industrial activities across the contested territory of Westfall.",al={"quest giver","who gives moonbrook espionage","alba fairmoon"}},{q="Why is Alba investigating Moonbrook?",a="Other local mines showed no signs of producing the poison under investigation. Because Moonbrook sits directly over the Deadmines, Alba suspects someone is running an illicit operation hidden beneath the town.",al={"why moonbrook","what is in moonbrook","investigate moonbrook"}},{q="What are the Deadmines?",a="The Deadmines are the deepest, most expansive gold mines in the region. Abandoned since the First War after the fall of Stormwind, they have long been assumed to be empty ruins haunted by vermin and bandits.",al={"deadmines lore","what are deadmines","history of deadmines"}},{q="What items are gathered during this scouting mission?",a="Scouts are sent to retrieve Suspicious Industrial Supplies scattered throughout Moonbrook, proving that active industrial work and refining are taking place near the mine shafts.",al={"suspicious industrial supplies","quest items moonbrook espionage"}},{q="What threats occupy Moonbrook right now?",a="Moonbrook is currently overrun by the Defias Brotherhood, who use the derelict buildings as a forward staging ground and guard the surface entrance leading down into the subterranean network.",al={"moonbrook enemies","who controls moonbrook"}},{q="What does finding these supplies prove?",a="The presence of modern, heavy industrial equipment in an allegedly abandoned town confirms that a coordinated faction is undertaking large-scale fabrication, hidden away from the prying eyes of Stormwind's authorities.",al={"what do the supplies mean","defias industry"}}},ang={["class:Rogue"]="Slipping through Moonbrook unspotted offers rogues a textbook opportunity to gather intelligence on Defias operations without raising the alarm.",["profession:Mining"]="Miners understand better than anyone the sheer wealth and logistical scale hidden within the deep shafts beneath Moonbrook.",["faction:Alliance"]="Uncovering active industry in Moonbrook signals a direct threat to the breadbasket of Westfall and the security of Stormwind itself."},kw={"alba fairmoon","deadmines","espionage","industrial supplies","mines","moonbrook","poison","westfall"},rel={"subzone:moonbrook","zone:deadmines","subzone:deadmines","zone:westfall","topic:first-war"},m={start="Alba Fairmoon",level="16",faction="Alliance",id=92747},src={"Moonbrook Espionage"},fv=true}
E["quest:92748"] = {t="quest",n="Explosive Consultation",z="westfall",s="Explosive Consultation is an Alliance assignment originating in Westfall to combat toxic industrial operations hidden deep within the Deadmines. Following discoveries that point to heavy machinery poisoning local farmland, adventurers are dispatched to the Dwarven District of Stormwind to enlist an engineering specialist capable of supplying heavy explosives.",h="Explosive Consultation is an Alliance assignment originating in Westfall to combat toxic industrial...",sec={{t="A Toxic Source",b="While Westfall contends with displaced vagrants and banditry under the Defias Brotherhood, evidence gathered across the region reveals a far more coordinated and mechanised threat festering beneath the earth. Industrial refuse and caustic toxins creeping into the surrounding soil have been traced directly back into the labyrinthine tunnels of the Deadmines, indicating that an organized operation is working tirelessly underground.",sp=0},{t="Seeking Stormwind's Expertise",b="Conventional weaponry is insufficient to sabotage fortified subterranean infrastructure. Halting the poisoning of Westfall requires industrial demolition, prompting an urgent summons to Stormwind City's Dwarven District. There, among the roaring forges, tinkerers, and blasting powder merchants, an engineering mind named Sprite Jumpsprocket must be recruited to devise an explosive remedy.",sp=0}},faq={{q="Why do we need explosives in the Deadmines?",a="Evidence recovered in Westfall indicates that a massive industrial operation hidden inside the Deadmines is actively generating toxins that foul the surrounding farmland. Smashing reinforced machinery by hand is impractical, requiring heavy-duty ordnance to disable.",al={"why explosives deadmines","why do we need bombs","deadmines toxins reason"}},{q="Who starts this quest?",a="Alba Fairmoon gives this task to heroes investigating the unnatural contaminants and unrest threatening Westfall.",al={"who gives explosive consultation","explosive consultation start"}},{q="Who is Sprite Jumpsprocket?",a="Sprite Jumpsprocket is a gnome engineer residing in the Dwarven District of Stormwind. Known for working with complex mechanical devices and volatile compounds, she is sought out to craft high-yield demolitions.",al={"sprite jumpsprocket location","who is jumpsprocket"}},{q="Why travel to the Dwarven District for help?",a="The Dwarven District serves as the industrial heart of Stormwind, housing the kingdom's premier blacksmiths, tinkerers, and suppliers of blasting powder and engineering components.",al={"why dwarven district","stormwind dwarven district connection"}},{q="Does Stormwind's government assist with this effort?",a="With King Varian Wrynn missing and the House of Nobles reluctant to commit formal military garrisons to Westfall, local defenders must rely on independent volunteers and private craftsmen in the capital rather than regular army regiments.",al={"does the army help","why stormwind engineer"}}},ang={["profession:Engineering"]="Engineers will appreciate that brute force cannot solve Westfall's ecological plight; disabling large-scale underground machinery demands specialized munitions and meticulous technical expertise.",["race:Gnome"]="Gnomish technological ingenuity is vital for neutralizing underground industrial threats that regular Alliance military forces fail to address.",["faction:Alliance"]="This task demonstrates the interdependence of Westfall's struggling frontier communities and the bustling workshops of Stormwind's Dwarven District."},kw={"alba fairmoon","deadmines","dwarven district","engineering","explosive consultation","sprite jumpsprocket","stormwind","toxins","westfall"},rel={"npc:sprite-jumpsprocket","zone:westfall","subzone:dwarven-district","zone:deadmines","subzone:deadmines","topic:stormwind-kingdom"},m={start="Alba Fairmoon",["end"]="Sprite Jumpsprocket",level="16",faction="Alliance",id=92748},src={"Explosive Consultation"},fv=true}
E["quest:92749"] = {t="quest",n="A Dynamite Plan",z="westfall",s="A Dynamite Plan is a task offered by the inventive tinkerer Sprite Jumpsprocket in Stormwind's Dwarven District. Stirred by rumors of brewing industrial sabotage, she seeks a sizable stash of coarse dynamite to kick-start her explosive countermeasures. Adventurers must manufacture or acquire the munitions to support her scheming.",h="A Dynamite Plan is a task offered by the inventive tinkerer Sprite Jumpsprocket in Stormwind's Dwarven...",sec={{t="Sparks in the Dwarven District",b="Amid the clatter and smoke of Stormwind's Dwarven District, gnome engineer Sprite Jumpsprocket is rarely one to shy away from radical solutions. When reports of industrial sabotage reach her ears, her immediate instinct is not caution, but counteraction. To fight fire with fire—or rather, sabotage with high explosives—she enlists passing mercenaries to supply her with a bundle of coarse dynamite.",sp=0},{t="Gnomish Ambitions",b="Procuring the explosives requires a capable hand at an engineering workbench or a knack for trading among the city's craftsmen. Ten sticks of coarse dynamite provide more than enough firepower to disrupt whatever industrial schemes are unfolding in the surrounding territories, demonstrating the practical, if perilous, methods gnomes favor when solving mechanical and political disruptions alike.",sp=0}},faq={{q="Who is Sprite Jumpsprocket?",a="Sprite Jumpsprocket is an engineer found working among the smithies and workshops of the Dwarven District in Stormwind City. She is known for pursuing audacious and volatile engineering projects.",al={"sprite jumpsprocket","who is sprite","quest giver"}},{q="What does Sprite need for this task?",a="She requires ten sticks of coarse dynamite. These can be manufactured using engineering techniques or acquired through trade and the auction house from other crafters.",al={"dynamite plan items","what do i need","items needed"}},{q="Why does Sprite want coarse dynamite?",a="Hearing whispers of industrial sabotage, Sprite believes the best way to handle the problem is to launch her own explosive enterprise, starting with a dependable stockpile of basic blasting charges.",al={"why dynamite","dynamite purpose","sabotage motive"}},{q="Where do I turn in the quest?",a="Sprite Jumpsprocket is located in the Dwarven District within the walls of Stormwind City.",al={"where to turn in","hand in location","sprite location"}},{q="Is engineering required to complete this quest?",a="No, engineering is not strictly required. While engineers can craft the coarse dynamite themselves, any adventurer can trade with players or buy the required dynamite from the auction house.",al={"do i need engineering","engineering requirement","can non engineers do this"}},{q="How does this relate to broader troubles around Stormwind?",a="Fringe syndicates and bandits frequently disrupt mining, farming, and transport throughout Westfall and Elwynn Forest. Urban tinkerers like Sprite often take matters into their own hands to protect or exploit commercial ventures threatened by regional lawlessness.",al={"stormwind troubles","westfall sabotage","industrial sabotage lore"}}},ang={["profession:Engineering"]="Engineers can craft coarse dynamite using coarse blasting powder and linen cloth, making this task a straightforward test of early tinkercraft.",["race:Gnome"]="Sprite Jumpsprocket exemplifies the classic gnomish impulse: meeting complicated industrial problems with clever, combustible contraptions.",["faction:Alliance"]="Supplying explosives within the city walls aids private dwarven and gnomish interests working to secure Alliance industrial ventures."},kw={"coarse dynamite","dwarven district","engineering","explosives","sabotage","sprite jumpsprocket","stormwind"},rel={"npc:sprite-jumpsprocket","subzone:dwarven-district","topic:stormwind-kingdom","zone:westfall"},m={start="Sprite Jumpsprocket",level="16",faction="Alliance",id=92749},src={"A Dynamite Plan"},fv=true}
E["quest:92750"] = {t="quest",n="Detonation at a Distance",z="westfall",s="Detonation at a Distance sends an adventurer seeking specialized explosives expertise across the capital of Stormwind. After being prompted by the eccentric gnome tinkerer Sprite Jumpsprocket, you are directed to Stormwind Intelligence to procure a remote detonator.",h="Detonation at a Distance sends an adventurer seeking specialized explosives expertise across the capital of...",sec={{t="A Controlled Blast",b="While goblins and gnomes are both notorious for their reckless abandon with volatile chemicals, not every demolition task calls for standing directly beside the payload. When standard fuses risk life and limb, remote detonation becomes an absolute necessity. Sprite Jumpsprocket recognizes that a controlled explosion requires specialized trigger mechanisms that common tinkerers do not carry in everyday surplus.",sp=0},{t="Calling Upon the SI:7",b="Instead of turning to local dwarven blasters or standard engineering supplies, Sprite directs the search toward Stormwind Intelligence, operating out of Old Town. Known colloquially as SI:7, the kingdom's covert operative network regularly handles sensitive sabotage, stealth infiltration, and targeted demolitions. Jasper Fel, an operative embedded within the capital, is precisely the sort of shadowy contact who manages such discreet and dangerous equipment.",sp=0}},faq={{q="Who sends you on this mission?",a="The quest is handed out by Sprite Jumpsprocket, an Alliance-aligned gnome tinkerer found in the Dwarven District of Stormwind.",al={"quest giver","who starts detonation at a distance","sprite jumpsprocket quest"}},{q="Who do you need to talk to in Stormwind?",a="You are directed to speak with Jasper Fel, an associate of Stormwind Intelligence stationed in the capital city of Stormwind.",al={"where to turn in","stormwind intelligence contact","jasper fel location"}},{q="Why does Sprite Jumpsprocket need a remote detonator?",a="Sprite notes that while remote detonations might lack the chaotic excitement of an uncontrolled blast, keeping your limbs intact makes a distance trigger far more practical for dangerous explosive work.",al={"why remote detonator","purpose of detonation"}},{q="Why contact Stormwind Intelligence rather than an engineer?",a="Stormwind Intelligence maintains covert supplies and specialized sabotage gear that ordinary city merchants or field tinkerers do not publicly stock or distribute.",al={"why si7","why stormwind intelligence"}},{q="Where is Jasper Fel located in Stormwind?",a="Jasper Fel is situated in Old Town within the headquarters of SI:7, where Stormwind's spies and covert agents conduct their operations.",al={"jasper fel stormwind","jasper fel room"}},{q="What faction can undertake this task?",a="This assignment is strictly available to members of the Alliance, as it relies on cooperation with Stormwind's royal intelligence division.",al={"is this alliance only","can horde do this"}}},ang={["class:Rogue"]="Visiting Jasper Fel means stepping into the center of SI:7 operations in Old Town, the heart of human covert tradecraft.",["profession:Engineering"]="While engineers frequently build their own fuses and dynamite, securing military-grade remote triggers often requires contacts who specialize in quiet sabotage.",["race:Gnome"]="Sprite Jumpsprocket exemplifies the classic gnomish interest in engineering problems, even if she defers to human intelligence for specific spycraft munitions."},kw={"detonation at a distance","jasper fel","remote detonator","si:7","sprite jumpsprocket","stormwind intelligence","westfall"},rel={"npc:sprite-jumpsprocket","npc:jasper-fel","zone:westfall","topic:stormwind-kingdom"},m={start="Sprite Jumpsprocket",["end"]="Jasper Fel",level="16",faction="Alliance",id=92750},src={"Detonation at a Distance"},fv=true}
E["quest:92751"] = {t="quest",n="Detonation at a Distance",z="westfall",s="Detonation at a Distance is an Alliance assignment initiated by Jasper Fel within Stormwind's intelligence circle. Learning of dangerous operations beneath Moonbrook, the spymaster provides a specialized remote detonator to safely handle demolitions without blowing up friendly operatives.",h="Detonation at a Distance is an Alliance assignment initiated by Jasper Fel within Stormwind's intelligence...",sec={{t="Eyes in the Shadows",b="Jasper Fel and the operatives of SI:7 monitor nearly everything unfolding across Stormwind's territories, especially chaotic borderlands like Westfall. When word reaches Fel of explosive operations in Moonbrook, he is already well aware of what is brewing in the abandoned mining tunnels beneath the countryside.",sp=0},{t="A Prototype Solution",b="Setting off massive explosions in confined cavern systems carries obvious hazards. Fel provides a prototype Remote Detonator Kit developed by Alliance-aligned engineers, ensuring that any detonation beneath Westfall can be triggered safely from outside. He directs the courier to deliver the hardware to Sprite Jumpsprocket in the Dwarven District, while quietly reminding them not to mention SI:7's involvement to their elven associates.",sp=1}},faq={{q="Who is Jasper Fel?",a="Jasper Fel is an operative tied to Stormwind's intelligence service, SI:7. Working out of the shadows, he keeps tabs on covert threats across the kingdom and provides specialized tools to handle them.",al={"jasper fel","who gives detonation at a distance","quest giver"}},{q="Why does SI:7 care about Moonbrook?",a="Moonbrook has fallen into the grip of bandits and outlaws, serving as the surface entrance to the Deadmines. Any activities or demolition deep beneath Westfall immediately draw the attention of Stormwind's internal intelligence network.",al={"why moonbrook","defias connection","westfall caves"}},{q="Who is Sprite Jumpsprocket?",a="Sprite Jumpsprocket is a gnome operative stationed in the Dwarven District of Stormwind who handles specialized technical equipment and prototypes.",al={"sprite jumpsprocket","who receives the detonator","turn in npc"}},{q="Who is the 'elf friend' Jasper Fel mentions?",a="Jasper Fel is referring to an elven contact assisting your efforts against the Westfall insurgents. SI:7 prefers to operate with secrecy and plausible deniability, keeping outside allies in the dark regarding their direct support.",al={"elf friend","dont tell elf","jasper fel elf"}},{q="What is the Remote Detonator Kit used for?",a="It is an engineering prototype designed to trigger demolition charges from a safe distance, allowing operatives to collapse or clear underground passages without being trapped inside.",al={"remote detonator","detonator kit","what does the kit do"}},{q="Where does this quest take you?",a="The quest tasks you with carrying the detonator kit directly to Sprite Jumpsprocket in the Dwarven District of Stormwind City.",al={"where do i go","quest route","turn in location"}}},ang={["class:Rogue"]="Dealing directly with Jasper Fel highlights SI:7's extensive covert network, showing how the kingdom's spymasters monitor field operatives and quietly supply them with the right tools.",["race:Gnome"]="The delivery to Sprite Jumpsprocket showcases gnome ingenuity at work in Stormwind, supplying the kingdom's spies with cutting-edge prototypes.",["faction:Alliance"]="The quest reflects Stormwind's struggle to reclaim Westfall, using covert engineering and intelligence rather than an open military deployment.",["profession:Engineering"]="Engineers will appreciate the prototype remote detonator, designed to replace risky manual fuses during complex cave demolitions."},kw={"deadmines","dwarven district","jasper fel","moonbrook","remote detonator","si:7","sprite jumpsprocket","westfall"},rel={"npc:jasper-fel","npc:sprite-jumpsprocket","quest:2300","subzone:dwarven-district","subzone:moonbrook","zone:westfall","topic:stormwind-kingdom"},m={start="Jasper Fel",["end"]="Sprite Jumpsprocket",level="16",faction="Alliance",id=92751},src={"Detonation at a Distance (2)"},fv=true}
E["quest:92752"] = {t="quest",n="Explosive Consultation",z="westfall",s="Explosive Consultation is a Westfall assignment involving gnome tinkerer Sprite Jumpsprocket and Alba Fairmoon. Having secured an extraordinarily volatile payload, Sprite entrusts a courier to return the primed charge safely without accidentally setting off the detonator.",h="Explosive Consultation is a Westfall assignment involving gnome tinkerer Sprite Jumpsprocket and Alba...",sec={{t="A Volatile Delivery",b="Gnomish engineering is rarely known for moderation, and Sprite Jumpsprocket's handiwork in Westfall holds true to the craft's reputation. After finalizing the concoction, Sprite provides a bundle of Extra-Destructive Explosives intended for Alba Fairmoon. Courier work in wartime Westfall is dangerous enough when evading Defias bandits and feral beasts, but carrying live, hair-trigger ordnance adds a distinctive level of hazard.",sp=0},{t="Handling with Care",b="Sprite Jumpsprocket offers simple but vital counsel upon handing over the payload: mind the detonator. Whether intended for clearing obstacles, breaking reinforced fortifications, or undermining Defias operations across the contested plains, the volatile cargo must arrive intact before Alba Fairmoon can put it to use.",sp=0}},faq={{q="Who starts the quest Explosive Consultation?",a="The quest is given by Sprite Jumpsprocket, a gnome tinkerer in the Dwarven District of Stormwind who supplies specialized explosives.",al={"who gives explosive consultation","quest giver explosive consultation","sprite jumpsprocket quest"}},{q="Who receives the explosives at the end of the quest?",a="The finished Extra-Destructive Explosives must be delivered directly to Alba Fairmoon in Westfall.",al={"where do i take the explosives","who turns in explosive consultation","alba fairmoon explosive"}},{q="What item are you tasked with transporting?",a="Sprite entrusts you with a package of Extra-Destructive Explosives, complete with an active and delicate detonator.",al={"what is sprite handing over","explosive consultation item","what bomb is this"}},{q="Why are explosives needed in Westfall?",a="Westfall is locked in conflict against the Defias Brotherhood and overrun with hostile automatons and scavengers. Heavy ordnance is often required to shatter barricades, clear obstructed paths, or neutralize fortified threats across the farmland.",al={"why do they need bombs","westfall explosives purpose","why blow things up in westfall"}},{q="Is this quest available to Horde adventurers?",a="No. Sprite Jumpsprocket and Alba Fairmoon operate in support of Alliance operations, making this task exclusive to Alliance players.",al={"can horde do explosive consultation","horde explosive consultation"}},{q="Does Sprite Jumpsprocket warn you about any specific danger?",a="Sprite explicitly cautions that the bomb is primed and that you must handle the detonator with extreme care on the journey.",al={"sprite warning","bomb warning westfall"}}},ang={["profession:Engineering"]="Any practicing engineer will recognize the typical risks of gnomish ordnance: maximum yield paired with a hair-trigger detonator.",["race:Gnome"]="Sprite Jumpsprocket represents Gnomeregan's explosive problem-solving, bringing high-yield technological solutions to Westfall's turbulent front.",["faction:Alliance"]="Alliance operatives across Westfall rely on unconventional armaments to counter entrenched bandit encampments and rogue machinery."},kw={"alba fairmoon","detonator","explosive consultation","explosives","gnome engineering","sprite jumpsprocket","westfall"},rel={"npc:sprite-jumpsprocket","zone:westfall"},m={start="Sprite Jumpsprocket",["end"]="Alba Fairmoon",level="16",faction="Alliance",id=92752},src={"Explosive Consultation (2)"},fv=true}
E["quest:92753"] = {t="quest",n="Destruction in Deadmines",z="westfall",s="Destruction in Deadmines is a covert sabotage mission coordinated by Alba Fairmoon to strike at the heart of the Defias Brotherhood's industrial operations. Deep within the labyrinthine tunnels beneath Moonbrook, the Brotherhood runs a massive metallurgical forge suspected of poisoning the surrounding land. Adventurers are tasked with penetrating the complex, planting powerful explosives near the foundry, and crippling the brotherhood's war effort.",h="Destruction in Deadmines is a covert sabotage mission coordinated by Alba Fairmoon to strike at the heart of...",sec={{t="Sabotaging the Foundry",b="The Deadmines hold more than just gold veins and cutpurses; beneath the dusty surface of Moonbrook lies a fortified industrial complex fueling the Defias Brotherhood. Among their underground works is a heavy metallurgical forge used to smelt metals and assemble machinery. Alba Fairmoon identifies this forge as the likely origin of environmental contamination blighting the area, making its demolition a vital goal.",sp=0},{t="A Decisive Blast",b="Reaching the heart of the Deadmines requires fighting through barricades, cutthroats, and goblin engineers. Armed with Extra-Destructive Explosives, an operative must plant the charge directly beside the forge works and make a hasty escape to the hills above Moonbrook, where Fairmoon waits to trigger the blast and permanently disable the brotherhood's manufacturing capability.",sp=1}},faq={{q="What is the goal of this mission?",a="The objective is to infiltrate the Deadmines beneath Moonbrook, locate the Defias Brotherhood's metallurgical forge, and plant Extra-Destructive Explosives nearby before rendezvous with Alba Fairmoon at the exit.",al={"quest objective","what do i do","what is destruction in deadmines"}},{q="Who is Alba Fairmoon?",a="Alba Fairmoon is an Alliance operative working in Westfall who believes the blight and poison corrupting the region stem from heavy smelting and industrial operations inside the Deadmines.",al={"who is alba","alba fairmoon lore","quest giver"}},{q="Why is the Defias forge considered so dangerous?",a="Beyond producing weapons and machinery for Edwin VanCleef's brotherhood, the metallurgical forge discharges toxic waste and fumes that poison the surrounding soil and water of Westfall.",al={"why destroy the forge","what does the forge do","forge poison"}},{q="Where does the player meet Alba after planting the explosives?",a="Alba Fairmoon waits outside the Deadmines complex in the hills behind Moonbrook near the mine's upper exit, ready to trigger the demolition once the operative safely emerges.",al={"where is alba waiting","deadmines exit location","turn in location"}},{q="Where is the forge located inside the Deadmines?",a="The forge is located deep inside the Deadmines instance, past the mining tunnels and within the industrial foundry sections manned by Defias laborers and goblin overseers.",al={"where is the forge","forge location deadmines","find the forge"}},{q="Does destroying the forge heal the land immediately?",a="Alba hopes that eliminating the heavy smelting operations will allow the land around Moonbrook to finally recover, though years of Defias industry and neglect will take time to wash away.",al={"will the land heal","does the poison stop","forge aftermath"}}},ang={["profession:Engineering"]="Using specialized Extra-Destructive Explosives against heavy industrial infrastructure requires precise placement near key structural stress points to ensure total destruction of the forge.",["profession:Mining"]="The Deadmines were once Stormwind's most lucrative gold and iron mines, now perverted by the Defias into a fortified smelting complex that blights the earth.",["faction:Alliance"]="Crippling the Defias forge strikes directly at the machinery and weaponry threatening Stormwind's sovereignty from within Westfall."},kw={"alba fairmoon","deadmines","defias brotherhood","extra-destructive explosives","metallurgical forge","moonbrook","sabotage","westfall"},rel={"subzone:deadmines","zone:deadmines","subzone:moonbrook","zone:westfall"},m={start="Alba Fairmoon",level="18",faction="Alliance",id=92753},src={"Destruction in Deadmines"},fv=true}
E["quest:92819"] = {t="quest",n="Destruction in Deadmines",z="westfall",s="Destruction in Deadmines is a clandestine mission overseen by Alba Fairmoon in Westfall. Tasked with triggering an explosive charge, the operative is sent deep beneath the region to detonate a device and cripple Defias operations within the labyrinthine tunnels.",h="Destruction in Deadmines is a clandestine mission overseen by Alba Fairmoon in Westfall.",sec={{t="Sabotage Beneath Westfall",b="The Deadmines have long harbored the core strength of the Defias Brotherhood, serving as both a stronghold and an industrial nerve center right beneath Westfall. Rather than relying solely on a direct assault through every fortified corridor, Alba Fairmoon directs a decisive act of sabotage. By planting explosives and detonating them within the subterranean complex, Alliance operatives aim to collapse vital infrastructure and derail whatever schemes the brotherhood is orchestrating in the dark.",sp=0},{t="The Detonator",b="Carrying out this assignment requires a steady hand and precise timing. Alba provides a detonator meant to trigger demolition charges placed within the stronghold. Striking directly at the mine's structural vulnerabilities ensures that the Defias will suffer lasting damage to their supply lines, machinery, and defensive works, buying valuable time for the defenders of Westfall above.",sp=0}},faq={{q="Who offers the quest Destruction in Deadmines?",a="The mission is given by Alba Fairmoon, an operative stationed in Westfall who directs Alliance adventurers to strike directly at the Defias Brotherhood's stronghold.",al={"who gives destruction in deadmines","quest giver deadmines detonation","alba fairmoon quest"}},{q="What is the primary objective of this mission?",a="You are tasked with triggering a detonator inside the Deadmines complex to trigger explosives and cripple the Defias operations buried beneath the region.",al={"what do i do in destruction in deadmines","destruction in deadmines goal","how to complete destruction in deadmines"}},{q="Why target the Deadmines with explosives?",a="The Deadmines are not just an abandoned gold mine; they house the Defias Brotherhood's central workshops, supplies, and assembly operations. Collapsing key points with explosives disrupts their ability to wage their underground campaign against Westfall and Stormwind.",al={"why blow up deadmines","deadmines sabotage lore","why use detonator in deadmines"}},{q="Where does this quest take place?",a="The mission begins with Alba Fairmoon in Westfall and takes you into the sprawling subterranean tunnels of the Deadmines beneath Moonbrook.",al={"destruction in deadmines location","where is destruction in deadmines","deadmines detonator location"}},{q="Is this mission available to Horde players?",a="No. Alba Fairmoon works exclusively with Alliance operatives defending Westfall against the rising threat of the Defias Brotherhood.",al={"is destruction in deadmines alliance only","can horde do destruction in deadmines"}},{q="What threat does the Defias Brotherhood pose in Westfall?",a="The Defias Brotherhood has driven out farmers, raided settlements, and seized the abandoned mines of Westfall. Operating from deep within the Deadmines, they are building an armed insurrection that directly threatens the kingdom of Stormwind.",al={"defias lore westfall","why fight defias","what are defias doing in deadmines"}}},ang={["profession:Engineering"]="Demolition and remotely triggered detonators are central to this assignment, appealing to engineers who appreciate the fine art of controlled structural collapses.",["class:Rogue"]="Infiltrating enemy territory to plant charges and slip out before the explosion makes this mission a classic exercise in covert sabotage.",["faction:Alliance"]="Every blow struck against the Defias stronghold in the Deadmines helps safeguard the struggling farmsteads of Westfall and the southern border of Stormwind."},kw={"alba fairmoon","deadmines","defias","destruction in deadmines","detonator","explosives","sabotage","westfall"},rel={"zone:westfall"},m={start="Alba Fairmoon",level="18",faction="Alliance",id=92819},src={"Destruction in Deadmines (2)"},fv=true}
E["subzone:alexston-farmstead"] = {t="subzone",n="Alexston Farmstead",z="westfall",s="The Alexston Farmstead is a derelict farm in Westfall, overgrown and prowled by haywire Harvest Watchers. Once the childhood home of Stormwind's city architect, Baros Alexston, it has fallen into ruin like much of the breadbasket around it.",h="The Alexston Farmstead is a derelict farm in Westfall, overgrown and prowled by haywire Harvest Watchers.",sec={{t="A Fallen Homestead",b="Situated amidst the dry plains of Westfall, the Alexston Farmstead stands as another grim testament to the kingdom's neglect. Like neighboring estates, the farm was abandoned by its caretakers when banditry erupted across the countryside. Today, the fields are overgrown, and the mechanical Harvest Watchers left behind to tend the crops have spun out of control, violently attacking anyone who approaches the barren farmhouse.",sp=0},{t="Humble Roots",b="Despite its bleak state, the farm is tied to one of Stormwind's most prominent citizens. Baros Alexston, the skilled architect who helped design parts of the rebuilt capital, spent his youth toiling on these very fields. He left the farmstead long before the unrest began to pursue his trade in masonry and construction, leaving behind a memento of his early life nestled among the ruins.",sp=0}},faq={{q="Who owns the Alexston Farmstead?",a="The farmstead takes its name from the family of Baros Alexston, the city architect of Stormwind. Baros worked the land here as a young boy before moving to the capital to pursue architecture.",al={"who owns this farm","alexston owner","whose farm is this"}},{q="Why is the farm abandoned?",a="Like much of Westfall, the farmstead was abandoned in the wake of widespread unrest and banditry by the Defias Brotherhood. With the kingdom unable to offer protection, the farmers fled, leaving the homestead to rot.",al={"why abandoned","what happened to alexston farm","who ruined the farm"}},{q="Why are mechanical scarecrows attacking people here?",a="The mechanical Harvest Watchers were originally built to work the soil and protect crops from scavengers. Left unmaintained after the farmers fled, their internal clockwork has malfunctioned, turning them violently hostile to any living creature.",al={"why harvest watchers attack","hostile scarecrows","harvest golems hostile"}},{q="Is there anything hidden inside the farmhouse?",a="Baros Alexston left behind a personal compass in the farmhouse from his youth. Travelers doing work in Stormwind City are sometimes asked to retrieve it from the abandoned homestead.",al={"quest here","loot in farm","baros item"}}},ang={["faction:Alliance"]="The farm is a reminder of the quiet, hardworking roots that built Stormwind's finest minds, as well as the Alliance's ongoing struggle to protect its own borders."},kw={"alexston","architect","baros","compass","farmstead","harvest watcher","westfall"},rel={"npc:baros-alexston","quest:399","zone:westfall","zone:stormwind","topic:defias-brotherhood","topic:stormwind-kingdom"},src={"Alexston Farmstead"}}
E["subzone:cooper-residence"] = {t="subzone",n="Cooper Residence",z="westfall",s="The Cooper Residence is a dilapidated home located on the western fringes of Moonbrook in Westfall. Once the dwelling of the Cooper family, it now lies abandoned and pillaged alongside the rest of the ruined town. For travelers picking through the wreckage of Moonbrook, the house serves as a stark reminder of the ordinary lives displaced by the rise of the Defias Brotherhood.",h="The Cooper Residence is a dilapidated home located on the western fringes of Moonbrook in Westfall.",sec={{t="A Ruined Homestead",b="Standing amid the dust and decay of Moonbrook, the Cooper Residence was once a quiet family dwelling before crime and poverty engulfed the region. When the Defias Brotherhood seized control of Moonbrook and turned it into their regional hub, the honest folk living here were driven away or forced into hiding. Today, the building sits ransacked and stripped of comfort, surrounded by outlaws and hostile prowlers, leaving behind little more than forgotten journals and old newspapers discarded on the floorboards.",sp=0}},faq={{q="Who were the Coopers?",a="The Coopers were an ordinary human family living in Moonbrook prior to the collapse of Westfall's local government. Like many villagers, they were forced to abandon their home when the Defias Brotherhood overtook the settlement, leaving their property to decay.",al={"who lived here","cooper family","who are the coopers"}},{q="What can be found inside the house?",a="Scattered on the floor of the abandoned residence are forgotten texts from Moonbrook's past, including old issues of The Moonbrook Times and a dusty journal that sheds light on the local turmoil.",al={"what is in cooper residence","cooper house items","cooper residence loot"}},{q="Why is Moonbrook abandoned?",a="Moonbrook was once the thriving center of Westfall's rural community. When the House of Nobles failed to pay the Stonemasons Guild after rebuilding Stormwind, Edwin VanCleef formed the Defias Brotherhood, claiming the struggling frontier towns and driving the residents away.",al={"what happened to moonbrook","why is town ruined","moonbrook fall"}},{q="Is the Cooper Residence safe to explore?",a="Not at all. The surrounding streets of Moonbrook crawl with hostile Defias highwaymen, thieves, and outlaws who attack anyone daring to trespass on their territory.",al={"is it safe","enemies in cooper residence","danger here"}}},ang={["faction:Alliance"]="The ruined home stands as a quiet indictment of Stormwind's neglect, showing what happens to ordinary kingdom subjects when the crown abandons its frontier settlements.",["race:Human"]="For humans walking through Moonbrook, homes like the Cooper Residence illustrate the tragic collateral damage wrought by the bitter dispute between the Stormwind nobility and the Stonemasons."},kw={"cooper family","cooper residence","defias","dusty journal","moonbrook","the moonbrook times","westfall"},rel={"subzone:moonbrook","zone:westfall","topic:alliance"},src={"Cooper Residence"}}
E["subzone:dagger-hills"] = {t="subzone",n="Dagger Hills",z="westfall",s="The Dagger Hills form a rugged ridge rising across southern Westfall, directly behind the blighted town of Moonbrook. Long neglected by the crown, this rocky highland serves as a hostile hideout for cutthroats, bandits, and creeping terrors that threaten the surrounding plains.",h="The Dagger Hills form a rugged ridge rising across southern Westfall, directly behind the blighted town of...",sec={{t="A Bandit Haven",b="Rising high above the dilapidated settlement of Moonbrook, the Dagger Hills mark the jagged southern reaches of Westfall. Stripped of official royal patrols from Stormwind, this arid highland has become a natural fortification for the Defias Brotherhood. Knuckledusters, pathstalkers, and highwaymen lurk among the rocky crests and scrub, ambushing unwary travelers and keeping watch over the approaches to their strongholds below.",sp=0},{t="Shadows on the Ridge",b="Beyond mortal outlaws, the Dagger Hills carry an eerie reputation under cover of darkness. The unsettling specter Leprithus, a wandering ghoul, has been sighted stalking the desolate heights when the sun dips. Aside from wandering outlaws and lingering undead, the only resident willing to brave the ridge is Grimbooze Thunderbrew, a dwarven brewer who sets up his distilling equipment in the rugged wilderness regardless of the nearby dangers.",sp=0}},faq={{q="Where are the Dagger Hills located?",a="The Dagger Hills form the high, rocky southern border of Westfall, standing directly behind the abandoned settlement of Moonbrook.",al={"dagger hills location","where is dagger hills","how to get to dagger hills"}},{q="Who controls the Dagger Hills?",a="The Defias Brotherhood maintains a heavy presence across the ridge, deploying highwaymen, pathstalkers, and knuckledusters to guard the southern hills.",al={"dagger hills defias","who lives in dagger hills","enemies in dagger hills"}},{q="Why is a dwarf brewing ale out here?",a="Grimbooze Thunderbrew has set up his distilling works in these lonely heights to craft his potent dwarven brews, braving bandits and beasts alike in the name of good drink.",al={"grimbooze westfall","dwarf in dagger hills","grimbooze thunderbrew lore"}},{q="What is Leprithus?",a="Leprithus is an infamous ghoul known to roam the crags of the Dagger Hills, terrifying any travelers or bandits unfortunate enough to run across it in the dark.",al={"leprithus spawn","ghoul in dagger hills","dagger hills undead"}}},ang={["faction:Alliance"]="The hills represent the utter breakdown of law in southern Westfall, where Gryan Stoutmantle's People's Militia must fight to reclaim ground surrendered by Stormwind's absence.",["race:Dwarf"]="The solitary presence of Grimbooze Thunderbrew on this exposed ridge shows the sheer stubbornness of dwarven brewers searching for undisturbed space to perfect their craft."},kw={"dagger hills","defias","grimbooze","leprithus","moonbrook","thunderbrew","westfall"},rel={"subzone:moonbrook","zone:westfall","npc:grimbooze-thunderbrew","quest:12","quest:117"},src={"Dagger Hills"}}
E["subzone:dead-acre"] = {t="subzone",n="Dead Acre",z="westfall",s="The Dead Acre is a ruined, smoldering farmstead in southeastern Westfall near the river bridge to Duskwood. Burned to ash by the Defias Brotherhood during their uprising across the countryside, the blackened fields are now abandoned by people and stalked by rogue harvest golems.",h="The Dead Acre is a ruined, smoldering farmstead in southeastern Westfall near the river bridge to Duskwood.",sec={{t="Ashes on the Border",b="Situated just north of the road linking Sentinel Hill to Duskwood, the Dead Acre was once a productive homestead among the breadbasket farms of Westfall. When the Defias Brotherhood rose in revolt and drove out the local landowners, this farm met a violent end. The homestead and its surrounding crops were put to the torch, leaving behind scorched timber, smoking earth, and wandering mechanical Harvest Watchers that still reap the barren soil.",sp=0}},faq={{q="Why is this place called the Dead Acre?",a="The Defias Brotherhood burned the farmstead and its surrounding fields to the ground when taking control of Westfall. The farm earned its grim name from the blackened ruins and smoldering earth left in their wake.",al={"why dead acre","what happened to dead acre","why is it burned"}},{q="Why are mechanical Harvest Watchers wandering here?",a="Like many farms across Westfall, the mechanical reapers built to tend the crops were left behind when the settlers fled or died. Corrupted or left without caretakers, the automated Harvest Watchers continue to endlessly patrol the burned-out fields, attacking anyone who draws near.",al={"harvest golems dead acre","why are there golems","harvest watchers"}},{q="Where is the Dead Acre located?",a="The Dead Acre sits in southeastern Westfall, nestled just north of the main road near the bridge that crosses into the shadowed borders of Duskwood.",al={"dead acre location","where is dead acre","how to find dead acre"}}},ang={["faction:Alliance"]="The Dead Acre stands as a grim reminder of Stormwind's neglect in Westfall, leaving loyal farmers defenseless against the violent depredations of the Defias Brotherhood."},kw={"burned farm","dead acre","defias","farm","harvest watcher","westfall"},rel={"zone:westfall","topic:defias-brotherhood","zone:duskwood","quest:65"},src={"Dead Acre"}}
E["subzone:deadmines"] = {t="subzone",n="Deadmines",z="westfall",s="Deep beneath the dusty ghost town of Moonbrook, the Deadmines are a sprawling underground labyrinth that once produced a third of Stormwind's gold reserves. Abandoned during the First War and long whispered to be haunted, the forgotten shafts have become the fortified headquarters of Edwin VanCleef and his rebellious Defias Brotherhood.",h="Deep beneath the dusty ghost town of Moonbrook, the Deadmines are a sprawling underground labyrinth that once...",sec={{t="A Vein of Gold and Blood",b="Before the First War, the Deadmines were the premier mining operation in human lands, rich in gold and sturdy Whitestone oak used for timber and structural supports. When the orcish Horde pushed north, the mines were abandoned in haste. Sir Anduin Lothar notably ventured into their treacherous depths to recover the sacred Tome of Divinity, surviving twenty months of captivity at the hands of subterranean ogres before being rescued. In the turmoil that followed the kingdom's fall, the shafts fell silent and gained a chilling reputation for being cursed.",sp=0},{t="VanCleef's Foundry",b="After the stonemasons' riot in Stormwind, the newly formed Defias Brotherhood seized the subterranean complex as their primary sanctuary. When Stormwind's Miners' League attempted to reopen the tunnels under Foreman Thistlenettle, Defias brigands ambushed the workers, bringing down shafts that left the slain miners wandering as restless undead. Today, protected by ogre enforcers and goblin tinkerers, the Defias have transformed the deep tunnels into an industrial war camp centered around a subterranean shipyard in Ironclad Cove.",sp=1}},faq={{q="How do you get into the Deadmines?",a="The main entrance is hidden inside the Defias Hideout, located in the ruined town of Moonbrook in southwestern Westfall. Winding downward through the basements brings you directly into the sprawling mine shafts.",al={"where is deadmines entrance","how to enter deadmines","deadmines location"}},{q="Why were the mines abandoned in the first place?",a="They were abandoned during the First War when the Horde overran the southern regions of the kingdom. With war raging and ogres moving into the depths, operations ceased, and the abandoned tunnels quickly developed a reputation for being haunted.",al={"why did deadmines close","why are deadmines abandoned"}},{q="What is the Defias Brotherhood building down here?",a="Deep within the flooded cavern of Ironclad Cove, Edwin VanCleef and hired goblin engineers are constructing an enormous ironclad juggernaught. VanCleef intends to sail this warship directly up the coast to bombard and besiege Stormwind City in retribution.",al={"what is in the deadmines","vancleef plan deadmines","ironclad cove ship"},sp=1},{q="Who are the undead wandering near the entrance tunnels?",a="They are the unfortunate workers of the Miners' League, led by Foreman Thistlenettle. When the League attempted to survey and reclaim the mine, Defias thugs ambushed them and collapsed the shafts, leaving the trapped miners to die and rise as restless ghouls.",al={"undead miners deadmines","foreman thistlenettle deadmines","why are there ghouls in deadmines"}},{q="What connection does Anduin Lothar have to the Deadmines?",a="During the First War, Sir Anduin Lothar journeyed deep into the Deadmines on an expedition to retrieve the sacred Tome of Divinity. He was captured by ogres residing in the caverns and held prisoner for nearly two years before an Alliance rescue party freed him.",al={"lothar deadmines","anduin lothar deadmines"}}},ang={["class:Paladin"]="The Deadmines hold holy significance for paladins: Sir Anduin Lothar ventured into its darkest chambers during the First War to recover the sacred Tome of Divinity from savage ogres.",["profession:Mining"]="Before the First War, these shafts were the crowning jewel of human mining, once accounting for a third of Stormwind's gold reserves before goblin machinery and Defias outlaws took over."},kw={"deadmines","defias","edwin vancleef","ironclad cove","juggernaught","lothar","moonbrook","thistlenettle","vancleef","westfall"},rel={"zone:westfall","topic:defias-brotherhood","npc:edwin-vancleef","subzone:ironclad-cove","subzone:moonbrook","subzone:defias-hideout","npc:wilder-thistlenettle","quest:65"},src={"Deadmines"}}
E["subzone:defias-hideout"] = {t="subzone",n="Defias Hideout",z="westfall",s="The Defias Hideout is an unassuming, derelict house situated on the southern edge of Moonbrook. Though it blends in with the surrounding ruined settlement, its upper floor conceals the primary overland entrance into the extensive subterranean network of the Deadmines.",h="The Defias Hideout is an unassuming, derelict house situated on the southern edge of Moonbrook.",sec={{t="A Gateway in Ruin",b="To the casual eye, the Defias Hideout looks like any other ransacked manor or farmhouse in Moonbrook, overrun by destitute vagrants and Defias thugs. However, its modest interior masks the nerve center of Edwin VanCleef's southern operations. Ascending to the upper floor reveals an opening that leads directly down into the sprawling labyrinth of the Deadmines. Because the Brotherhood focuses its manpower on guarding the perimeter of Moonbrook and laboring deep underground, the hideout itself is sparsely garrisoned, functioning more as a heavily monitored bottleneck than an active stronghold.",sp=0}},faq={{q="What is inside the Defias Hideout?",a="Inside the structure lies a staircase that leads up to a winding tunnel, serving as the overland entrance to the Deadmines. Aside from wandering vagrants and scattered bandits, the building itself is mostly bare, acting primarily as a guarded entryway.",al={"inside defias hideout","hideout entrance","what is here"}},{q="Why is the hideout relatively unguarded inside?",a="The Defias Brotherhood concentrates its fighting forces outside in the streets of Moonbrook to intercept intruders before they draw close, while the rest of their laborers and enforcers are busy working far below in the depths of the mines.",al={"why empty","where are the defias","why so few guards"}},{q="Where in Moonbrook is this building located?",a="The hideout is located on the southern edge of Moonbrook in southwestern Westfall, distinguished as a large, intact two-story building resting near the base of the mountains.",al={"how to find hideout","where is defias hideout","hideout location"}},{q="Who are the people lingering around the hideout?",a="The building and the surrounding town are populated by Defias bandits along with desperate vagrants who have gathered in Moonbrook, having fled poverty or aligned themselves with the Brotherhood out of necessity.",al={"who are vagrants","moonbrook vagrants","defias people"}}},ang={["class:Rogue"]="The hideout is a masterclass in clandestine defense: by disguising the gateway to a massive underground fortress within a nondescript ruined manor, the Defias keep their true scale hidden from casual Stormwind patrols.",["faction:Alliance"]="This decrepit estate serves as the front door to Edwin VanCleef's conspiracy, making it a critical staging ground for Alliance adventurers seeking to put an end to the Defias rebellion."},kw={"deadmines","defias","defias hideout","entrance","moonbrook","vancleef","westfall"},rel={"subzone:moonbrook","zone:deadmines","subzone:deadmines","topic:defias-brotherhood","zone:westfall"},src={"Defias Hideout"}}
E["subzone:demont-s-place"] = {t="subzone",n="Demont's Place",z="westfall",s="Demont's Place is a ruined homestead nestled in southwestern Westfall, just west of the forsaken town of Moonbrook. Once a working agricultural plot, the farm was driven to ruin alongside the rest of the region and claimed by the rogue agents of the Defias Brotherhood. Today, its weathered fences and empty fields stand as another casualty of the realm's fading prosperity.",h="Demont's Place is a ruined homestead nestled in southwestern Westfall, just west of the forsaken town of...",sec={{t="A Ruined Homestead",b="Situated within sight of Moonbrook and the rotting expanse of the Dead Acre, Demont's Place was once among the private family holdings feeding the Kingdom of Stormwind. Economic collapse and the sudden rise of outlaw brigands stripped the farm of its livelihood, forcing out its original caretakers. Much like its neighboring fields, the plot has degenerated into a rough hideout, overrun by outlaws using its weathered grounds as an extension of the Defias stronghold in Moonbrook.",sp=0},{t="The Grip of the Brotherhood",b="Because of its close proximity to Moonbrook, Demont's Place serves the Defias Brotherhood as an operational outpost on the outskirts of their regional center. Thugs, cutpurses, and displaced laborers linger among the fences and shattered structures, ambushing travelers who wander off the southern roads. Until Moonbrook is reclaimed and the outlaws broken, the ground remains far too dangerous for peaceful farming to ever return.",sp=0}},faq={{q="Where is Demont's Place located?",a="Demont's Place is situated in southwestern Westfall, immediately west of the abandoned town of Moonbrook and near the blighted fields of the Dead Acre.",al={"demont's place location","where is demonts place","demonts place map"}},{q="Who owns Demont's Place?",a="The farm likely belonged to a settler named Demont before the peasant unrest and economic troubles swept the countryside. Any original inhabitants have long since fled or perished, leaving the ruined acreage to brigands.",al={"who owns demonts place","who is demont","demont farm owner"}},{q="Who currently occupies the farm?",a="The homestead is currently infested by members of the Defias Brotherhood, who use the decrepit grounds as a peripheral staging point outside their base of operations in Moonbrook.",al={"who is at demonts place","what enemies are at demonts place","demonts place mobs"}},{q="Can the farm be restored to production?",a="Not under current conditions. With the Defias actively entrenched throughout southern Westfall and Stormwind unable to spare garrison troops, the homestead remains far too dangerous for ordinary tillers to rebuild.",al={"can you fix demonts place","is demonts place abandoned"}}},ang={["faction:Alliance"]="For Alliance travelers, Demont's Place is a grim reminder of how far order has retreated from Westfall, with former farmland actively held by Defias outlaws right under the kingdom's nose.",["class:Rogue"]="The sprawling ruined plots around Moonbrook, including Demont's Place, offer a stark look at the lawless network established by the Defias Brotherhood across the countryside."},kw={"dead acre","defias","defias brotherhood","demont's place","demonts place","farmstead","moonbrook","westfall"},rel={"zone:westfall","subzone:moonbrook","subzone:dead-acre"},src={"Demont's Place"}}
E["subzone:dust-plains"] = {t="subzone",n="Dust Plains",z="westfall",s="The Dust Plains form the dry, wind-scoured southern frontier of Westfall. Marked by arid ground and scarce scrub, the region is overrun by aggressive gnoll encampments and borders an old wizard's tower along its eastern rise.",h="The Dust Plains form the dry, wind-scoured southern frontier of Westfall.",sec={{t="A Barren Frontier",b="Stretching across southern Westfall, the Dust Plains mark the transition from troubled farmland to desolate wilderness. Unlike the plundered farmsteads to the north, this arid reach has long been surrendered to packs of feral gnolls who ambush travelers and challenge anyone venturing toward the coast or the nearby hills. On the eastern boundary sits Mortwake's Tower, a lonely magical retreat that offers no shelter from the beasts prowling the surrounding wastes.",sp=0}},faq={{q="Where are the Dust Plains located?",a="The Dust Plains occupy the southernmost portion of Westfall, lying south of the abandoned farmsteads and extending toward the cliffs and Mortwake's Tower on the east.",al={"dust plains location","where is dust plains","where dust plains"}},{q="What threats can travelers find in the Dust Plains?",a="The region is heavily populated by savage gnolls, who maintain crude camps throughout the dusty landscape and violently assault anyone who wanders near.",al={"what lives in dust plains","dust plains enemies","mobs in dust plains"}},{q="What is the tower on the eastern edge of the plains?",a="That is Mortwake's Tower, an old wizard's spire that overlooks the eastern verge of the Dust Plains.",al={"dust plains tower","eastern tower westfall","what is mortwake's tower"}},{q="Does the People's Militia hold any control over the Dust Plains?",a="No. The People's Militia is already stretched dangerously thin defending Sentinel Hill and the northern farms from the Defias Brotherhood, leaving the Dust Plains entirely in the hands of prowling gnolls.",al={"militia dust plains","is westfall guard here"}}},ang={["faction:Alliance"]="The Dust Plains represent another lawless fringe where Stormwind's neglect is starkly visible, forcing travelers and local defenders to fend off relentless gnoll packs without official reinforcement."},kw={"dust plains","gnolls","mortwake's tower","plains","southern westfall","westfall"},rel={"zone:westfall","subzone:mortwake-s-tower","topic:gnoll"},src={"Dust Plains"}}
E["subzone:furlbrow-s-pumpkin-farm"] = {t="subzone",n="Furlbrow's Pumpkin Farm",z="westfall",s="Furlbrow's Pumpkin Farm is an overrun homestead in northern Westfall, just off the main road from Elwynn Forest. Once a prosperous plot tended by Farmer Furlbrow and his wife Verna, the fields and farmhouse have been seized by the Defias Brotherhood and prowling harvest golems.",h="Furlbrow's Pumpkin Farm is an overrun homestead in northern Westfall, just off the main road from Elwynn...",sec={{t="A Harvest Lost",b="Situated near the northern border of Westfall, Furlbrow's Pumpkin Farm was once known for producing robust crops to feed the kingdom. That ended when the Defias Brotherhood swept across the countryside. Outlaws drove Farmer Furlbrow and his wife Verna from their land, leaving their fields overrun with mechanical harvest golems programmed to attack anyone approaching. With the farm buildings occupied by bandits and the fields prowled by renegade machinery, the rightful owners have been forced to camp along the roadside near the Jansen Stead, mourning the loss of their home and livelihood.",sp=0},{t="Defias Stronghold",b="The farm's fall illustrates the broader collapse of law and order across Westfall. With Stormwind's military garrison spread thin and unable to safeguard rural freeholders, the Defias Brotherhood easily claimed homesteads like Furlbrow's. Bandits use the property as an staging ground and camp while letting lethal harvest watchers guard the perimeter, leaving travelers on the nearby highway vulnerable to ambush.",sp=0}},faq={{q="Who owns this pumpkin farm?",a="The farm belongs to Farmer Furlbrow and his wife, Verna Furlbrow. However, they were forced off their property when outlaws seized the area, driving the couple to take refuge along the road near the Jansen Stead.",al={"who owns furlbrow farm","furlbrow owner","who lives here"}},{q="Why is the farm abandoned?",a="The farm was violently taken over by the Defias Brotherhood. They drove off the Furlbrows and stationed thugs in the buildings, using haywire mechanical harvest golems to guard the surrounding pumpkin patch.",al={"why is it abandoned","what happened to the farm","why are bandits here"}},{q="Where are the Furlbrows now?",a="Farmer Furlbrow and his wife have taken shelter along the main road just northeast of the farm, close to the Jansen Stead, stranded with their cart and belongings.",al={"where is farmer furlbrow","furlbrow location","find furlbrow"}},{q="Why are mechanical harvest golems attacking people here?",a="The mechanical harvesters once worked the fields, but the Defias Brotherhood reprogrammed or repurposed them into deadly sentries that attack any non-Defias trespassers on sight.",al={"harvest golems","why are golems hostile","who made the golems"}}},ang={["faction:Alliance"]="The overrun farm stands as a stark indictment of Stormwind's inability to protect its own heartland, leaving loyal tax-paying farmers defenseless against banditry."},kw={"defias","farm","furlbrow","harvest golem","jansen","pumpkin","verna","westfall"},rel={"npc:farmer-furlbrow","subzone:jansen-stead","zone:westfall","topic:defias-brotherhood","subzone:sentinel-hill","topic:stormwind-kingdom"},src={"Furlbrow's Pumpkin Farm"}}
E["subzone:gold-coast-quarry"] = {t="subzone",n="Gold Coast Quarry",z="westfall",s="The Gold Coast Quarry is an open-pit mine carved into the bluffs of southwestern Westfall. Once a prized source of stone, minerals, and gold for the Kingdom of Stormwind, it has been seized by the Defias Brotherhood to fuel their growing insurrection.",h="The Gold Coast Quarry is an open-pit mine carved into the bluffs of southwestern Westfall.",sec={{t="A Plundered Resource",b="Before the kingdom fell into neglect, the Gold Coast Quarry supplied raw building materials and precious gold to help rebuild Stormwind. When royal troops withdrew from Westfall and left the countryside unprotected, Defias highwaymen and renegade laborers took control of the diggings. The Brotherhood now patrols the terraced stone ramps, using the site's vantage over the coast and plundering whatever minerals remain to fund their rebellion.",sp=0}},faq={{q="What was the quarry originally used for?",a="The quarry was established by the Kingdom of Stormwind to extract stone, minerals, and gold from the coastal bluffs. Much of the stone quarried across Westfall helped support Stormwind's reconstruction following the Second War.",al={"why is there a quarry here","what did they mine here","gold coast purpose"}},{q="Who controls the Gold Coast Quarry right now?",a="The Defias Brotherhood controls the site. Their brigands, looters, and highwaymen patrol the terraced cliffs and mine entrances, keeping honest settlers away and extracting resources for their own illicit operations.",al={"who is at the quarry","who owns gold coast quarry","enemies at the quarry"}},{q="Why hasn't Stormwind sent guards to clear the quarry?",a="With King Varian Wrynn missing and the Stormwind House of Nobles unwilling to fund a standing military garrison in Westfall, the region has been abandoned by the crown. The local People's Militia must fight for control of places like the quarry on their own.",al={"why no stormwind army","where are the guards","why is it abandoned"}},{q="Where is the Gold Coast Quarry located?",a="It is carved into the cliffs along the southwestern coastline of Westfall, situated south of the Saldean and Alexston farmsteads and overlooking the Great Sea.",al={"quarry location","how to find gold coast quarry","where is it"}}},ang={["profession:Mining"]="Miners wandering Westfall will find rich stone faces and mineral veins cut along the quarry cliffs, though working them means fighting through entrenched Defias patrols.",["faction:Alliance"]="Reclaiming sites like the Gold Coast Quarry is vital to restoring order in Westfall, where the absence of royal garrisons has forced local volunteers to take up arms."},kw={"defias","defias brotherhood","gold coast quarry","mine","people's militia","quarry","stormwind","westfall"},rel={"zone:westfall","topic:defias-brotherhood","topic:stormwind-kingdom","quest:12","quest:65"},src={"Gold Coast Quarry"}}
E["subzone:jangolode-mine"] = {t="subzone",n="Jangolode Mine",z="westfall",s="Jangolode Mine is a rich mineral excavation located in the rolling hills of Westfall. Once a vital source of ore and raw materials for Stormwind City, the mine was overrun by bandits and now crawls with opportunistic kobolds.",h="Jangolode Mine is a rich mineral excavation located in the rolling hills of Westfall.",sec={{t="A Plundered Resource",b="Before Westfall fell into decline, the Jangolode Mine provided a steady flow of metals crucial to the reconstruction and supply of Stormwind City. As civil order deteriorated and the kingdom withdrew its garrisons, the Defias Brotherhood seized control of the site to feed their own operations. Following clashes that broke the bandits' hold over the shafts, scavenging kobolds surged into the tunnels, claiming the rich veins for themselves and fiercely defending their subterranean prize.",sp=0}},faq={{q="What is the Jangolode Mine?",a="It is an excavation site in Westfall that historically supplied Stormwind City with essential minerals and metal ore. With regional defense weakened, it fell into hostile hands.",al={"jangolode mine info","what is jangolode","jangolode westfall"}},{q="Who controls the mine right now?",a="Kobolds currently infest the underground shafts. Although the Defias Brotherhood previously drove out the original miners, the kobolds took advantage of the turmoil to occupy the tunnels.",al={"who is in jangolode mine","jangolode mobs","who lives in jangolode"}},{q="Why does Stormwind not reclaim the mine?",a="Stormwind is mired in political unrest and struggling to protect even its core borders. The kingdom lacks the troops to garrison Westfall's outlying mines, leaving the People's Militia and local adventurers to manage the threat.",al={"why doesnt stormwind clear jangolode","stormwind garrison westfall","why abandon the mine"}}},ang={["profession:Mining"]="The Jangolode Mine remains rich in basic copper and tin deposits, making it a lucrative stop for prospectors willing to fight past the subterranean pests.",["faction:Alliance"]="Reclaiming Westfall's resources is vital for stabilizing the kingdom, and driving out the vermin from Jangolode is one step toward restoring the region's prosperity."},kw={"defias brotherhood","jangolode","jangolode mine","kobold","stormwind","westfall"},rel={"zone:westfall","topic:kobold","topic:defias-brotherhood","zone:stormwind","topic:stormwind-kingdom"},src={"Jangolode Mine"}}
E["subzone:jansen-stead"] = {t="subzone",n="Jansen Stead",z="westfall",s="Jansen Stead is the northernmost farmstead in Westfall, situated just down the road from the bridge to Elwynn Forest. Like much of the surrounding breadbasket, the homestead has fallen out of peasant hands and is swarming with rogue mechanical Harvest Watchers and roving Defias bandits.",h="Jansen Stead is the northernmost farmstead in Westfall, situated just down the road from the bridge to Elwynn...",sec={{t="A Fallen Homestead",b="Positioned right past the Elwynn border, the Jansen Stead represents the harsh reality greeting anyone traveling westward into Westfall. Once a flourishing family farm feeding the kingdom, its rightful occupants have been driven away by the rising tide of unrest. In their place, hostile Harvest Watchers—malfunctioning clockwork automatons reprogrammed by the Defias Brotherhood—patrol the blighted fields alongside brigands. Its proximity to the main road makes it a prominent early hazard for couriers and travelers moving between Goldshire and Sentinel Hill.",sp=0}},faq={{q="Where is Jansen Stead located?",a="It is the very first farmstead on the right-hand side of the road as you cross the river bridge from Elwynn Forest into northeastern Westfall.",al={"jansen stead location","where is jansen stead","jansen farm westfall"}},{q="Who lives at Jansen Stead right now?",a="The farm's original residents have been displaced. Today, the overgrown fields and derelict farmhouse are occupied by hostile Harvest Watchers and footpads loyal to the Defias Brotherhood.",al={"who is at jansen stead","jansen stead inhabitants","mobs at jansen stead"}},{q="Why are mechanical scarecrows attacking people here?",a="The mechanical golems known as Harvest Watchers were originally built to tend crops and harvest wheat. The Defias Brotherhood has commandeered and reprogrammed them into deadly sentries to protect their illicit operations and drive out loyalist farmers.",al={"why harvest watchers attack","mechanical golems westfall","defias scarecrows"}},{q="Who is nearby asking for help?",a="Just south of the bridge near the entrance to Jansen Stead, Farmer Furlbrow and his wife Verna have set up camp by their broken wagon, having been forced off their own pumpkin patch down the road.",al={"quests near jansen stead","furlbrows location","who gives quests near elwynn bridge"}}},ang={["race:Human"]="For humans crossing over from the relative peace of Northshire and Elwynn, the ruin of Jansen Stead offers a harsh awakening to the economic crisis and banditry paralyzing Stormwind's rural heartland.",["faction:Alliance"]="The farmstead's fall underscores the failure of Stormwind's leadership to secure its own borders, leaving defenseless homesteaders at the mercy of outlaws within sight of Elwynn Forest."},kw={"defias","farm","furlbrow","harvest watcher","jansen","stead","westfall"},rel={"zone:westfall","zone:elwynn","topic:defias-brotherhood","npc:farmer-furlbrow","npc:verna-furlbrow","topic:stormwind-kingdom"},src={"Jansen Stead"}}
E["subzone:longshore"] = {t="subzone",n="Longshore",z="westfall",s="The Longshore is the expansive sandy coastline stretching along the entire western edge of Westfall. Despite its vast and scenic expanse, the shore is notoriously hazardous due to thick populations of aggressive murlocs and scattered wrecks off the coast.",h="The Longshore is the expansive sandy coastline stretching along the entire western edge of Westfall.",sec={{t="A Treacherous Coastline",b="Running the full western length of Westfall, the Longshore is one of the widest unbroken beaches in the Eastern Kingdoms. Yet it offers little peace to travelers. Coastal murlocs dominate the surf, led by notorious terrors like Old Murk-Eye, while the remnants of sunken vessels—including ruined elven destroyers—litter the shallows. Near the southern reaches, isolated settlers like Daphne Stilwell struggle against marauding Defias bandits, standing within sight of the Westfall Lighthouse across the water.",sp=0}},faq={{q="Why is the Longshore so dangerous?",a="The shoreline is infested with aggressive murloc tribes that roam unchecked across the sands, ambushing anyone who strays too close to the surf. In addition to the murlocs, the southern end of the beach is troubled by Defias bandits raiding coastal homesteads.",al={"why are there so many murlocs","longshore hazards","is longshore safe"}},{q="Who is Daphne Stilwell?",a="Daphne Stilwell is a lone settler maintaining an isolated farm on the southwestern stretch of the Longshore. Her vulnerable position makes her a frequent target for raids by the Defias Brotherhood, prompting the Knights of the Silver Hand to dispatch paladin initiates to her defense.",al={"daphne stilwell","stilwell farm","woman on the beach"}},{q="What are the shipwrecks lying off the coast?",a="Numerous wrecks lie submerged off the Longshore, ranging from merchant vessels to elven destroyers lost during past naval conflicts. These underwater ruins attract scavengers, murlocs, and adventurers seeking relics lost beneath the waves.",al={"elven destroyers westfall","sunken ships longshore","shipwrecks"}},{q="Why do druids visit the Longshore?",a="Alliance druids undertake a rite known as the Trial of the Sea Lion to master their aquatic form. Part of this trial requires seeking out a submerged chest near an offshore shipwreck along northwestern Longshore to retrieve the Half Pendant of Aquatic Endurance.",al={"druid quest longshore","strange lockbox westfall","half pendant of aquatic endurance"}}},ang={["class:Paladin"]="Paladins following the guidance of Duthorian Rall in Stormwind are sent south to Daphne Stilwell's homestead on Longshore, proving their valor by shielding an innocent farmer from Defias raiders.",["class:Druid"]="Alliance druids must brave the depths off the northwestern Longshore, locating a lockbox hidden near a sunken wreck to assemble the pendant required for their aquatic form."},kw={"aquatic form","daphne stilwell","longshore","murloc","old murk-eye","shipwrecks","westfall","westfall lighthouse"},rel={"zone:westfall","subzone:westfall-lighthouse","npc:daphne-stilwell","quest:1649","quest:31","npc:duthorian-rall","topic:murloc","topic:defias-brotherhood"},src={"Longshore"}}
E["subzone:molsen-farm"] = {t="subzone",n="Molsen Farm",z="westfall",s="Molsen Farm is an abandoned homestead located in the breadbasket region of Westfall. Once a fertile piece of farmland feeding Stormwind, it has fallen into ruin following the rise of the Defias Brotherhood and the prowling mechanical harvest golems left in their wake.",h="Molsen Farm is an abandoned homestead located in the breadbasket region of Westfall.",sec={{t="A Ruined Homestead",b="Like many homesteads across Westfall, Molsen Farm stands as a casualty of the kingdom's neglect and criminal uprising. When the Defias Brotherhood took control of the countryside, the resident farmers were driven out or worse, abandoning their crops and buildings. Now, instead of laborers gathering grain, hostile mechanical Harvest Watchers and wandering outlaws scour the untended fields, making the farm a hazard to anyone traveling through the province.",sp=0}},faq={{q="Why is Molsen Farm abandoned?",a="The farm was abandoned when the Defias Brotherhood swept across Westfall. Left without military protection from Stormwind, the homesteaders could not defend their land against bandits and rogue harvest golems, forcing them to flee their homes.",al={"why is it empty","who lived here","what happened to molsen farm"}},{q="Who controls the farm now?",a="The fields are overrun by malfunctioning Harvest Watchers and outlaws aligned with the Defias Brotherhood. No lawful citizens currently occupy or work the property.",al={"molsen farm enemies","who is at molsen farm"}},{q="Who was Molsen?",a="The farm takes its name from the local family that originally settled and tilled the land before the recent unrest drove Westfall's agrarian population into exile or poverty.",al={"who is molsen","molsen family"}}},ang={["faction:Alliance"]="The overgrown fields of Molsen Farm are a grim reminder of Stormwind's failing grasp on its rural territories and the pressing threat of the Defias Brotherhood."},kw={"abandoned farm","defias","harvest watcher","homestead","molsen farm","westfall"},rel={"zone:westfall","topic:defias-brotherhood","quest:65"},src={"Molsen Farm"}}
E["subzone:moonbrook"] = {t="subzone",n="Moonbrook",z="westfall",s="Once a bustling agricultural hub and mining town in southwestern Westfall, Moonbrook now stands as a lawless ghost town. The town has been completely overrun by the Defias Brotherhood, who use it as a fortified screen to hide their subterranean headquarters in the Deadmines.",h="Once a bustling agricultural hub and mining town in southwestern Westfall, Moonbrook now stands as a lawless...",sec={{t="A Fallen Town",b="Before the First War, Moonbrook was a vital community at the center of Westfall's breadbasket, supporting local farming families and the lucrative gold shafts of the Deadmines. Though it was razed by the Old Horde and painstakingly rebuilt after the Second War, its peace did not last. Neglected by the House of Nobles in Stormwind and stripped of military protection, the settlement could not resist the vengeful Stonemasons Guild when they fled into the wilderness. Bandits drove out the honest homesteaders, forcing citizens and teachers alike to flee toward Sentinel Hill and Elwynn Forest.",sp=0},{t="Defias Stronghold",b="Today, Moonbrook is effectively the surface garrison for Edwin VanCleef's rebellion. Red-masked thugs and rogue wizards patrol the streets and ransacked homes, while harvest golems patrol the surrounding weed-choked fields. The quiet residential streets conceal the entrance to the Deadmines beneath an unassuming barn on the town edge, making Moonbrook the most dangerous hotbed of treason in the kingdom.",sp=1}},faq={{q="Why is Moonbrook abandoned?",a="Moonbrook was abandoned by its peaceful residents when the Defias Brotherhood seized control of Westfall. Without the Stormwind Army to garrison the region, the townsfolk were forced out, and the bandits claimed the entire town as their own stronghold.",al={"what happened to moonbrook","why are there bandits in moonbrook","who took over moonbrook"}},{q="Where does the mine inside Moonbrook lead?",a="The mine entrance beneath the barn on the edge of Moonbrook leads into the Deadmines. Once an immense source of gold for Stormwind, the labyrinthine tunnels are now the secret redoubt and staging ground of the Defias Brotherhood.",al={"where are deadmines","what is under moonbrook","moonbrook mine entrance"}},{q="Who used to live here before the bandits?",a="Moonbrook was once populated by miners, farmers, and tradespeople who supported Westfall's agriculture. Notable former residents included Stalvan Mistmantle, who briefly served as the headmaster of the local Moonbrook Schoolhouse before the bandits overran the town.",al={"moonbrook residents","who lived in moonbrook","stalvan mistmantle school"}},{q="Does Stormwind plan to reclaim the town?",a="Stormwind's court has repeatedly refused to send royal troops to liberate Moonbrook or the surrounding farms, claiming resources are stretched thin. The local defense is left entirely to the volunteer People's Militia stationed at Sentinel Hill.",al={"will stormwind save moonbrook","why doesn't the army help moonbrook"}}},ang={["faction:Alliance"]="Moonbrook stands as a bitter reminder of the kingdom's neglect, where law-abiding subjects were abandoned to the Defias Brotherhood.",["class:Rogue"]="The alleys and ransacked homes of Moonbrook offer an unvarnished look at an entire outlaw syndicate operating in broad daylight."},kw={"deadmines","defias","moonbrook","schoolhouse","sentinel hill","vancleef","westfall"},rel={"zone:westfall","zone:deadmines","topic:defias-brotherhood","npc:edwin-vancleef","subzone:sentinel-hill","subzone:moonbrook-schoolhouse","quest:12","topic:house-of-nobles"},src={"Moonbrook"}}
E["subzone:moonbrook-schoolhouse"] = {t="subzone",n="Moonbrook Schoolhouse",z="westfall",s="Standing in the northwestern corner of Moonbrook, the Schoolhouse is a prominent building resembling a town hall with a small graveyard behind it. Originally erected to educate local children under headmaster Stalvan Mistmantle, it now stands derelict amidst the Defias occupation of Westfall.",h="Standing in the northwestern corner of Moonbrook, the Schoolhouse is a prominent building resembling a town...",sec={{t="A Beacon Fallen into Shadow",b="Before Moonbrook fell to ruin and bandits, the community invested in the education of its youth by raising this grand schoolhouse. Stalvan Mistmantle, an educated scholar from the north, was invited to Westfall specifically to serve as its headmaster. In those brighter days, the hall bustled with students rather than thieves, standing as proof of Moonbrook's former prosperity. Now, the schoolhouse lies abandoned to the elements and infested with outlaws, while the weathered headstones of its rear cemetery silently oversee Westfall's steady decay.",sp=0},{t="Secrets in the Floorboards",b="Though long abandoned by scholars, the schoolhouse holds the beginning of a grim mystery. An old footlocker left behind on the main floor contains unsent correspondence detailing Stalvan's departure from Westfall. Frustrated by meager pay and the isolation of rustic life, Mistmantle left his post in Moonbrook to seek fortune tutoring the nobility of Elwynn Forest—a fateful decision that set off a tragic chain of events across the southern kingdoms.",sp=1}},faq={{q="What was this building originally used for?",a="It served as Moonbrook's schoolhouse, constructed specifically to provide local children with a formal education. Its spacious design, resembling a town hall, reflects the ambition and pride the township held before its fall.",al={"why was it built","moonbrook school purpose","what is this place"}},{q="Who was Stalvan Mistmantle?",a="Stalvan Mistmantle was a learned scholar hired to be the schoolhouse's headmaster. Unhappy with his meager wages and country life in Moonbrook, he eventually resigned to pursue work as a private tutor for an aristocratic family in Elwynn Forest.",al={"who is stalvan","stalvan mistmantle lore","school headmaster"}},{q="Why is the schoolhouse abandoned now?",a="When Moonbrook collapsed under economic strife and the Defias Brotherhood took over southern Westfall, the town's civic institutions collapsed. The schoolhouse was abandoned along with the rest of the town and is now overrun by bandits.",al={"why abandoned","what happened to moonbrook school","who lives here now"}},{q="What can be found inside the schoolhouse today?",a="Alliance investigators tracking the history of Stalvan Mistmantle can find an old, dusty footlocker on the ground floor. Inside rests an unsent letter that reveals his reasons for leaving Moonbrook behind.",al={"footlocker location","loot in schoolhouse","quest item inside"}}},ang={["faction:Alliance"]="The derelict schoolhouse serves as a stark reminder of how far Westfall has fallen from the Crown's protection, turning centers of learning into hideouts for outlaws."},kw={"defias","footlocker","headmaster","mistmantle","moonbrook","schoolhouse","stalvan","westfall"},rel={"subzone:moonbrook","quest:66","zone:westfall","topic:alliance"},src={"Moonbrook Schoolhouse"}}
E["subzone:mortwake-s-tower"] = {t="subzone",n="Mortwake's Tower",z="westfall",s="Mortwake's Tower, commonly known as Klaven's Tower or simply the Defias Tower, is a fortified watchtower standing near the river in southeastern Westfall. Commanded by the rogue Klaven Mortwake, it serves as a critical waypoint for smuggling stolen goods across kingdom borders.",h="Mortwake's Tower, commonly known as Klaven's Tower or simply the Defias Tower, is a fortified watchtower...",sec={{t="A Smuggler's Stronghold",b="Perched on the borderlands north of the Dagger Hills, Klaven's Tower is a vital hub for Defias Brotherhood operations in southern Westfall. Together with Jerod's Landing across the river in Elwynn Forest, the site acts as a receiving post and staging ground for contraband plundered from the Redridge Mountains. Its commanding vantage over the waterways allows the Brotherhood to slip supplies past Kingdom patrols, shielding their logistical network from the crown's eyes.",sp=0},{t="Fumes and Shadows",b="The tower is controlled by Klaven Mortwake, an alchemist and rogue obsessed with lethal concoctions. Mortwake spends his hours brewing exotic troll poisons within the tower's confines, churning thick, noxious fumes that permeate the upper chambers. While deadly to intruders, the vapors also dull the senses of Mortwake's own guards, providing an exploitable blind spot for stealth operatives sent by Stormwind's intelligence service, SI:7, who monitor the structure from nearby hills.",sp=1}},faq={{q="Who controls this tower?",a="The tower is held by Klaven Mortwake, a Defias rogue who oversees smuggling operations and conducts experiments with volatile poisons. A contingent of Defias sentries and patrollers guards the grounds under his command.",al={"who is mortwake","who is klaven","who lives in the tower"}},{q="Why is the tower important to the Defias Brotherhood?",a="It serves as a primary logistical relay for stolen goods moving into Westfall. Smuggled cargo from the Redridge Mountains is transported across Elwynn Forest, routed past Jerod's Landing, and funneled through this tower to supply the Brotherhood's wider rebellion.",al={"defias tower purpose","what is this tower used for","why is the tower here"}},{q="Why is SI:7 watching this place?",a="Stormwind intelligence, led by Master Mathias Shaw, keeps the site under close surveillance due to Mortwake's lethal poison-crafting and the tower's central role in Defias supply routes. Operatives like Amber Kearnen scout the perimeter to assess Brotherhood movements and seize valuable intelligence.",al={"si7 mortwake tower","amber kearnen tower","why is stormwind watching"}},{q="What are the fumes lingering inside the tower?",a="The haze inside stems from Klaven Mortwake's ongoing experiments with exotic troll poisons. The fumes are dangerous to inhale, though their heavy scent also dulls the senses of the Defias guards garrisoned inside, leaving them vulnerable to skilled infiltrators.",al={"poison tower westfall","tower fumes","klaven poison"}}},ang={["class:Rogue"]="For rising rogues trained in Stormwind, Klaven's Tower is a rite of passage: SI:7 directs operatives here to infiltrate Mortwake's stronghold, test their lockpicking and stealth skills, and master the dangerous craft of virulent poisons.",["faction:Alliance"]="Nestled near the borders of Elwynn, Westfall, and Redridge, this Defias stronghold demonstrates how deeply the brotherhood has compromised the kingdom's interior riverways and trade routes."},kw={"amber kearnen","dagger hills","defias tower","klaven mortwake","klaven's tower","mortwake's tower","si:7","troll poison","westfall"},rel={"quest:2359","npc:amber-kearnen","quest:2300","subzone:jerod-s-landing","zone:westfall","zone:redridge","subzone:dagger-hills","topic:troll"},src={"Mortwake's Tower"}}
E["subzone:raging-chasm"] = {t="subzone",n="Raging Chasm",z="westfall",s="In the year 25 ADP, the tranquil western plains between the Alexston and Molsen farmsteads remain uninterrupted rolling farmland. The Raging Chasm is an anomaly not found in Westfall's current landscape, existing solely in tales of far-flung cataclysms and elemental upheavals that have not touched the kingdom.",h="In the year 25 ADP, the tranquil western plains between the Alexston and Molsen farmsteads remain...",sec={{t="Untorn Ground",b="Travelers wandering western Westfall today will find no gaping sinkhole between the Alexston and Molsen homesteads. The region is instead defined by golden fields, dusty wagon ruts, and rogue Harvest Golems. While whispers occasionally tell of unstable leylines or cataclysmic fissures tearing through the soil, Westfall's bedrock currently holds firm against the sea winds.",sp=0}},faq={{q="Where is the Raging Chasm located in Westfall?",a="You will not find the Raging Chasm anywhere in Westfall today. The ground between the Alexston and Molsen farms remains unriven, covered in the dry grasses and abandoned crops typical of the province.",al={"raging chasm location","where is raging chasm","sinkhole westfall"}},{q="Why do some records mention a giant rift of energy here?",a="Such accounts describe a violent disaster that simply has not occurred. In the present era, no magical beams or floating earthen vortexes breach the skies of western Westfall.",al={"energy beam westfall","chasm vortex","giant hole westfall"}},{q="Are there any oozes or slimes infesting the western plains?",a="The countryside is plagued by roving Defias bandits, wild beasts, and mechanical harvest reapers, but unnatural Chasm Slimes are entirely absent from the region.",al={"chasm slimes","westfall oozes"}}},ang={["faction:Alliance"]="For Alliance travelers, the western lands of Westfall remain intact farmland, troubled only by the Defias Brotherhood rather than subterranean tears or elemental energy pillars."},kw={"alexston farm","chasm","molsen farm","raging chasm","sinkhole","westfall"},rel={"zone:westfall","subzone:molsen-farm","topic:stormwind-kingdom"},src={"Raging Chasm"}}
E["subzone:saldean-s-farm"] = {t="subzone",n="Saldean's Farm",z="westfall",s="Saldean's Farm is the only homestead in Westfall that has not been completely overrun and abandoned to the Defias Brotherhood. Held by the stubborn Farmer Saldean and his wife Salma, the farmhouse remains a rare safe haven amid the region's turmoil.",h="Saldean's Farm is the only homestead in Westfall that has not been completely overrun and abandoned to the...",sec={{t="A Beacon in the Dust",b="While neighboring lands fell to banditry and mechanical sabotage, the Saldean family refused to abandon their soil. Farmer Saldean and his wife Salma have stayed on their homestead, offering hot food and a kind word to passing travelers. Despite their resilience, the fields remain plagued by rogue harvest golems deployed across the plains, forcing the family to stay close to the farmhouse walls.",sp=0},{t="Holding the Line",b="Because the Stormwind crown has largely neglected Westfall, law enforcement here is thin. A handful of Sentinel Hill and Stormwind guards patrol the periphery, but the farm survives primarily through sheer grit and the aid of passing travelers. For the Saldeans, Salma's famous Westfall stew and goretusk liver pie and the shelter of their farmhouse are small comforts against the ever-present threat of the Defias.",sp=0}},faq={{q="Why is this farm still standing when the others fell?",a="Farmer Saldean and his wife simply refused to pack up and flee when the Defias Brotherhood swept through Westfall. Though hostile harvest golems prowl their crops, the family stubbornly defends the immediate perimeter with the help of passing militia and adventurers.",al={"why not overrun","saldean farm survival","how is the farm alive"}},{q="Who are all the people gathered around the house?",a="The farm's residents are Farmer Saldean and his wife Salma; anyone else you find there is likely a passing traveler, as the couple welcome visitors and the adventurers willing to help them with the dangers plaguing their fields.",al={"refugees at saldean","homeless westfall","orphans at farm"}},{q="Why are mechanical golems attacking the fields?",a="The Defias Brotherhood repurposed the region's mechanical harvest reapers and golems into deadly sentries. They roam the fields attacking anyone who attempts to cultivate or clear the land.",al={"harvest golems","why are robots in crops","mechanical scarecrows"}},{q="Is the Stormwind Army protecting the farm?",a="Official military presence is practically nonexistent. A few scattered guards from Sentinel Hill and Stormwind provide minimal watch, but the crown has largely left Westfall's defense to local initiative.",al={"stormwind military presence","sentinel hill guards here","guard support"}}},ang={["faction:Alliance"]="Saldean's Farm represents the raw, failing edge of the kingdom's frontier, exposing how deeply ordinary citizens suffer when Stormwind's leadership is distracted.",["profession:Cooking"]="Salma Saldean is renowned among travelers for turning scavenged Westfall ingredients into hearty, lifesaving dishes like Goretusk Liver Pie."},kw={"farmer saldean","halfway house","harvest golem","refugees","saldean","salma saldean","westfall"},rel={"npc:farmer-saldean","npc:salma-saldean","zone:westfall","subzone:sentinel-hill","topic:defias-brotherhood","topic:stormwind-kingdom","topic:stormwind-guard","quest:65"},src={"Saldean's Farm"}}
E["subzone:sentinel-hill"] = {t="subzone",n="Sentinel Hill",z="westfall",s="Sentinel Hill is the primary bastion of the Alliance in Westfall, serving as the command center for the People's Militia. Surrounded by overgrown fields, scavenging gnolls, and hostile outlaws, this fortified rise is the only secure foothold for lawful citizens in the region.",h="Sentinel Hill is the primary bastion of the Alliance in Westfall, serving as the command center for the...",sec={{t="A Bastion in the Dust",b="Perched on high ground in central Westfall, Sentinel Hill stands as a vital sanctuary in an otherwise lawless territory. It features a barracks-style inn, a gryphon roost connecting travelers to Stormwind and beyond, a forge, and a lumber mill, all anchored by the imposing Sentinel Tower. While the surrounding lands have fallen to banditry and ravenous beasts, the encampment maintains a fragile perimeter where travelers, beleaguered farmers, and recruits can regroup under the watchful eyes of veteran defenders.",sp=0},{t="Heart of the Militia",b="With the royal army detained in Stormwind and unable to spare soldiers to protect outlying territories, Gryan Stoutmantle established the People's Militia directly upon this hill. From here, volunteer fighters organize scouts, coordinate strikes against the Riverpaw gnolls, and investigate the organized banditry tearing through Westfall's abandoned farmsteads. Sentinel Hill is neither an opulent fort nor a comfortable refuge, but a working frontline camp determined to reclaim the kingdom's former breadbasket.",sp=0}},faq={{q="Why hasn't Stormwind sent soldiers to defend Sentinel Hill?",a="With King Varian Wrynn missing and resources spread thin across the realm, Stormwind's regency has largely abandoned the western provinces to their own devices. Local citizens and veterans had to form the People's Militia themselves to hold Sentinel Hill and protect what remains of Westfall.",al={"why no stormwind guards","where is stormwind army","why militia here"}},{q="Who is in charge of Sentinel Hill?",a="Gryan Stoutmantle commands the People's Militia from the base of Sentinel Tower. He coordinates local defense, gathers intelligence on surrounding threats, and directs visiting adventurers against the gnolls and highwaymen encroaching on the settlement.",al={"who leads sentinel hill","sentinel hill commander","gryan stoutmantle"}},{q="What threats actively endanger the hill?",a="The encampment faces constant pressure from aggressive Riverpaw gnolls roaming the western plains, as well as the insidious, coordinated sabotage of the Defias Brotherhood lurking throughout the abandoned farms.",al={"what attacks sentinel hill","sentinel hill enemies","who is attacking"}},{q="What services are available here for travelers?",a="Sentinel Hill provides a full set of frontier accommodations: a gryphon master offering travel to Stormwind City and other Alliance outposts, an innkeeper, a mailbox, trade supply vendors, and repair facilities around the local forge.",al={"sentinel hill amenities","sentinel hill flight path","is there an inn here"}}},ang={["faction:Alliance"]="Sentinel Hill is your only fortified outpost and supply hub in Westfall, anchoring the Alliance's presence against outlaws and raiders.",["race:Human"]="Seeing Westfall's farmers forced to raise their own militia here reflects the kingdom's deepening crisis while the throne remains vacant."},kw={"gryan stoutmantle","gryphon roost","peoples militia","riverpaw gnolls","sentinel hill","sentinel tower","westfall"},rel={"subzone:sentinel-tower","zone:westfall","npc:gryan-stoutmantle","topic:defias-brotherhood","subzone:gryphon-roost","zone:stormwind","topic:gnoll","quest:65"},src={"Sentinel Hill"}}
E["subzone:sentinel-tower"] = {t="subzone",n="Sentinel Tower",z="westfall",s="Sentinel Tower crowns the apex of Sentinel Hill, standing as the primary vantage point and headquarters for defenders in Westfall. From its heights, Gryan Stoutmantle and the People's Militia organize their desperate defense against bandits, gnolls, and the growing shadow of the Defias Brotherhood.",h="Sentinel Tower crowns the apex of Sentinel Hill, standing as the primary vantage point and headquarters for...",sec={{t="Watch over the Wild West",b="Erected upon the crest of Sentinel Hill, Sentinel Tower is the military heart of unsettled Westfall. With Stormwind's official army largely absent and withholding aid, local volunteers and veterans banded together to create a central redoubt. The stone tower grants lookouts an unbroken view across the dusty plains, from the abandoned pumpkin patches to the misty shores, giving early warning when rogue highwaymen or gnoll raiding parties begin to prowl.",sp=0},{t="Headquarters of the Militia",b="The tower serves as the command post for Gryan Stoutmantle and the core of the local leadership. Surrounded by makeshift defenses, wounded refugees, and weary soldiers, it operates as both an administrative hub and an emergency shelter for homesteaders driven from their lands. Here, intelligence on the Defias Brotherhood is pieced together, coordinating volunteers into cohesive strikes against the syndicate that has choked the province into ruin.",sp=0}},faq={{q="Who is in charge at Sentinel Tower?",a="Gryan Stoutmantle directs operations from the tower. As head of the People's Militia, he coordinates the defense of Westfall's displaced farmers and manages the recruitment of willing adventurers.",al={"sentinel tower leader","who leads sentinel tower","who runs the tower"}},{q="Why is the tower so important to Westfall?",a="It is the only fortified garrison and lookout post left in the central plains. Because Stormwind has left Westfall largely undefended, the tower serves as the last organized bastion of order and safety for refugees in the region.",al={"why sentinel tower matters","purpose of sentinel tower"}},{q="Who stays in and around the tower?",a="You will find militia officers, sentinels keeping watch, quartermasters, and fleeing farmsteader families who have abandoned their ruined lands to seek shelter near its sturdy stone walls.",al={"who is at sentinel tower","sentinel tower occupants"}},{q="What threats are watched from the tower?",a="Sentinels monitor the movements of the Riverpaw gnolls, stray murlocs crawling inland from the coast, and above all, roaming highwaymen and brigands belonging to the Defias Brotherhood.",al={"sentinel tower enemies","what does the tower guard against"}}},ang={["faction:Alliance"]="Sentinel Tower represents the grit of ordinary Alliance subjects fighting for their homeland when the high lords in Stormwind have turned a blind eye.",["race:Human"]="For humans of the kingdom, the tower is a painful reminder that the agrarian breadbasket of Stormwind is barely holding together against homegrown rebellion."},kw={"defias","gryan stoutmantle","peoples militia","sentinel hill","sentinel tower","watchtower","westfall"},rel={"subzone:sentinel-hill","npc:gryan-stoutmantle","zone:westfall","topic:defias-brotherhood","quest:65","topic:alliance"},src={"Sentinel Tower"}}
E["subzone:stendel-s-pond"] = {t="subzone",n="Stendel's Pond",z="westfall",s="Stendel's Pond is a small, tainted body of water located southwest of Sentinel Hill in Westfall. Surrounded by prowling gnolls and marked by nearby graves, it remains one of the few fresh fishing spots in the parched countryside despite its sinister hazards.",h="Stendel's Pond is a small, tainted body of water located southwest of Sentinel Hill in Westfall.",sec={{t="A Dangerous Watering Hole",b="Tucked away southwest of Sentinel Hill, Stendel's Pond offers a quiet break from Westfall's dusty plains, though danger is never far. Gnolls roam the muddy banks, while scattered skeletons and a pair of lone graves suggest that either the waters or the beasts around it are fatal to careless travelers. Anglers still risk the trek for schools of sagefish and the elusive prize known locally as Stendel's Bane.",sp=0}},faq={{q="Where is Stendel's Pond located?",a="It lies southwest of Sentinel Hill in central Westfall, just off the dusty paths leading toward the southern reaches.",al={"stendel pond location","where is stendel's pond","find stendel pond"}},{q="What creatures lurk around the pond?",a="The pond's muddy shoreline is prowled by territorial Riverpaw gnolls who attack any wanderers approaching the water.",al={"who lives here","monsters at stendel's pond","stendel pond gnolls"}},{q="Why are there skeletons and graves by the shore?",a="The skeletons and two unnamed graves point to the area's deadly perils. Whether travelers fell prey to the gnolls or were poisoned by foul pond water remains an ominous mystery.",al={"whose graves are these","why skeletons","grave at pond"}},{q="Can you catch anything special while fishing here?",a="Yes. Beyond schools of sagefish, fishermen have been known to hook an exceptionally rare catch called Stendel's Bane.",al={"stendel pond fishing","fish in stendel's pond","stendel's bane"}}},ang={["profession:Cooking"]="The sagefish harvested from these murky waters are prized by cooks for recipes that bolster mana regeneration and physical focus.",["faction:Alliance"]="Located close to Sentinel Hill, the pond remains an uncontrolled threat on the People's Militia's southern perimeter due to gnoll encampments."},kw={"gnolls","graves","pond","sagefish","sentinel hill","stendel","stendel's bane","westfall"},rel={"zone:westfall","subzone:sentinel-hill","topic:gnoll"},src={"Stendel's Pond"}}
E["subzone:westfall-lighthouse"] = {t="subzone",n="Westfall Lighthouse",z="westfall",s="Perched on a rocky isle off the southwestern shore of Westfall, the Westfall Lighthouse once warned vessels away from the perilous shallows of the Great Sea. Today, its living keepers are gone, wiped out in a brutal assault led by the notorious murloc Old Murk-Eye, leaving only the spirit of Captain Grayson to watch over the flame.",h="Perched on a rocky isle off the southwestern shore of Westfall, the Westfall Lighthouse once warned vessels...",sec={{t="A Beacon in the Mist",b="Built along the treacherous southwestern bluffs of Westfall, the lighthouse long provided safe passage for ships navigating the coastline near Stormwind. However, as law and order collapsed across the region and royal patrols dwindled, coastal dangers surged unchecked. A family of keepers originally tended the beacon, but aggressive murloc tribes drove them inland. Though they bravely returned to relight the tower, the infamous murloc raider Old Murk-Eye rallied his kin for a second, merciless onslaught, butchering the family and extinguishing the beacon.",sp=0},{t="The Ghostly Watch",b="Following the tragedy, the beacon did not remain entirely abandoned. The specter of Captain Grayson now lingers on the rocky outcrop, bound to the site where he helplessly witnessed the family's demise. Unable to rest while the beacon is dark and the shore crawls with monsters, Grayson enlists passing adventurers to scour the beaches for fuel to keep the flame burning and to hunt down Old Murk-Eye to avenge the fallen keepers.",sp=1}},faq={{q="Why is the Westfall Lighthouse abandoned?",a="The human family that tended the lighthouse was driven out by local murlocs. When they returned to relight the beacon, Old Murk-Eye led a second raid that massacred the entire family before Captain Grayson's eyes.",al={"what happened to the keepers","who lived at the lighthouse","why is it ruined"}},{q="Who is Captain Grayson?",a="Captain Grayson is a ghost haunting the island outside the lighthouse. Bound by guilt and duty after witnessing the keepers' deaths, he tasks brave travelers with gathering oil to keep the beacon lit and hunting the coastal murlocs responsible.",al={"ghost at lighthouse","who is the ghost","captain grayson lore"}},{q="Who is Old Murk-Eye?",a="Old Murk-Eye is an unusually cunning and vicious murloc chieftain who stalks the Westfall shoreline. He rallied the coastal tribes to overrun the lighthouse and slaughter the keepers.",al={"murk eye","murloc boss","who killed the keepers"}},{q="Does the lighthouse still function?",a="The mechanical lantern still functions, projecting a sweeping beam of light across the ocean at night whenever travelers help Captain Grayson collect the fuel needed to maintain the fire.",al={"does the light turn on","beacon working"}}},ang={["faction:Alliance"]="The lighthouse stands as a stark symbol of Stormwind's failing reach, where isolated kingdom servants were abandoned to savage coastal beasts without military support."},kw={"beacon","captain grayson","coast","flame","lighthouse","murloc","old murk-eye","westfall"},rel={"npc:captain-grayson","quest:103","quest:104","topic:murloc","zone:westfall","topic:alliance","topic:pirate"},src={"Westfall Lighthouse"}}
E["topic:westfall-brigade"] = {t="topic",n="Westfall Brigade",z="westfall",s="The People's Militia, later known as the Westfall Brigade, is a grassroots defense force founded by Gryan Stoutmantle to protect Westfall's residents from the Defias Brotherhood. Operating out of Sentinel Hill, these volunteer defenders stand alone after royal aid from Stormwind City failed to arrive. They rely on local farmers and visiting adventurers to hold the line against rampant banditry.",h="The People's Militia, later known as the Westfall Brigade, is a grassroots defense force founded by Gryan...",sec={{t="A Region Abandoned",b="Westfall was once the breadbasket of the Kingdom of Stormwind, but recent unrest and economic turmoil caused the crown to withdraw regular army garrisons back to the capital. In the vacuum, the masked bandits of the Defias Brotherhood swept across the plains, seizing family homesteads, commandeering iron mines, and extorting local farmers. Facing lawlessness and seeing no sign of royal reinforcements, veteran warrior Gryan Stoutmantle rallied local citizens and retired soldiers to form the People's Militia.",sp=0},{t="Holding Sentinel Hill",b="Based at Sentinel Tower atop Sentinel Hill, the Militia maintains a tenuous perimeter across the region's main thoroughfares. Lacking professional military gear and sustained supplies, their protectors patrol dusty roads while Stoutmantle directs volunteers to thin the swelling ranks of Defias highwaymen, thieves, and pillagers. When neighboring regions like Redridge plead for mutual aid, the Militia is forced to decline, as sparing even a handful of men would spell the total ruin of Westfall.",sp=0},{t="Uncovering the Conspiracy",b="Through relentless scouting and outside help, the Militia unearths the true scale of the Defias threat. Rather than simple agrarian brigands, the Brotherhood operates under Edwin VanCleef, the former Guildmaster of the Stonemasons who rebuilt Stormwind. Operating from the subterranean depths of the Deadmines beneath Moonbrook, the Defias intend to overthrow the kingdom itself, leaving the embattled Militia as the only wall between the capital and open insurrection.",sp=1}},faq={{q="Why is the People's Militia fighting alone without Stormwind's army?",a="Stormwind City is paralyzed by political corruption and the disappearance of King Varian Wrynn. With royal troops withheld in the capital, local leaders like Gryan Stoutmantle took up arms to form a self-funded civilian force.",al={"why no stormwind guard","where is stormwind army","why westfall abandoned"}},{q="Who leads the People's Militia?",a="Gryan Stoutmantle, a seasoned human veteran, founded and directs the force from Sentinel Tower on Sentinel Hill.",al={"who leads westfall brigade","militia leader","gryan stoutmantle role"}},{q="What is the difference between the People's Militia and the Westfall Brigade?",a="They are the same organization. Founded as the People's Militia to defend Westfall from the Defias, the force later adopts the broader title of the Westfall Brigade as its military footprint and standing grow.",al={"peoples militia vs westfall brigade","is westfall brigade the militia"}},{q="Where is their headquarters located?",a="They operate out of Sentinel Hill, centered around the tall stone watchtower in the heart of Westfall.",al={"militia base","where is sentinel hill","westfall militia base"}},{q="Can the Militia help other troubled regions like Redridge?",a="No. When Magistrate Solomon of Lakeshire requested military reserves, Stoutmantle was forced to refuse because the Militia is barely clinging to survival against the Defias.",al={"why wont they help lakeshire","solomon request stoutmantle"}},{q="Who is the main enemy the Militia fights?",a="Their primary adversary is the Defias Brotherhood, a vast criminal syndicate of former masons, rogues, and highwaymen led by Edwin VanCleef.",al={"who are they fighting","militia enemy","defias enemy"},sp=1}},ang={["race:Human"]="The Militia showcases the grit and desperation of Stormwind's rural folk, forced to defend their own hearths when the royal court turns a blind eye.",["class:Warrior"]="Gryan Stoutmantle and his protectors embody pragmatic frontline leadership, making do with worn blades and makeshift armor to hold back overwhelming odds.",["faction:Alliance"]="Westfall's crisis highlights the dangerous cracks in the kingdom, showing Alliance heroes that peace in the core territories is fragile."},kw={"defias brotherhood","edwin vancleef","gryan stoutmantle","moonbrook","people's militia","sentinel hill","sentinel tower","westfall brigade"},rel={"npc:gryan-stoutmantle","subzone:sentinel-hill","zone:westfall","topic:defias-brotherhood","quest:12","npc:edwin-vancleef","subzone:deadmines","quest:143"},src={"Westfall Brigade"}}
E["zone:westfall"] = {t="zone",n="Westfall",z="westfall",s="Once the fertile breadbasket of the Kingdom of Stormwind, Westfall has collapsed into a windswept, neglected territory overrun by outlaws. Deprived of official crown support and military garrisons, its surviving homesteaders cling to their farms while the Defias Brotherhood tightens its grip from the abandoned mining town of Moonbrook.",h="Once the fertile breadbasket of the Kingdom of Stormwind, Westfall has collapsed into a windswept, neglected...",sec={{t="A Land Left Behind",b="For generations, Westfall fed the Kingdom of Stormwind. Its rolling pastures and wheat fields flourished until the aftermath of the Second War brought financial exhaustion and political neglect. When the kingdom poured its resources elsewhere and failed to maintain its garrisons, the territory grew fallow. Today, barren pastures, howling coastal gusts, rogue harvest golems, and raiding Riverpaw gnolls make daily survival a constant trial for the stubborn few who refuse to abandon their homesteads.",sp=0},{t="The Rise of the Brotherhood",b="Westfall's collapse accelerated when the Stonemasons Guild, denied payment for rebuilding Stormwind City, turned to open revolt. Outlawed and exiled under Edwin VanCleef, the stonemasons reconstituted themselves as the Defias Brotherhood. They claimed Westfall as their stronghold, burning stubborn farmers' fields, salting soil, and seizing abandoned mines. Operating out of the ghost town of Moonbrook, the Brotherhood now rules the majority of the countryside in all but name.",sp=0},{t="The People's Militia",b="With the House of Nobles ignoring Westfall's plight, local inhabitants took up their own defense. Based at the fortified post of Sentinel Hill, Gryan Stoutmantle organized the People's Militia—a volunteer force attempting to hold the line against gnolls and bandits. Lacking formal soldiers and supplies from Stormwind, the Militia relies on wandering adventurers to push back the Defias tide and protect the remaining farms.",sp=0},{t="The Deadmines Conspiracy",b="The true scale of the Defias threat lies concealed beneath the surface. Deep within the abandoned gold shafts of the Deadmines beneath Moonbrook, Edwin VanCleef has assembled an army of cutthroats, goblins, and renegades. Rather than simple banditry, the Brotherhood is constructing a massive ironclad juggernaut designed to sail up the coast and bombard Stormwind City directly.",sp=1}},faq={{q="Why are so many farms abandoned in Westfall?",a="Stormwind withdrew its military garrisons when upkeep became too expensive, leaving the region unprotected. Soon after, the Defias Brotherhood seized control of the countryside, driving off homesteaders, burning cropland, and reprogramming mechanical harvest watchers into lethal sentries.",al={"abandoned farms","why is westfall dead","why fallow"}},{q="Why does Stormwind not send troops to help Westfall?",a="The kingdom's treasury is strained, and the House of Nobles considers threats in other lands to be higher priorities. Furthermore, court manipulation has quietly starved Westfall of attention and supplies, forcing local residents to fend entirely for themselves.",al={"why no stormwind army","where are the guards","stormwind aid"}},{q="What is the People's Militia?",a="The People's Militia is a volunteer defense outfit organized by Gryan Stoutmantle at Sentinel Hill. Because the crown refused to deploy soldiers to Westfall, the remaining farmers and settlers banded together to fight off the Defias Brotherhood and the Riverpaw gnolls.",al={"peoples militia","sentinel hill militia","gryan stoutmantle army"}},{q="Who leads the Defias Brotherhood in Westfall?",a="Edwin VanCleef, the former guildmaster of the Stonemasons Guild who oversaw the rebuilding of Stormwind City. After a bitter dispute over payment resulted in riots and the death of Queen Tiffin, VanCleef led his workers into Westfall and turned to armed insurrection.",al={"defias leader","who leads defias","vancleef"}},{q="What is hidden inside Moonbrook?",a="Underneath an unassuming barn in Moonbrook lies the entrance to the Deadmines, an extensive abandoned gold mine that the Defias Brotherhood converted into an underground fortress and shipwright for their war against Stormwind.",al={"moonbrook secret","what is in deadmines","moonbrook mine"},sp=1},{q="Why are the mechanical scarecrows attacking people?",a="Originally built to tend the crops and scare away pests, these mechanical harvest watchers were captured and retrofitted by Defias-aligned goblin tinkerers to patrol fields and murder any trespassers.",al={"harvest golems attacking","harvest watchers","evil scarecrows"}}},ang={["race:Human"]="Westfall is a painful reflection of Stormwind's political decay; the farmers starving in the dirt were abandoned by the very nobility they toiled to feed.",["faction:Alliance"]="Without the People's Militia holding Sentinel Hill, the Defias Brotherhood would control the southern approaches straight to Elwynn Forest.",["class:Rogue"]="The shadow war across Westfall pits SI:7 spies directly against the street-smart scouts, thieves, and assassins of the Defias Brotherhood.",["profession:Cooking"]="The beleaguered homesteaders at Saldean's Farm make do with tough local beasts, teaching travelers to brew the hearty staple known as Westfall Stew."},kw={"deadmines","defias","harvest golem","militia","moonbrook","saldean","sentinel hill","stoutmantle","vancleef","westfall"},rel={"npc:gryan-stoutmantle","npc:edwin-vancleef","topic:defias-brotherhood","subzone:sentinel-hill","subzone:moonbrook","zone:deadmines","quest:12","quest:36"},m={levels="10-20"},src={"Westfall (Classic)","Westfall"}}
